const field = "mt-2 w-full rounded-lg border border-slate-400 bg-white p-3 text-slate-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-800";
const button = "rounded-full bg-[#123f60] px-6 py-3 font-semibold text-white hover:bg-[#092b44] focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-blue-800";

export function DraftResult({ text, name }: { text: string; name: string }) {
  const [notice, setNotice] = useState("");
  const [manualCopy, setManualCopy] = useState(false);
  const copyId = useId();
  async function copy() {
    try { await navigator.clipboard.writeText(text); setManualCopy(false); setNotice("Copied."); }
    catch { setManualCopy(true); setNotice("Copy is unavailable here. Select the complete draft below to copy it, or try downloading it. Your draft is still here."); }
  }
  function download() {
    let url: string | undefined;
    let anchor: HTMLAnchorElement | undefined;
    try {
      url = URL.createObjectURL(new Blob([text], { type: "text/plain;charset=utf-8" }));
      anchor = document.createElement("a"); anchor.href = url; anchor.download = name + ".txt";
      document.body.appendChild(anchor); anchor.click();
      setManualCopy(false); setNotice("Download requested. Check your downloads for the text file.");
    } catch {
      setManualCopy(true); setNotice("The download could not start. Select the complete draft below to copy it, or try again. Your draft is still here.");
    } finally {
      anchor?.remove();
      if (url) { const pending = url; setTimeout(() => URL.revokeObjectURL(pending), 1000); }
    }
  }
  return <div className="mt-6 rounded-xl border border-slate-300 bg-white p-5">
    <h3 className="text-xl font-semibold">Your draft</h3>
    <pre className="mt-4 whitespace-pre-wrap break-words font-sans text-base leading-7">{text}</pre>
    <div className="mt-5 flex flex-wrap gap-3"><button className={button} type="button" onClick={copy}>Copy draft</button><button className="rounded-full border border-slate-500 px-5 py-3 font-semibold" type="button" onClick={download}>Download draft</button></div>
    <p role="status" className="mt-3 text-sm">{notice}</p>
    {manualCopy ? <div className="mt-4"><label htmlFor={copyId} className="block font-semibold">Copy your complete draft</label><textarea id={copyId} className={field} readOnly rows={12} value={text} onFocus={event => event.currentTarget.select()} /></div> : null}
  </div>;
}

