'use client';
import { useState } from 'react';
import { checkOrdering, type Decision, type Ordering, type PracticeOption, type RecallQuestion } from '@/lib/content/clas-curriculum-practice';

type ChoiceProps = { id: string; question: string; scenario?: string; options: PracticeOption[] };

/**
 * One multiple-choice item: radio buttons, a check button, feedback for the chosen option and a
 * retry. Nothing is recorded; the choice lives only in component state.
 */
export function ChoiceQuestion({ id, question, scenario, options }: ChoiceProps) {
  const [selected, setSelected] = useState<number | null>(null);
  const [checked, setChecked] = useState(false);
  const [needsChoice, setNeedsChoice] = useState(false);
  const chosen = checked && selected !== null ? options[selected] : null;
  return (
    <fieldset className="clas-question">
      <legend>{question}</legend>
      {scenario && <p className="clas-question-scenario">{scenario}</p>}
      {options.map((option, n) => (
        <label key={n}>
          <input type="radio" name={id} value={n} checked={selected === n} onChange={() => { setSelected(n); setChecked(false); setNeedsChoice(false); }} />
          <span>{option.text}</span>
        </label>
      ))}
      <div className="clas-question-actions">
        {!checked
          ? <button type="button" onClick={() => { if (selected === null) setNeedsChoice(true); else setChecked(true); }}>Check my answer</button>
          : <button type="button" className="clas-study-secondary" onClick={() => { setChecked(false); setSelected(null); }}>Try again</button>}
      </div>
      <div className="clas-study-feedback" aria-live="polite">
        {needsChoice && !checked && <p>Choose one option, then check your answer.</p>}
        {chosen && <>
          <h3>{chosen.correct ? 'That is the stronger choice' : 'Not the strongest choice'}</h3>
          <p>{chosen.feedback}</p>
          <p>{chosen.correct ? 'You can choose another response to compare the reasoning.' : 'Try again and compare the reasoning for each option.'}</p>
        </>}
      </div>
    </fieldset>
  );
}

export function RecallSection({ questions, previousTitle, previousPart }: { questions: RecallQuestion[]; previousTitle: string; previousPart: number }) {
  if (!questions.length) return null;
  return (
    <section aria-labelledby="recall">
      <h2 id="recall">Before you watch: a quick recall from Part {previousPart}</h2>
      <p>Two short questions from “{previousTitle}”. Answer from memory; the feedback explains the reasoning. Nothing is scored or recorded.</p>
      {questions.map(q => <ChoiceQuestion key={q.id} id={`recall-${q.id}`} question={q.question} options={q.options} />)}
    </section>
  );
}

export function DecisionList({ decisions }: { decisions: Decision[] }) {
  if (!decisions.length) return null;
  return (
    <div className="clas-decisions">
      <h3>More decisions to practice</h3>
      <p>Each scenario is fictional and about your next decision. Check an answer to read why it is stronger or weaker; you can try again as often as you like.</p>
      {decisions.map(d => <ChoiceQuestion key={d.id} id={`decision-${d.id}`} question={d.question} scenario={d.scenario} options={d.options} />)}
    </div>
  );
}

/**
 * The learner builds an order by choosing the next step from numbered buttons; nothing is dragged.
 * Checking compares each position with the suggested order and allows another attempt.
 */
export function OrderingQuestion({ ordering }: { ordering: Ordering }) {
  const [chosen, setChosen] = useState<number[]>([]);
  const [result, setResult] = useState<ReturnType<typeof checkOrdering> | null>(null);
  const remaining = ordering.steps.map((_, i) => i).filter(i => !chosen.includes(i));
  const complete = chosen.length === ordering.steps.length;
  function reset() { setChosen([]); setResult(null); }
  return (
    <fieldset className="clas-ordering">
      <legend>{ordering.prompt}</legend>
      {ordering.scenario && <p className="clas-question-scenario">{ordering.scenario}</p>}
      <p className="clas-ordering-help">Choose the step you would do first, then the next. Use the numbered buttons; nothing needs to be dragged. You can remove the last step or start over at any time.</p>
      <div className="clas-ordering-chosen">
        <h3>Your order{chosen.length ? ` (${chosen.length} of ${ordering.steps.length})` : ''}</h3>
        {chosen.length
          ? <ol aria-live="polite">{chosen.map((step, position) => <li key={step}>{ordering.steps[step]}{result && <em className={result.matches[position] ? 'clas-order-match' : 'clas-order-miss'}> ({result.matches[position] ? 'in the suggested place' : 'not in the suggested place'})</em>}</li>)}</ol>
          : <p>No steps chosen yet.</p>}
      </div>
      {!complete && (
        <div className="clas-ordering-remaining">
          <h3>Choose step {chosen.length + 1}</h3>
          <ul>{remaining.map(i => <li key={i}><button type="button" className="clas-study-secondary" onClick={() => { setChosen([...chosen, i]); setResult(null); }}>Step {chosen.length + 1}: {ordering.steps[i]}</button></li>)}</ul>
        </div>
      )}
      <div className="clas-question-actions">
        {complete && !result && <button type="button" onClick={() => setResult(checkOrdering(chosen, ordering.correctOrder))}>Check my order</button>}
        {chosen.length > 0 && !result && <button type="button" className="clas-study-secondary" onClick={() => setChosen(chosen.slice(0, -1))}>Remove last step</button>}
        {chosen.length > 0 && <button type="button" className="clas-study-secondary" onClick={reset}>{result ? 'Try again' : 'Start over'}</button>}
      </div>
      <div className="clas-study-feedback" aria-live="polite">
        {result && <>
          <h3>{result.correct ? 'That matches the suggested order' : `Not yet: ${result.matches.filter(Boolean).length} of ${ordering.steps.length} steps are in the suggested place`}</h3>
          {ordering.feedback && <p>{ordering.feedback}</p>}
          {!result.correct && <p>Choose “Try again” to build the order once more.</p>}
        </>}
      </div>
    </fieldset>
  );
}

'use client';
import { useEffect, useMemo, useRef, useState } from 'react';
import type { CardDescription, ChapterKeyPoints } from '@/lib/content/clas-curriculum-practice';
import { chapterBoundaries, formatTime, type Chapter, type Cue } from '@/lib/learning/vtt';

type Props = {
  headingId: string;
  title: string;
  cues: Cue[];
  chapters: Chapter[];
  active: number;
  playing: boolean;
  keyPoints?: ChapterKeyPoints[];
  cardDescriptions?: CardDescription[];
  onSeek: (seconds: number) => void;
};

/**
 * Sentence-by-sentence transcript. The sentence being spoken carries aria-current and is kept in
 * view while the media plays; each sentence is a button that seeks to its start. Chapter titles
 * appear at the boundary, with that chapter's key points and card description.
 */
export function SyncedTranscript({ headingId, title, cues, chapters, active, playing, keyPoints = [], cardDescriptions = [], onSeek }: Props) {
  const list = useRef<HTMLOListElement>(null);
  const [expanded, setExpanded] = useState(false);
  const boundaries = useMemo(() => chapterBoundaries(cues, chapters), [cues, chapters]);
  const pointsFor = (chapter: string) => keyPoints.find(k => k.chapter === chapter)?.points ?? [];
  const descriptionFor = (chapter: string) => cardDescriptions.find(d => d.chapter === chapter)?.description;

  useEffect(() => {
    const container = list.current;
    if (!playing || !container || active < 0) return;
    const item = container.querySelector<HTMLElement>(`[data-cue="${active}"]`);
    if (!item || container.scrollHeight <= container.clientHeight) return;
    const top = item.offsetTop - container.offsetTop;
    if (top < container.scrollTop || top + item.offsetHeight > container.scrollTop + container.clientHeight) container.scrollTop = Math.max(0, top - container.clientHeight / 3);
  }, [active, playing]);

  if (!cues.length) return null;
  return (
    <section className="clas-transcript" aria-labelledby={headingId}>
      <div className="clas-transcript-head">
        <h3 id={headingId}>{title}</h3>
        <button type="button" className="clas-study-secondary" aria-expanded={expanded} onClick={() => setExpanded(e => !e)}>{expanded ? 'Shorten the transcript box' : 'Expand the transcript box'}</button>
      </div>
      <p className="clas-transcript-help">The sentence being spoken is highlighted. Choose a sentence or a chapter title to play from there.</p>
      <ol ref={list} className={expanded ? 'clas-transcript-list is-expanded' : 'clas-transcript-list'}>
        {cues.map((cue, index) => {
          const chapterIndex = boundaries.get(index);
          const chapter = chapterIndex === undefined ? null : chapters[chapterIndex];
          const points = chapter ? pointsFor(chapter.title) : [];
          const description = chapter ? descriptionFor(chapter.title) : undefined;
          return (
            <li key={`${cue.start}-${index}`} data-cue={index} className={index === active ? 'clas-transcript-cue is-active' : 'clas-transcript-cue'}>
              {chapter && (
                <div className="clas-transcript-chapter">
                  <h4><button type="button" onClick={() => onSeek(chapter.start)}>{chapter.title}<span className="sr-only"> (chapter, starts at {formatTime(chapter.start)})</span></button></h4>
                  {description && <p className="sr-only">Card shown: {description}</p>}
                  {points.length > 0 && <div className="clas-keypoints-inline"><p><strong>Key points</strong></p><ul>{points.map(point => <li key={point}>{point}</li>)}</ul></div>}
                </div>
              )}
              <button type="button" aria-current={index === active ? 'true' : undefined} onClick={() => onSeek(cue.start)}>
                <span className="clas-transcript-time" aria-hidden="true">{formatTime(cue.start)}</span>
                <span className="sr-only">{formatTime(cue.start)}: </span>
                <span className="clas-transcript-text">{cue.text}</span>
              </button>
            </li>
          );
        })}
      </ol>
    </section>
  );
}

'use client';
import { SourceLink } from "@/components/app-link";

import { useEffect, useMemo, useRef, useState, type SyntheticEvent } from 'react';
import type { Walkthrough } from '@/lib/learning/clas-walkthrough';
import { clearPosition, readPosition, readSpeed, resumable, writePosition, writeSpeed, type Speed } from '@/lib/learning/media-storage';
import { formatTime } from '@/lib/learning/vtt';
import { ChapterList } from './chapter-list';
import { pauseOtherMedia } from './download';
import { SpeedControl } from './media-player';

export type WalkthroughItem = { id: string; title: string; walkthrough: Walkthrough };
export const PLAYLIST_CHAPTER_ID = 'walkthrough-full-chapter';
export const walkthroughMediaId = (id: string) => `walkthrough:${id}`;

/**
 * One audio element that plays the nine chapter files in sequence. The learner starts playback; a
 * chapter that ends moves to the next one and keeps playing. Position and chapter are remembered on
 * this device, and the per-chapter position is shared with the lesson page's player.
 */
export function WalkthroughPlaylist({ items }: { items: WalkthroughItem[] }) {
  const audio = useRef<HTMLAudioElement>(null);
  const continueRef = useRef(false);
  const lastSaved = useRef(0);
  const [index, setIndex] = useState(0);
  const [time, setTime] = useState(0);
  const [speed, setSpeed] = useState<Speed>(1);
  const [resumedFrom, setResumedFrom] = useState<number | null>(null);
  const [status, setStatus] = useState('');
  const current = items[index];
  const total = useMemo(() => items.reduce((sum, item) => sum + item.walkthrough.durationSeconds, 0), [items]);
  const chapters = useMemo(() => items.map((item, n) => ({ title: `Part ${n + 1}: ${item.title}`, start: n, label: item.walkthrough.durationSeconds ? formatTime(item.walkthrough.durationSeconds) : '' })), [items]);

  // Browser storage is unavailable during server rendering; restore the chapter and speed afterwards.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => {
    setSpeed(readSpeed());
    const saved = readPosition(PLAYLIST_CHAPTER_ID);
    if (saved !== null && saved - 1 > 0 && saved - 1 < items.length) setIndex(saved - 1);
  }, [items.length]);

  // After the playlist advances, the new element starts only because the learner was already listening.
  useEffect(() => {
    if (!continueRef.current) return;
    continueRef.current = false;
    const el = audio.current;
    if (!el) return;
    el.playbackRate = speed;
    const started = el.play();
    if (started && typeof started.catch === 'function') started.catch(() => setStatus('Press play to continue with the next chapter.'));
  }, [index, speed]);

  if (!current) return null;
  const mediaId = walkthroughMediaId(current.id);

  function select(next: number, play: boolean) {
    if (next < 0 || next >= items.length) return;
    const wasPlaying = audio.current ? !audio.current.paused : false;
    continueRef.current = play || wasPlaying;
    setIndex(next);
    setTime(0);
    setResumedFrom(null);
    lastSaved.current = 0;
    writePosition(PLAYLIST_CHAPTER_ID, next + 1);
    setStatus('');
  }
  function onLoadedMetadata(event: SyntheticEvent<HTMLAudioElement>) {
    const el = event.currentTarget;
    el.playbackRate = speed;
    const position = resumable(readPosition(mediaId), el.duration);
    if (position !== null) { el.currentTime = position; setTime(position); setResumedFrom(position); }
  }
  function onTimeUpdate(event: SyntheticEvent<HTMLAudioElement>) {
    const now = event.currentTarget.currentTime;
    setTime(now);
    if (Math.abs(now - lastSaved.current) >= 3) { lastSaved.current = now; writePosition(mediaId, now); writePosition(PLAYLIST_CHAPTER_ID, index + 1); }
  }
  function onPause(event: SyntheticEvent<HTMLAudioElement>) {
    const now = event.currentTarget.currentTime;
    if (now > 0 && !event.currentTarget.ended) writePosition(mediaId, now);
  }
  function onEnded() {
    clearPosition(mediaId);
    setResumedFrom(null);
    if (index < items.length - 1) select(index + 1, true);
    else { clearPosition(PLAYLIST_CHAPTER_ID); setStatus('You have reached the end of the walkthrough.'); }
  }
  function changeSpeed(next: Speed) { setSpeed(next); writeSpeed(next); if (audio.current) audio.current.playbackRate = next; }
  function startOver() { if (audio.current) audio.current.currentTime = 0; setTime(0); setResumedFrom(null); clearPosition(mediaId); lastSaved.current = 0; }

  return (
    <div className="clas-player clas-player--audio clas-playlist">
      <p className="clas-playlist-now"><strong>Now playing:</strong> Part {index + 1} of {items.length}, {current.title}{current.walkthrough.durationSeconds ? ` (${formatTime(current.walkthrough.durationSeconds)})` : ''}{time > 0 ? ` · ${formatTime(time)}` : ''}</p>
      <audio key={current.id} ref={audio} controls preload="metadata" src={current.walkthrough.audio} aria-label={`Walkthrough, Part ${index + 1}: ${current.title}`}
        onPlay={event => { pauseOtherMedia(event.currentTarget); event.currentTarget.playbackRate = speed; }}
        onLoadedMetadata={onLoadedMetadata} onTimeUpdate={onTimeUpdate} onPause={onPause} onEnded={onEnded}
        onError={() => setStatus('This chapter could not be loaded. You can open it from its lesson page.')}>
        Your browser cannot play this audio. Each lesson page offers the same chapter with a transcript.
      </audio>
      <p>When a chapter ends, the next one follows{total ? `; the full walkthrough runs about ${Math.round(total / 60)} minutes` : ''}. You can pause at any time and return later.</p>
      <div className="clas-player-controls">
        <SpeedControl speed={speed} onChange={changeSpeed} />
        <button type="button" className="clas-study-secondary" onClick={() => select(index - 1, false)} disabled={index === 0}>Previous chapter</button>
        <button type="button" className="clas-study-secondary" onClick={() => select(index + 1, false)} disabled={index >= items.length - 1}>Next chapter</button>
        <p className="clas-player-status" role="status">
          {resumedFrom !== null && <>Resumed at {formatTime(resumedFrom)}, where you left off on this device. <button type="button" className="clas-study-link" onClick={startOver}>Start this chapter from the beginning</button> </>}
          {status}
        </p>
      </div>
      <ChapterList label="Walkthrough chapters" chapters={chapters} active={index} onSelect={n => select(n, false)} />
      <p><SourceLink href={current.walkthrough.audio}>Open this chapter's audio</SourceLink>{current.walkthrough.captions && <> · <SourceLink href={current.walkthrough.captions}>Download its captions</SourceLink></>} · <SourceLink href={`/learn/clas/curriculum/${current.id}`}>Open Part {index + 1} with the synced transcript</SourceLink></p>
    </div>
  );
}

