export function ClasPlanningWorksheet(){
 const [values,setValues]=useState<Record<string,string>>({});const [notice,setNotice]=useState("");const [fallback,setFallback]=useState(false);
 const text=clasPlanningText(values);
 async function copy(){try{await navigator.clipboard.writeText(text);setNotice("Working notes copied.");setFallback(false);}catch{setNotice("Copy was unavailable. Select and copy the notes below.");setFallback(true);}}
 function download(){let url:string|undefined;try{url=URL.createObjectURL(new Blob([text],{type:"text/plain;charset=utf-8"}));const link=document.createElement("a");link.href=url;link.download="cultural-language-access-working-notes.txt";document.body.appendChild(link);link.click();link.remove();setNotice("Your editable working-notes download is ready.");}catch{setNotice("The download could not start. Select and copy the notes below.");setFallback(true);}finally{if(url){const pending=url;setTimeout(()=>URL.revokeObjectURL(pending),1000);}}}
 return <section className="space-y-6" aria-labelledby="clas-notes-title"><h2 id="clas-notes-title" className="text-2xl font-semibold">Prepare your working notes</h2><p id="clas-privacy" className="notice">These notes are not saved or submitted. Download or copy what you want to keep before leaving. Use general service information and responsible roles; leave out names, health, case, personnel and confidential records.</p>{CLAS_PLANNING_FIELDS.map(field=><div className="space-y-2" key={field.id}><label htmlFor={"clas-"+field.id} className="block text-lg font-semibold">{field.label}</label><p id={"clas-"+field.id+"-help"} className="text-muted">{field.help}</p><textarea id={"clas-"+field.id} aria-describedby={"clas-"+field.id+"-help clas-privacy"} className="w-full rounded-lg border border-line p-3" rows={4} maxLength={3000} value={values[field.id]??""} onChange={event=>setValues(current=>({...current,[field.id]:event.target.value}))}/></div>)}<div className="flex flex-wrap gap-3"><button type="button" className="btn btn--primary" onClick={copy}>Copy working notes</button><button type="button" className="btn btn--light" onClick={download}>Download editable notes</button></div><p role="status">{notice}</p>{fallback&&<label className="block">Your working notes<textarea className="mt-2 w-full rounded-lg border border-line p-3" rows={14} readOnly value={text} onFocus={event=>event.target.select()}/></label>}</section>;
