  const [preparedDownload,setPreparedDownload]=useState<{format:"html"|"word"|"json";payload:string;name:string}|null>(null);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [tab, setTab] = useState<"prepare" | "analysis" | "gaps" | "practice">("prepare");
  const [gap, setGap] = useState(initialGap);
  const [gapError, setGapError] = useState("");
  const [gapResult, setGapResult] = useState<{ gap: number | null; targetMet: boolean | null; scenario: number | null; current:number|null;target:number|null } | null>(null);
  const [gapSnapshot,setGapSnapshot]=useState("");
  const [review, setReview] = useState<Record<string, { status: string; note: string }>>({});
  const resultHeading = useRef<HTMLHeadingElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(()=>()=>{document.getElementById("one-dsd-report-download")?.remove();},[]);

  useEffect(() => { const timeout = setTimeout(() => { try { setSavedAvailable(Boolean(localStorage.getItem(KEY))); } catch { /* Storage is optional. */ } },0); return () => clearTimeout(timeout); }, []);
  useEffect(() => {
    const controller=new AbortController();
    void fetch("/api/consultant/analysis",{signal:controller.signal}).then(async response=>{
      if(!response.ok) throw new Error("Connection check failed");
      const body=await response.json();
      setAvailability({analysisAvailable:body.analysisAvailable===true,researchAvailable:body.researchAvailable===true,analysisUnavailableReason:typeof body.analysisUnavailableReason==="string" ? body.analysisUnavailableReason.slice(0,1000) : undefined});
    }).catch(()=>{if(!controller.signal.aborted)setAvailability({analysisAvailable:false,researchAvailable:false});});
    return()=>controller.abort();
  },[]);
  useEffect(() => {
    if (!saving) return;
    timer.current = setTimeout(() => {
      const checked = draftSchema.safeParse({ request, analysis, analysisSources,researchNote, gap, review });
      if (!checked.success) { setMessage("Complete the required preparation fields before a draft can be saved."); return; }
      try { localStorage.setItem(KEY, JSON.stringify(checked.data)); setSavedAvailable(true); setMessage("Saved in this browser. Not shared or saved to the server."); }
      catch { setMessage("Browser saving is unavailable. Download a copy to keep your work."); }
    }, 600);
    return () => { if (timer.current) clearTimeout(timer.current); };
  }, [request, analysis, analysisSources,researchNote, gap, review, saving]);
  function invalidateAnalysis() { if (analysis) { setAnalysis(null); setAnalysisSources([]);setResearchNote(""); setMessage("Preparation changed. Run a new analysis so findings match the current material."); } }
  function update<K extends keyof AnalysisRequest>(key: K, value: AnalysisRequest[K]) { invalidateAnalysis(); setRequest(previous => ({ ...previous, [key]: value })); }
  function sourceUpdate(index: number, key: "title" | "text", value: string) { invalidateAnalysis(); setRequest(previous => ({ ...previous, sources: previous.sources.map((source, i) => i === index ? { ...source, [key]: value } : source) })); }
  function recover() {
    try {
      const value = localStorage.getItem(KEY);
      if (!value || value.length > 2000000) throw new Error("No supported saved draft was found.");
      const parsed = draftSchema.parse(JSON.parse(value));
      applyDraft(parsed); setMessage("Recovered your browser draft. Confirm the material before running another analysis.");
    } catch { setError("The saved draft could not be recovered. Your current work has not been replaced."); }
  }
  function download() {
    const checked = draftSchema.safeParse({ request, analysis, analysisSources,researchNote, gap, review });
    if (!checked.success) { setError("Add a title, question, source title and source text before downloading."); return; }
    prepareDownload("json",JSON.stringify(checked.data),"one-dsd-equity-analysis.json");
    setMessage("Working copy ready. If the download did not start, choose Save the prepared file. This copy is not password protected.");
  }
  function applyDraft(parsed:z.infer<typeof draftSchema>) {
    setRequest(parsed.request);setAnalysis(parsed.analysis);setAnalysisSources(parsed.analysisSources);setResearchNote(parsed.researchNote);setGap(parsed.gap);setReview(parsed.review);setGapResult(null);setConfirmed(false);setError("");
  }
  async function importDraft(file:File|undefined) {
    if(!file) return;
    if(file.size>2000000) {setError("Choose a downloaded analysis copy under 2 MB.");return;}
    try {const parsed=draftSchema.parse(JSON.parse(await file.text()));applyDraft(parsed);setMessage("Opened your downloaded working copy. Confirm its material before running another analysis.");}
    catch {setError("This file is not a supported working copy. Your current work has not been replaced.");}
  }
  async function upload(file: File | undefined, index: number) {
    if (!file) return;
    if(!confirmed){setError("Confirm that the material is public or deidentified before uploading.");return;}
    if (!/\.(txt|pdf|docx|pptx|png|jpe?g|webp|mp3|wav|m4a|mp4|webm)$/i.test(file.name) || file.size > 20*1024*1024) { setError("Choose a supported document, image, audio or video file no larger than 20 MB."); return; }
    const form=new FormData();form.append("file",file);form.append("publicMaterialConfirmed","true");
    const selectedSourceId=request.sources[index]?.id;if(!selectedSourceId)return;
    setUploading(true);setError("");setMessage("Reading the uploaded material…");
    const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),300000);
    try{
      const response=await fetch("/api/consultant/analysis/upload",{method:"POST",body:form,signal:controller.signal});
      const body=await response.json();
      if(!response.ok)throw new Error(typeof body.error==="string"?body.error:"This material could not be read. Your current work is unchanged.");
      const source=sourceSchema.parse(body.source);
      const combined=request.sources.reduce((sum,s)=>sum+(s.id===selectedSourceId?source.text.length:s.text.length),0);
      if(combined>200000)throw new Error("Use shorter excerpts or fewer sources so the total remains under 200,000 characters. Your current material is unchanged.");
      invalidateAnalysis();setRequest(previous=>({...previous,sources:previous.sources.map(s=>s.id===selectedSourceId?{...source,id:selectedSourceId}:s)}));
      setMessage(typeof body.note==="string"?body.note.slice(0,6000):"Material loaded. Review the extracted text before analyzing; formatting and non-text details may not be included.");
    }catch(cause){setError(controller.signal.aborted?"Reading this file took too long. Your current work is unchanged.":cause instanceof z.ZodError?"The extracted material could not be checked. Your current work is unchanged; use a shorter text excerpt instead.":cause instanceof Error?cause.message:"This material could not be read. Your current work is unchanged.");setMessage("");}
    finally{clearTimeout(timeout);setUploading(false);}
  }
  function reportInput():AnalysisReportInput{return {request,analysis,sources:analysis?analysisSources:request.sources,researchNote,gap,gapResult:gapSnapshot===JSON.stringify(gap)?gapResult:null,review};}
  function exportPayload(){return JSON.stringify({request,analysis,analysisSources,researchNote,gap,review,gapResult:gapSnapshot===JSON.stringify(gap)?gapResult:null});}
  function submitDownload(format:"html"|"word"|"json",payload:string){
    let frame=document.getElementById("one-dsd-report-download") as HTMLIFrameElement|null;
    if(!frame){frame=document.createElement("iframe");frame.id="one-dsd-report-download";frame.name="one-dsd-report-download";frame.title="Report download response";frame.hidden=true;frame.onload=()=>{try{const text=frame?.contentDocument?.body?.textContent;if(text){const result=JSON.parse(text);if(typeof result.error==="string"){setError(result.error.slice(0,1000));setMessage("");}}}catch{/* Attachment responses do not expose a document. */}};document.body.appendChild(frame);}
    const form=document.createElement("form");form.method="POST";form.action="/api/consultant/analysis/export";form.target=frame.name;form.hidden=true;
    for(const [name,value] of Object.entries({format,payload})){const field=document.createElement("input");field.type="hidden";field.name=name;field.value=value;form.appendChild(field);}
    document.body.appendChild(form);try{form.submit();}finally{form.remove();}
  }
  function prepareDownload(format:"html"|"word"|"json",payload:string,name:string){setPreparedDownload({format,payload,name});submitDownload(format,payload);}
  async function exportReport(format:"html"|"word"){
    setExporting(true);setError("");
    try{prepareDownload(format,exportPayload(),`one-dsd-analysis-report.${format==="html"?"html":"docx"}`);setMessage("Report download requested. If the browser did not save it, choose Save the prepared file. Keep the report somewhere appropriate; it is not password protected.");}
    catch{setError("The report download could not be requested. Your work is unchanged; download a working copy to keep it.");}finally{setExporting(false);}
  }
  async function shareReport(){
    const file=new File([analysisReportHtml(reportInput())],"one-dsd-analysis-report.html",{type:"text/html"});
    if(navigator.share&&navigator.canShare?.({files:[file]})){
      try{await navigator.share({files:[file],title:request.title||"One DSD equity analysis"});setMessage("The report was passed to your device’s sharing service. No public page or link was created.");}
      catch(cause){if(cause instanceof DOMException&&cause.name==="AbortError")setMessage("Sharing canceled. Your work is unchanged.");else{prepareDownload("html",exportPayload(),file.name);setMessage("Device sharing was unavailable. Choose Save the prepared file, then attach it using your usual sharing service.");}}
    }else{prepareDownload("html",exportPayload(),file.name);setMessage("This browser does not support sharing a report file. Choose Save the prepared file, then attach it using your usual sharing service.");}
  }
  async function analyze() {
    setError(""); setMessage("");
    if (!confirmed) { setError("Confirm that the material is public or deidentified before continuing."); return; }
    const checked = analysisRequestSchema.safeParse(request);
    if (!checked.success) {
      const field=checked.error.issues[0]?.path[0];
      setError(field==="title" ? "Give this work a title." : field==="question" ? "Enter the question you want to examine." : field==="goals" ? "Check the ADSA goals you selected. You may leave them blank when they do not apply." : field==="sources" ? "Give each source a title and a text excerpt. Use up to 12 sources and 200,000 characters in total." : "Check the preparation fields before continuing.");
      return;
    }
    setBusy(true);
    const controller=new AbortController();
    const timeout=setTimeout(()=>controller.abort(),180000);
    try {
      const response = await fetch("/api/consultant/analysis", { method: "POST", signal:controller.signal, headers: { "Content-Type": "application/json" }, body: JSON.stringify(checked.data) });
      const body = await response.json();
      if (!response.ok) throw new Error(typeof body.error === "string" ? body.error : "Analysis is unavailable. Your work is still here.");
      const sources=z.array(sourceSchema).min(1).max(12).parse(body.sources ?? checked.data.sources);
      const validated = validateAnalysisResponse(body.analysis, {...checked.data,sources});
      setAnalysisSources(sources);setResearchNote(typeof body.researchNote === "string" ? body.researchNote.slice(0,6000) : "");setAnalysis(validated); setTab("analysis"); setMessage("Analysis ready for your review. Check the evidence and revise the proposed actions.");
      setTimeout(() => resultHeading.current?.focus(), 0);
    } catch (cause) { setError(controller.signal.aborted ? "The analysis response did not arrive within three minutes. Your work is still here. You can try again; no automatic retry was made." : cause instanceof z.ZodError ? "The returned analysis could not be checked. Your preparation is still here; no new findings have been added." : cause instanceof Error ? cause.message : "Analysis is unavailable. Your work is still here."); }
    finally { clearTimeout(timeout);setBusy(false); }
  }
  function calculate() {
    setGapError(""); setGapResult(null);
    try {
      if(!gap.change.trim()) throw new Error("Enter a what-if change, including zero for no change.");
      if(gap.unit==="count" && gap.target.trim() && !Number.isSafeInteger(Number(gap.target))) throw new Error("A count target must be a whole number.");
      const numerator=gap.numerator.trim()?Number(gap.numerator):null;
      const denominator=gap.denominator.trim()?Number(gap.denominator):null;
      if(gap.unit==="percent" && ((numerator===null)!==(denominator===null))) throw new Error("Enter both the number meeting the measure and the total group size, or leave both blank if unknown.");
      const current=gap.unit==="percent" ? numerator===null||denominator===null ? null : numerator/denominator*100 : gap.value.trim()?Number(gap.value):null;
      const measure: AggregateMeasure = { label: gap.label, unit: gap.unit, value: current, ...(gap.unit==="percent"?{numerator,denominator}:{}), periodStart: reportingDate(gap.start), periodEnd: reportingDate(gap.end), sourceId: request.sources[0]?.id ?? "source-1" };
      const result = calculateGap(measure, gap.target.trim() ? Number(gap.target) : null, gap.direction);
      const scenario = calculateScenario(measure.value, Number(gap.change));
      if(gap.unit==="percent" && scenario.value!==null && scenario.value>100) throw new Error("This what-if change exceeds 100 percent. Use a smaller change or review the assumption.");
      setGapResult({ gap: result.gap, targetMet: result.targetMet, scenario: scenario.value,current:measure.value,target:gap.target.trim()?Number(gap.target):null });
      setGapSnapshot(JSON.stringify(gap));
    } catch (cause) {
      if(cause instanceof z.ZodError) {
        const issue=cause.issues[0];
        if(issue?.path.includes("periodStart") || issue?.path.includes("periodEnd")) setGapError("Enter valid reporting dates. The end date must be on or after the start date.");
        else if(issue?.path.includes("label")) setGapError("Give the measure a clear name before comparing it.");
        else if(issue?.path.includes("denominator") || issue?.path.includes("numerator") || gap.unit==="percent") setGapError("Enter the number meeting the measure and a total group size greater than zero. The first number cannot be larger than the total.");
        else setGapError("Enter a number of zero or more in the selected unit. Counts must be whole numbers.");
      } else setGapError(cause instanceof Error ? cause.message : "Check the measure and reporting dates.");
    }
  }
  function citations(entries: AnalysisResponse["findings"][number]["citations"]) {
    return entries.length ? <div className="space-y-2 border-t border-slate-300 pt-3"><h4 className="font-bold">Referenced evidence</h4>{entries.map((citation, index) => <blockquote key={index} className="border-l-4 border-slate-500 pl-3"><p className="whitespace-pre-wrap">{citation.excerpt}</p><p className="text-sm font-semibold">{analysisSources.find(source => source.id === citation.sourceId)?.title ?? "Source unavailable"}</p></blockquote>)}</div> : <p className="text-sm">No direct excerpt attached. Treat this as an interpretation or question requiring evidence.</p>;
  }
  return <div className="space-y-6 text-slate-900">
    <div className={`${surface} flex flex-wrap items-center justify-between gap-4`}>
      <div><h2 className="text-xl font-bold">From evidence to action</h2><p className="mt-1">DHS · ADSA · One DSD</p></div>
      <div className="flex flex-wrap gap-2"><button className="btn btn--light" disabled={busy || uploading || exporting} onClick={download}>Download working copy</button><button className="btn btn--light" disabled={busy || uploading || exporting} onClick={() => void exportReport("word")}>{exporting ? "Preparing report…" : "Download Word report"}</button><button className="btn btn--light" disabled={busy || uploading || exporting} onClick={() => void exportReport("html")}>Download HTML report</button><button className="btn btn--light" disabled={busy || uploading || exporting} onClick={() => void shareReport()}>Share report file</button>{savedAvailable && <button disabled={busy || uploading} className="btn btn--light" onClick={recover}>Recover browser draft</button>}<label className="btn btn--light">Open downloaded copy<input aria-label="Open downloaded analysis copy" type="file" accept=".json,application/json" className="max-w-48 text-sm" disabled={busy || uploading || exporting} onChange={event => void importDraft(event.target.files?.[0])} /></label></div>
      <div className="w-full space-y-2 text-sm">{preparedDownload && <p><button className="btn btn--light" onClick={()=>submitDownload(preparedDownload.format,preparedDownload.payload)}>Save the prepared file</button><span className="ml-3">{preparedDownload.name}</span></p>}<label className="flex items-start gap-2"><input type="checkbox" checked={saving} onChange={event => { setSaving(event.target.checked); setMessage(event.target.checked ? "Browser saving enabled for this workspace." : "Browser saving paused. Any earlier saved copy remains until you remove it."); }} />Keep a draft in this browser on this device</label><p>Use public material or remove private personal details first. Browser drafts and downloads are private working copies, not shared program records.</p>{savedAvailable && <button className="underline" onClick={() => { try { localStorage.removeItem(KEY); setSavedAvailable(false); setSaving(false); setMessage("Removed the saved browser copy. Your open work remains."); } catch { setError("The saved browser copy could not be removed."); } }}>Remove saved browser copy</button>}</div>
    </div>
    {error && <p role="alert" className="rounded-lg border border-red-700 bg-white p-4 text-red-800">{error}</p>}
    <p role="status" aria-live="polite" className="text-sm">{message}</p>
    <p className="text-sm">{availability===null ? "Checking analysis connections…" : availability.analysisAvailable ? "Analysis connection available. Working copies stay in your browser or downloaded file." : (availability.analysisUnavailableReason || "Analysis connection is unavailable. You can prepare material, explore numeric gaps, review work and download a copy; the full analysis cannot run yet.")}</p>
    <nav aria-label="Analysis workspace" className="flex flex-wrap gap-2">{([['prepare','1. Set the question'],['analysis','2. Examine findings'],['gaps','3. Explore the gap'],['practice','4. Review and learn']] as const).map(([value,label]) => <button key={value} type="button" className={`btn ${tab === value ? "btn--primary" : "btn--light"}`} style={tab === value ? navyAction : undefined} aria-current={tab === value ? "step" : undefined} onClick={() => setTab(value)}>{label}</button>)}</nav>
    {tab==="analysis" && analysis && <section className={surface}><h2 className="text-xl font-bold">Sources used for this analysis</h2>{request.mode==="practice" && <p className="mt-2 font-bold">Practice analysis. These findings do not describe actual DHS people or programs.</p>}{researchNote && <p className="mt-2">{researchNote}</p>}<ul className="mt-3 list-disc space-y-2 pl-5">{analysisSources.map(source=><li key={source.id}>{safeSourceHref(source.url) ? <SourceLink href={safeSourceHref(source.url)!} target="_blank" rel="noopener noreferrer" className="underline">{source.title}</SourceLink> : source.title}{source.date && ` · ${source.date}`}</li>)}</ul></section>}
    {tab === "prepare" && <fieldset disabled={busy || uploading} className="min-w-0 space-y-6">
      <div className={surface}><h2 className="text-xl font-bold">Try a realistic practice situation</h2><p className="mt-2">These invented cases are not evidence about actual DHS staff, services or legislation. Loading a case replaces the open preparation and analysis. Download any work you want to keep first.</p><div className="mt-3 flex flex-wrap gap-2">{PRACTICE_SCENARIOS.map(({id,...scenario}) => <button key={id} className="btn btn--light" onClick={() => {setRequest(scenario);setAnalysis(null);setAnalysisSources([]);setResearchNote("");setConfirmed(false);setReview({});setGap(initialGap);setGapResult(null);setGapSnapshot("");setGapError("");setMessage("Practice case loaded. Review the material and confirm it before analyzing.");}}>{scenario.title}</button>)}</div></div>
      <section className={surface}><h2 className="mb-4 text-xl font-bold">What decision are you examining?</h2><div className="grid gap-4 md:grid-cols-2"><label className="space-y-1"><span className="font-semibold">Work title</span><input className={input} maxLength={200} value={request.title} onChange={event => update("title",event.target.value)} /></label><label className="space-y-1"><span className="font-semibold">Reach of the work</span><select className={input} value={request.scope} onChange={event => update("scope",event.target.value as AnalysisRequest["scope"])}>{["individual","team","division","administration","agency"].map(scope => <option key={scope} value={scope}>{scope[0].toUpperCase()+scope.slice(1)}</option>)}</select></label><label className="space-y-1"><span className="font-semibold">Type of work</span><select className={input} value={request.kind} onChange={event => update("kind",event.target.value as AnalysisRequest["kind"])}><option value="policy">Policy or procedure</option><option value="bill">Bill or legislative proposal</option><option value="hcbs">Home and community-based services</option><option value="research">Research question</option><option value="workplace">Hiring or workplace culture</option><option value="program">Program or service design</option></select></label><label className="space-y-1"><span className="font-semibold">Use</span><select className={input} value={request.mode} onChange={event => update("mode",event.target.value as AnalysisRequest["mode"])}><option value="actual">Actual work</option><option value="practice">Practice</option></select></label></div><label className="mt-4 block space-y-1"><span className="font-semibold">Question to examine</span><textarea className={input} rows={3} maxLength={2000} value={request.question} onChange={event => update("question",event.target.value)} placeholder="Which barriers could this proposed change create, and which alternatives deserve consideration?" /></label><label className="mt-4 block space-y-1"><span className="font-semibold">Situation and who is responsible for the decision</span><textarea className={input} rows={3} maxLength={12000} value={request.context} onChange={event => update("context",event.target.value)} placeholder="Describe the situation, affected people, decision owner and any known limits. Do not include private personal information." /></label></section>
      <section className={surface}><h2 className="text-xl font-bold">Connect ADSA goals when relevant</h2><p className="mb-4 mt-2">This workspace supports work anywhere in DHS. Select ADSA goals when they apply; otherwise leave them blank. Findings and actions will keep the connections you choose.</p><div className="grid gap-3 md:grid-cols-2">{ADSA_GOALS.map(goal => <label key={goal.id} className="flex items-center gap-3 rounded-lg border border-slate-300 bg-white p-3"><input type="checkbox" checked={request.goals.includes(goal.id)} onChange={event => update("goals",event.target.checked ? [...request.goals,goal.id] : request.goals.filter(id => id !== goal.id))} /><span>{goal.title}</span></label>)}</div><Link className="mt-4 inline-block underline" href="/one-dsd">Explore the program and its equity goals</Link></section>
      <section className={surface}><h2 className="text-xl font-bold">Bring in the material</h2><p className="mb-4 mt-2">Paste excerpts or upload public or deidentified documents, images, audio or video. Confirm the material below before uploading. Give each source a clear title and check the extracted text. Use PDF, Word (.docx), PowerPoint (.pptx), text, PNG/JPEG/WebP, MP3/WAV/M4A, or MP4/WebM files up to 20 MB. Each source allows 50,000 characters, with 200,000 in total. Audio transcription and video review cover at most the first five minutes; video uses sampled visuals and it is not a complete review of every frame.</p>{request.sources.map((source,index) => <div key={source.id} className="mb-5 space-y-3 rounded-lg border border-slate-300 bg-white p-4"><label className="block space-y-1"><span className="font-semibold">Source {index+1} title</span><input className={input} maxLength={300} value={source.title} onChange={event => sourceUpdate(index,"title",event.target.value)} /></label><label className="block space-y-1"><span className="font-semibold">Source {index+1} text</span><textarea className={input} rows={7} maxLength={50000} value={source.text} onChange={event => sourceUpdate(index,"text",event.target.value)} /></label><label className="block"><span className="font-semibold">Upload material for this source</span><input className="mt-1 block w-full" type="file" accept=".txt,.pdf,.docx,.pptx,.png,.jpg,.jpeg,.webp,.mp3,.wav,.m4a,.mp4,.webm" disabled={!confirmed || uploading || busy} onChange={event => {void upload(event.target.files?.[0],index);event.target.value="";}} /><p className="mt-1 text-sm">Read or transcribed text is returned for your review. Uploads are sent to the reading service; browser drafts and report downloads remain your working copies.</p></label>{request.sources.length > 1 && <button className="underline" onClick={() => update("sources",request.sources.filter((_,i) => i !== index))}>Remove this source</button>}</div>)}<button className="btn btn--light" disabled={request.sources.length >= 12} onClick={() => update("sources",[...request.sources,{id:`source-${crypto.randomUUID()}`,title:"",text:""}])}>Add another source</button><label className="mt-5 flex items-start gap-3"><input type="checkbox" checked={confirmed} onChange={event => setConfirmed(event.target.checked)} /><span>I confirm these materials are public or have had private personal details removed, and are appropriate to send for analysis. They contain no private personnel, client, health or case information.</span></label><label className="mt-3 flex items-start gap-3"><input type="checkbox" disabled={!availability?.researchAvailable && !request.publicResearch} checked={request.publicResearch} onChange={event => update("publicResearch",event.target.checked)} /><span>Also search public sources using my question. The text you supplied is not sent to the search service. {!availability?.researchAvailable && "Public research is currently unavailable."}</span></label><button className="btn btn--primary mt-5" style={busy || !confirmed || !availability?.analysisAvailable ? undefined : navyAction} disabled={busy || uploading || !confirmed || !availability?.analysisAvailable} onClick={() => void analyze()}>{busy ? "Preparing your analysis…" : "Analyze the material"}</button><p className="mt-3 text-sm">Findings from the analysis need your review. Completing an analysis does not make it an official DHS position or a legal decision.</p></section>
    </fieldset>}
    {tab === "analysis" && <section className="space-y-5"><h2 ref={resultHeading} tabIndex={-1} className="text-2xl font-bold">Evidence, options and proposed action</h2>{!analysis ? <div className={surface}><p>Prepare your question and sources, then run an analysis. Your results will appear here.</p><button className="btn btn--light mt-3" onClick={() => setTab("prepare")}>Return to preparation</button></div> : <><div className={surface}><EditText label="Working summary" value={analysis.summary} onChange={summary => setAnalysis({...analysis,summary})} /><p className="mt-3 text-sm">Editable working analysis. Supplied quotations stay attached as evidence; changes you make are your own interpretation.</p></div><h3 className="text-xl font-bold">Findings</h3>{analysis.findings.map((finding,index) => <article key={index} className={`${surface} space-y-3`}><p className="text-sm font-bold uppercase tracking-wide">{finding.kind === "evidence" ? "Evidence from referenced material" : finding.kind === "gap" ? "Gap to investigate" : "Interpretation to review"}</p><EditText label={`Finding ${index+1}`} value={finding.statement} onChange={statement => setAnalysis({...analysis,findings:analysis.findings.map((item,i) => i===index ? {...item,statement}:item)})} /><EditText label="Reasoning" value={finding.reasoning} onChange={reasoning => setAnalysis({...analysis,findings:analysis.findings.map((item,i) => i===index ? {...item,reasoning}:item)})} /><p><strong>People to consider:</strong> {finding.affectedGroups.join(", ") || "Not yet identified"}</p><p className="text-sm"><strong>ADSA connection:</strong> {goalNames(finding.goals)}</p>{citations(finding.citations)}</article>)}<h3 className="text-xl font-bold">Compare alternatives</h3><div className="grid gap-4 lg:grid-cols-2">{analysis.alternatives.map((alternative,index) => <article key={index} className={`${surface} space-y-3`}>{(["title","benefits","risks","evidenceNeeded"] as const).map(key => <EditText key={key} label={key === "evidenceNeeded" ? "Evidence still needed" : key[0].toUpperCase()+key.slice(1)} value={alternative[key]} onChange={value => setAnalysis({...analysis,alternatives:analysis.alternatives.map((item,i) => i===index ? {...item,[key]:value}:item)})} />)}</article>)}</div><h3 className="text-xl font-bold">Turn the analysis into action</h3>{analysis.recommendations.map((recommendation,index) => <article key={index} className={`${surface} space-y-3`}>{(["action","rationale","responsibleRole","measure","nextStep"] as const).map(key => <EditText key={key} label={{action:"Proposed action",rationale:"Why this action",responsibleRole:"Responsible role",measure:"How to check the result",nextStep:"Next step"}[key]} value={recommendation[key]} onChange={value => setAnalysis({...analysis,recommendations:analysis.recommendations.map((item,i) => i===index ? {...item,[key]:value}:item)})} />)}<p className="text-sm"><strong>ADSA connection:</strong> {goalNames(recommendation.goals)}</p>{citations(recommendation.citations)}</article>)}<div className={surface}><h3 className="text-xl font-bold">Limits and questions</h3><ul className="mt-3 list-disc space-y-2 pl-5">{[...analysis.limitations,...analysis.questionsForReview].map((item,index) => <li key={index}>{item}</li>)}</ul></div><div className="flex flex-wrap gap-3"><button className="btn btn--primary" style={navyAction} onClick={() => setTab("gaps")}>Explore a measurable gap</button><Link className="btn btn--light" href="/one-dsd/planning">Connect to implementation planning</Link></div></>}</section>}
    {tab === "gaps" && <section className={surface}><h2 className="text-xl font-bold">Compare a current measure with a target</h2><p className="my-3">Use a group total or summary you are permitted to use, and a target in the same unit. Leave a value blank when it is unknown. This comparison does not explain the cause of a difference or predict an outcome.</p><div className="grid gap-4 md:grid-cols-2">{([['label','Measure'],['value','Current value (leave blank if unknown)'],['target','Target (leave blank if unknown)']] as const).map(([key,label]) => <label key={key} className="space-y-1"><span className="font-semibold">{label}</span><input className={input} disabled={key === "value" && gap.unit === "percent"} type={key === "label" ? "text" : "number"} min={key === "label" ? undefined : 0} value={gap[key]} onChange={event => setGap({...gap,[key]:event.target.value})} /></label>)}<label className="space-y-1"><span className="font-semibold">Unit</span><select className={input} value={gap.unit} onChange={event => setGap({...gap,unit:event.target.value as "count" | "percent" | "days" | "dollars"})}><option value="count">Count</option><option value="percent">Percentage</option><option value="days">Days</option><option value="dollars">Dollars</option></select></label><label className="space-y-1"><span className="font-semibold">Desired direction</span><select className={input} value={gap.direction} onChange={event => setGap({...gap,direction:event.target.value as "increase" | "decrease"})}><option value="increase">Increase toward target</option><option value="decrease">Decrease toward target</option></select></label>{([['start','Reporting period begins'],['end','Reporting period ends']] as const).map(([key,label]) => <label key={key} className="space-y-1"><span className="font-semibold">{label}</span><input className={input} type="text" aria-label={label} placeholder="MM/DD/YYYY" maxLength={10} value={gap[key]} onChange={event => setGap({...gap,[key]:event.target.value})} /></label>)}<label className="space-y-1"><span className="font-semibold">What-if change (%)</span><input className={input} type="number" min={-100} max={1000} value={gap.change} onChange={event => setGap({...gap,change:event.target.value})} /></label></div>{gap.unit==="percent" && <div className="mt-4 grid gap-4 md:grid-cols-2"><p className="md:col-span-2">For a percentage, enter the number meeting the measure and the total group size—for example, 60 completed requests out of 100. Leave both blank if unknown. The current percentage is calculated from these numbers.</p>{([["numerator","Number meeting the measure"],["denominator","Total in the measured group"]] as const).map(([key,label])=><label key={key} className="space-y-1"><span className="font-semibold">{label}</span><input className={input} type="number" min={0} value={gap[key]} onChange={event=>setGap({...gap,[key]:event.target.value})}/></label>)}</div>}<label className="mt-4 block space-y-1"><span className="font-semibold">Evidence, assumptions and uncertainty</span><textarea className={input} rows={3} value={gap.uncertainty} maxLength={6000} onChange={event => setGap({...gap,uncertainty:event.target.value})} placeholder="Name the source, population, limits and what would need to be true for the what-if change to occur." /></label><button className="btn btn--primary mt-4" style={navyAction} onClick={calculate}>Compare and explore</button>{gapError && <p role="alert" className="mt-3 text-red-800">{gapError}</p>}{gapResult && gapSnapshot===JSON.stringify(gap) && <div role="status" className="mt-5 rounded-lg border border-slate-400 bg-white p-5"><h3 className="text-lg font-bold">{gapResult.gap === null ? "Gap unknown" : gapResult.targetMet ? "Target reached for this measure" : `${gapResult.gap.toLocaleString()} ${gap.unit === "percent" ? "percentage points" : gap.unit} to the target`}</h3>{gapResult.gap !== null && (gapResult.target ?? 0)>0 && <><p className="mt-3 text-sm">Current and target, on the same scale</p>{[['Current',gapResult.current ?? 0],['Target',gapResult.target ?? 0]] .map(([label,value]) => <div key={String(label)} className="mt-2"><span>{label}: {Number(value).toLocaleString()} {gap.unit}</span><div className="mt-1 h-3 rounded bg-slate-200"><div className="h-3 rounded bg-slate-600" style={{width:`${Math.min(100,Number(value)/Math.max(gapResult.current ?? 0,gapResult.target ?? 0,1)*100)}%`}} /></div></div>)}</>}<p className="mt-4"><strong>What if the assumed change happens:</strong> {gapResult.scenario === null ? "The current value is unknown, so this result is unknown." : `${gapResult.scenario.toLocaleString()} ${gap.unit} if the assumed change occurs.`}</p><p className="mt-2 text-sm">This is a scenario, not a forecast. Predicting future results requires suitable data and checks for accuracy. That feature is not active here.</p></div>}</section>}
    {tab === "practice" && <section className={`${surface} space-y-4`}><h2 className="text-xl font-bold">Review the work and support learning</h2><p>Whether you are practicing or reviewing actual work, use the same criteria. Review the reasoning and supporting evidence, not a person’s worth or intercultural development level. Several well-supported answers may be reasonable.</p>{REVIEW_CRITERIA.map(criterion => <fieldset key={criterion.id} className="space-y-2 rounded-lg border border-slate-300 bg-white p-4"><legend className="px-2 font-bold">{criterion.title}</legend><label className="block"><span className="font-semibold">What does the work show?</span><select className={input} value={review[criterion.id]?.status ?? ""} onChange={event => setReview({...review,[criterion.id]:{status:event.target.value,note:review[criterion.id]?.note ?? ""}})}><option value="">Not reviewed yet</option><option value="supported">Supported with evidence</option><option value="developing">Developing; needs more work</option><option value="not-addressed">Not addressed</option><option value="not-applicable">Not applicable to this situation</option></select></label><label className="block"><span className="font-semibold">Evidence and useful feedback</span><textarea className={input} rows={3} maxLength={6000} value={review[criterion.id]?.note ?? ""} onChange={event => setReview({...review,[criterion.id]:{status:review[criterion.id]?.status ?? "",note:event.target.value}})} /></label></fieldset>)}<p className="text-sm">These observations can inform a future measure of progress over time. This workspace does not rank employees, determine individual IDI results or provide an established performance rating.</p><div className="flex flex-wrap gap-3"><Link className="btn btn--light" href="/program/foundation">Connect with foundational learning</Link><Link className="btn btn--light" href="/equity-review">Open the staff equity tools</Link></div></section>}
  </div>;
}

"use client";

import { usePathname, useSearchParams } from "next/navigation";
import { safeConsultantReturnPath } from "@/lib/auth/consultant-return";

export function ConsultantSignIn({ usesStarterKey }: { usesStarterKey: boolean }) {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const returnTo = safeConsultantReturnPath(pathname);

  return (
    <>
      {searchParams?.get("denied") === "1" ? (
        <p className="notice notice--stop mt-6 max-w-md" role="alert">
          The workspace access key did not match. Check it and try again.
        </p>
      ) : null}
      <form method="post" action="/api/consultant/login" className="card mt-6 max-w-md">
        <input type="hidden" name="returnTo" value={returnTo} />
        <div className="field">
          <label htmlFor="key">Workspace access key</label>
          <p className="help m-0">
            {usesStarterKey
              ? "Private sign-in has not been set up for this preview. Ask the person managing the application to configure access before sharing the workspace."
              : "Enter your Consultant Workspace access key."}
          </p>
          <input id="key" name="key" type="password" autoComplete="current-password" required />
        </div>
        <button type="submit" className="btn btn--primary">Open the workspace</button>
      </form>
    </>
  );
}

"use client";
import { SourceLink } from "@/components/app-link";


import { fullNames } from "@/lib/consultant-toolkit/auto-route";
import { getInstrument, getQuestions, type ToolkitQuestion } from "@/lib/consultant-toolkit/instrument";
import type { ToolkitRequest, ToolkitResponse } from "@/lib/consultant-toolkit/schema";
import styles from "../consultant-toolkit-workspace.module.css";
import { Field } from "./field";

type Source = ToolkitRequest["sources"][number];
export const safeHref = (value?: string) => { try { const url = new URL(value || ""); return ["http:", "https:"].includes(url.protocol) && !url.username && !url.password ? url.href : null; } catch { return null; } };
export const sourceNotes = (source: Source) => source.origin === "application-context" ? ["Related application reference", ...source.text.split("\n").filter(line => /^(Authority:|Resource location:|Source review date:|Official source entry point|No dashboard dataset)/.test(line)).map(fullNames)] : ["Supplied document or pasted evidence"];
const kindWords = (kind?: string) => kind === "evidence" ? "Supported by the cited material" : kind === "inference" ? "Interpretation — review against the evidence" : "Evidence still needed";

/** The analysis: a decision brief, what needs attention, every response with its evidence, options and actions. */
export function AnalysisView({ request, result, locked, busy, contextNote, editResult, editAnswer }: {
  request: ToolkitRequest; result: ToolkitResponse; locked: boolean; busy: boolean; contextNote: string;
  editResult: (next: ToolkitResponse) => void; editAnswer: (id: string, text: string) => void;
}) {
  const instrument = getInstrument(request.track);
  const question = (item: ToolkitQuestion, rows: number) => {
    const answer = result.answers.find(entry => entry.questionId === item.id);
    return <div className={styles.question} key={item.id}>
      <Field label={item.prompt} hint={item.help} value={answer?.text || "No answer recorded."} onChange={value => editAnswer(item.id, value)} disabled={locked || busy || !answer} rows={rows} />
      <p className={styles.muted}>{kindWords(answer?.kind)}</p>
      {answer?.citations.map((citation, i) => { const source = request.sources.find(entry => entry.id === citation.sourceId); const href = safeHref(source?.url); return <div className={styles.evidence} key={`${citation.sourceId}-${i}`}><strong>{source?.title || "Source"}</strong><blockquote>{citation.excerpt}</blockquote>{href && <SourceLink href={href} target="_blank" rel="noopener noreferrer">Open source</SourceLink>}</div>; })}
    </div>;
  };
  return <>
    <section className={`${styles.panel} ${styles.brief}`} aria-labelledby="decision-brief-heading">
      <h2 id="decision-brief-heading">Decision brief</h2>
      <p className={styles.caseTitle}>{request.title}</p>
      <h3>The decision being considered</h3><p className={styles.plain}>{request.question}</p>
      <details className={styles.disclosure}><summary>See what supports this draft</summary><p>These labels describe how the draft uses its sources. They are not a confidence score or a substitute for reviewing the quotations.</p><dl className={styles.briefColumns}>{([["evidence", "Responses citing evidence"], ["inference", "Responses needing interpretation review"], ["gap", "Responses needing evidence"]] as const).map(([kind, label]) => <div key={kind}><dt>{label}</dt><dd>{result.answers.filter(answer => answer.kind === kind).length}</dd></div>)}</dl><p>Start with the evidence gaps and limitations below. Then examine the source quotations and the alternatives before finalizing.</p></details>
      <h3>What the analysis says</h3><p className={styles.plain}>{result.summary}</p>
      <p className={styles.muted}>Read these findings alongside the evidence gaps below. The complete responses, source quotations, alternatives, and actions remain available for your review.</p>
      {!locked && <details className={styles.disclosure}><summary>Edit the summary</summary><Field label="Summary" value={result.summary} onChange={value => editResult({ ...result, summary: value })} rows={5} disabled={busy} /></details>}
      {contextNote && <p className={styles.muted}>{fullNames(contextNote)}</p>}
    </section>
    <section className={styles.panel} aria-labelledby="analysis-attention-heading"><h2 id="analysis-attention-heading">What needs attention before a decision</h2>
      <div className={styles.briefColumns}>
        <div><h3>Limits of the evidence</h3>{result.limitations.length ? <ul className={styles.briefList}>{result.limitations.map((value, index) => <li className={styles.plain} key={index}>{value}</li>)}</ul> : <p>No limitations have been recorded. Check the evidence before relying on this analysis.</p>}</div>
        <div><h3>Questions for your review</h3>{result.questionsForReview.length ? <ul className={styles.briefList}>{result.questionsForReview.map((value, index) => <li className={styles.plain} key={index}>{value}</li>)}</ul> : <p>No review questions have been recorded. Consider whose perspectives or evidence may still be missing.</p>}</div>
      </div>
      {!locked && <details className={styles.disclosure}><summary>Edit limitations and review questions</summary><fieldset disabled={locked || busy} className={styles.fields}>{result.limitations.map((value, index) => <Field key={`lim-${index}`} label={`Limitation ${index + 1}`} value={value} rows={2} onChange={next => editResult({ ...result, limitations: result.limitations.map((item, i) => i === index ? next : item) })} />)}{result.questionsForReview.map((value, index) => <Field key={`review-${index}`} label={`Review question ${index + 1}`} value={value} rows={2} onChange={next => editResult({ ...result, questionsForReview: result.questionsForReview.map((item, i) => i === index ? next : item) })} />)}</fieldset></details>}
    </section>
    <details className={`${styles.panel} ${styles.analysisDisclosure}`}><summary>Read the complete analysis — {getQuestions(request.track).length} responses and evidence</summary>
      <p className={styles.muted}>Every response is retained in full. Source quotations support examination of the findings; they do not replace your judgment about their accuracy or relevance.</p>
      <nav className={styles.stageNav} aria-label="Toolkit stages"><SourceLink href="#toolkit-preparation">Preparation</SourceLink>{instrument.stages.map((stage, index) => <SourceLink key={stage.id} href={`#toolkit-${stage.id}`}>{index + 1}. {stage.title}</SourceLink>)}</nav>
      <details className={styles.disclosure}><summary>Sources considered</summary><p className={styles.muted}>Application references provide context. Their source status and review date still need to fit this decision.</p>{request.sources.map(source => <div className={styles.source} key={source.id}><strong>{source.title}</strong>{sourceNotes(source).map(note => <p className={styles.muted} key={note}>{note}</p>)}{safeHref(source.url) && <SourceLink href={safeHref(source.url)!} target="_blank" rel="noopener noreferrer">Open source</SourceLink>}</div>)}</details>
      <section id="toolkit-preparation" className={`${styles.panel} ${styles.stage}`}><h2>Prepare the analysis</h2><p>{fullNames(instrument.preparationIntro)}</p>{instrument.preparation.map(item => question(item, 4))}</section>
      {instrument.stages.map((stage, index) => <section className={`${styles.panel} ${styles.stage}`} id={`toolkit-${stage.id}`} key={stage.id}><h2>{index + 1}. {stage.title}</h2><p>{fullNames(stage.description)}</p>{stage.questions.map(item => question(item, 5))}</section>)}
    </details>
    <details className={`${styles.panel} ${styles.analysisDisclosure}`}><summary>Compare the options</summary><div className={styles.compare}>{result.alternatives.map((option, index) => <fieldset className={styles.option} disabled={locked || busy} key={index}><Field label={`Option ${index + 1}`} value={option.title} rows={2} onChange={value => editResult({ ...result, alternatives: result.alternatives.map((item, i) => i === index ? { ...item, title: value } : item) })} />{([["benefits", "Potential benefits"], ["burdens", "Burdens and unintended effects"], ["evidenceNeeded", "Evidence still needed"]] as const).map(([key, label]) => <div className={styles.fields} key={key}><Field label={label} value={option[key]} onChange={value => editResult({ ...result, alternatives: result.alternatives.map((item, i) => i === index ? { ...item, [key]: value } : item) })} /></div>)}</fieldset>)}</div></details>
    <details className={`${styles.panel} ${styles.analysisDisclosure}`}><summary>Turn findings into action</summary>{result.actions.map((action, index) => <fieldset className={styles.question} key={index} disabled={locked || busy}><Field label={`Action ${index + 1}`} value={action.action} onChange={value => editResult({ ...result, actions: result.actions.map((item, i) => i === index ? { ...item, action: value } : item) })} /><div className={`${styles.twoColumns} ${styles.fields}`}>{([["responsibleRole", "Responsible role"], ["dueDate", "Timing"], ["resources", "Resources and support"], ["measure", "How to check progress"], ["followUp", "Follow-up and reporting back"]] as const).map(([key, label]) => <Field label={label} key={key} value={action[key]} rows={2} onChange={value => editResult({ ...result, actions: result.actions.map((item, i) => i === index ? { ...item, [key]: value } : item) })} />)}</div></fieldset>)}</details>
  </>;
}

"use client";

import type { ReactNode } from "react";

import { INFORMATION_CHECK_NOTE, type InformationNeed } from "@/lib/consultant-toolkit/information-needed";
import styles from "../consultant-toolkit-workspace.module.css";

export function ClosedSinceLastRun({ closed }: { closed: { questionId: string; title: string }[] }) {
  if (!closed.length) return null;
  return <section className={styles.closed} aria-labelledby="closed-since-heading">
    <h3 id="closed-since-heading">Closed since the last run</h3>
    <ul className={styles.briefList}>{closed.map(item => <li key={item.questionId}>{item.title}</li>)}</ul>
  </section>;
}

/** The needs list. Before a run it is a check of the attached material; after a run it lists recorded gaps. */
export function InformationNeededPanel({ items, mode, prompts, children }: { items: InformationNeed[]; mode: "before" | "after"; prompts: Map<string, string>; children?: ReactNode }) {
  const missing = items.filter(item => item.status === "missing");
  const found = items.filter(item => item.status === "found");
  const heading = mode === "before" ? "What is still needed" : "What is still needed after this run";
  return <section className={styles.panel} aria-labelledby={`needs-${mode}-heading`}>
    <h3 id={`needs-${mode}-heading`}>{heading}</h3>
    <p className={styles.muted}>{mode === "before" ? `${INFORMATION_CHECK_NOTE} You can run the analysis at any time; missing information is recorded as a gap.` : "These come from the responses the analysis could not answer from the material, its stated limits and its open questions."}</p>
    {missing.length ? <ul className={styles.needList}>{missing.map(item => <li key={item.id}>
      <strong className={styles.plain}>{item.need}</strong>
      <p className={styles.plain}>{item.why}</p>
      <p className={styles.muted}>Who might have it: {item.whoMightHaveIt}.</p>
      {item.questionIds.length > 0 && <details><summary>Toolkit {item.questionIds.length === 1 ? "question" : "questions"} it helps answer</summary><ul className={styles.briefList}>{item.questionIds.map(id => <li key={id}>{prompts.get(id) ?? id}</li>)}</ul></details>}
    </li>)}</ul> : <p>{mode === "before" ? "The attached material appears to touch on each kind of information this check looks for. Read it closely during the analysis." : "No gaps, limits or open questions were recorded. This does not establish that none exist."}</p>}
    {found.length > 0 && <details className={styles.disclosure}><summary>Already in the attached material ({found.length})</summary><ul className={styles.briefList}>{found.map(item => <li key={item.id}>{item.need}</li>)}</ul></details>}
    {children}
  </section>;
}

"use client";

import type { ToolkitRequest, ToolkitResponse } from "@/lib/consultant-toolkit/schema";
import styles from "../consultant-toolkit-workspace.module.css";

/** Page navigation, kept in one place so it can be observed in tests. */
export const navigation = { assign: (url: string) => window.location.assign(url) };

export type DownloadKind = "report" | "worksheet" | "action-plan" | "information-request" | "leadership-brief";
export type DownloadFormat = "word" | "pdf" | "json";

/** Body for the Equity Policy Analyzer's create-case route (createCaseRequestSchema in lib/policy-analysis/contract.ts). */
export function policyCaseBody(caseTitle: string, request: ToolkitRequest, result: ToolkitResponse) {
  const sources = request.sources.filter(source => source.origin !== "application-context").slice(0, 12).map(source => ({
    id: source.id, title: source.title, text: source.text,
    ...(source.url ? { url: source.url } : {}), ...(source.date ? { date: source.date } : {}),
    origin: "user" as const,
  }));
  return {
    title: caseTitle,
    policy: { title: caseTitle, programs: request.programs.slice(0, 20).map(program => program.slice(0, 120)) },
    sources,
    context: `${request.question}\n\n${result.summary}`.slice(0, 4000),
  };
}

export function OutputsPanel({ trackLabel, canDownload, dirty, busy, hasResult, onDownload, onPolicyChanges }: {
  trackLabel: string; canDownload: boolean; dirty: boolean; busy: boolean; hasResult: boolean;
  onDownload: (kind: DownloadKind, format: DownloadFormat) => void; onPolicyChanges: () => void;
}) {
  const cards: [DownloadKind, string, string][] = [
    ["report", "Analysis report", "The complete findings, alternatives, actions, and evidence."],
    ["leadership-brief", "Leadership brief", "One to two pages: the question, key findings, options, actions, what is unknown and the decision needed."],
    ["information-request", "Request for information", "A request to whoever holds the missing information: what is needed, why, and how to send it back."],
    ["worksheet", trackLabel === "Equity scan" ? "Equity scan worksheet" : "Full analysis worksheet", "Responses organized around the toolkit questions."],
    ["action-plan", "Action plan", "Responsibilities, resources, measures, and follow-up."],
  ];
  const disabled = busy || !canDownload || dirty;
  return <>
    <section className={styles.panel} aria-labelledby="downloads-heading"><h2 id="downloads-heading">Download the outputs</h2>
      <p>Each download includes its saved status and source information.</p>
      {dirty && <p className={styles.notice}>Save your changes first so the download matches your current work.</p>}
      {!canDownload && !dirty && <p className={styles.notice}>Save the analysis to download it.</p>}
      <div className={styles.downloads}>{cards.map(([kind, title, description]) => <div className={styles.downloadCard} key={kind}><h3>{title}</h3><p>{description}</p><div className={styles.actions}>
        <button type="button" className={styles.secondary} disabled={disabled} onClick={() => onDownload(kind, "word")} aria-label={`Download ${title} as Word`}>Word</button>
        <button type="button" className={styles.secondary} disabled={disabled} onClick={() => onDownload(kind, "pdf")} aria-label={`Download ${title} as PDF`}>PDF</button>
      </div></div>)}</div>
      <details className={styles.disclosure}><summary>Keep a complete data copy</summary><p>The data copy includes the analysis and source text. Store it with the same care as your source documents.</p><button type="button" className={styles.textButton} disabled={disabled} onClick={() => onDownload("report", "json")}>Download data copy</button></details>
    </section>
    <section className={styles.panel} aria-labelledby="policy-changes-heading"><h2 id="policy-changes-heading">Turn the recommendations into policy changes</h2>
      <p>Open this analysis in the Equity Policy Analyzer to draft specific changes to policy wording, protocols, processes and training, and to record a decision on each. Your documents, the question and the summary go with it; related application references do not.</p>
      <button type="button" className={styles.primary} disabled={busy || !hasResult} onClick={onPolicyChanges}>Turn the recommendations into policy changes</button>
      {!hasResult && <p className={styles.muted}>Run the analysis first.</p>}
    </section>
  </>;
}

"use client";

import type { ReactNode } from "react";

import type { SuggestedSetup } from "@/lib/consultant-toolkit/auto-route";
import type { ToolkitRequest } from "@/lib/consultant-toolkit/schema";
import styles from "../consultant-toolkit-workspace.module.css";
import { ROUTING_LABELS, SCOPE_LABELS, TRACK_LABELS } from "./field";

type Fields = Partial<Pick<ToolkitRequest, "title" | "track" | "routing" | "programs" | "scope" | "question">>;

/** Shows the suggested setup beside the current one. Nothing is applied until a "Use" button is chosen. */
export function SuggestedSetupPanel({ suggestion, request, disabled, onUse }: { suggestion: SuggestedSetup; request: ToolkitRequest; disabled: boolean; onUse: (fields: Fields, label: string) => void }) {
  const all: Fields = { track: suggestion.track, routing: suggestion.routing, programs: suggestion.programs, scope: suggestion.scope, question: suggestion.suggestedQuestion, ...(!request.title.trim() && suggestion.title ? { title: suggestion.title } : {}) };
  const signalsFor = (key: keyof ToolkitRequest["routing"]) => suggestion.signals.filter(signal => signal.key === key);
  const row = (label: string, value: ReactNode, fields: Fields, useLabel: string, detail?: ReactNode) => <div className={styles.setupRow}>
    <div><h4>{label}</h4><div className={styles.plain}>{value}</div>{detail}</div>
    <button type="button" className={styles.secondary} disabled={disabled} onClick={() => onUse(fields, useLabel)} aria-label={`Use the suggested ${useLabel}`}>Use</button>
  </div>;
  return <section className={styles.panel} aria-labelledby="suggested-setup-heading">
    <h3 id="suggested-setup-heading">Suggested setup</h3>
    <p>{suggestion.advisory} The suggestion comes from reading the attached material. Use all of it, use one field at a time, or change any field in your setup below.</p>
    <div className={styles.actions}><button type="button" className={styles.primary} disabled={disabled} onClick={() => onUse(all, "setup")}>Use this setup</button></div>
    {"title" in all && row("Title", all.title, { title: all.title }, "title")}
    {row("Depth of the analysis", TRACK_LABELS[suggestion.track], { track: suggestion.track }, "depth of the analysis",
      <details className={styles.disclosure}><summary>Why this depth</summary>{suggestion.trackReasons.map(reason => <p className={styles.muted} key={reason}>{reason}</p>)}</details>)}
    {row("The four routing answers", <ul className={styles.briefList}>{ROUTING_LABELS.map(([key, label]) => <li key={key}><strong>{suggestion.routing[key] ? "Yes" : "No"}:</strong> {label}{signalsFor(key).map(signal => <span className={styles.muted} key={signal.phrase}> The document says “{signal.phrase}”.</span>)}</li>)}</ul>, { routing: suggestion.routing }, "routing answers")}
    {row("Programs and service lines", suggestion.programs.length ? suggestion.programs.join(", ") : "No program names were found in the material. Add them in your setup if you know them.", { programs: suggestion.programs }, "programs")}
    {row("Scope of the work", SCOPE_LABELS[suggestion.scope], { scope: suggestion.scope }, "scope", <p className={styles.muted}>{suggestion.scopeReason}</p>)}
    {row("Drafted analysis question", suggestion.suggestedQuestion, { question: suggestion.suggestedQuestion }, "analysis question")}
    <details className={styles.disclosure}><summary>What the suggestion is based on</summary><ul className={styles.briefList}>{suggestion.reasons.map(reason => <li key={reason}>{reason}</li>)}</ul></details>
  </section>;
}

"use client";
import { SourceLink } from "@/components/app-link";


import { useEffect, useMemo, useRef, useState } from "react";
import { ADSA_GOALS } from "@/lib/consultant-analysis/schema";
import { fullNames, suggestSetup } from "@/lib/consultant-toolkit/auto-route";
import { afterRun, beforeRun, closedSinceLastRun, gapQuestionIds } from "@/lib/consultant-toolkit/information-needed";
import { getInstrument, getQuestions, recommendTrack } from "@/lib/consultant-toolkit/instrument";
import { casePayloadSchema, toolkitCaseSchema, toolkitRequestSchema, toolkitResponseSchema, TOOLKIT_LIMITS, type ToolkitCase, type ToolkitRequest, type ToolkitResponse } from "@/lib/consultant-toolkit/schema";
import { LTSS_RESOURCES } from "@/lib/consultant-toolkit/ltss";
import { linkedSourceId, linkedSourceTextHref, linkedSourceTitle, parseLinkedSource } from "@/lib/consultant-toolkit/linked-source";
import { AnalysisView, sourceNotes } from "./consultant-toolkit/analysis-view";
import { Field, ROUTING_LABELS, SCOPE_LABELS, spelledOut, TRACK_LABELS } from "./consultant-toolkit/field";
import { ClosedSinceLastRun, InformationNeededPanel } from "./consultant-toolkit/information-needed-panel";
import { navigation, OutputsPanel, policyCaseBody, type DownloadFormat, type DownloadKind } from "./consultant-toolkit/outputs";
import { SuggestedSetupPanel } from "./consultant-toolkit/suggested-setup";
import styles from "./consultant-toolkit-workspace.module.css";

type Availability = { analysisAvailable: boolean; analysisUnavailableReason: string | null; caseSavingAvailable: boolean; caseSavingUnavailableReason: string | null; privateProcessingNote: string };
type CaseSummary = Pick<ToolkitCase,"id"|"version"|"status"|"title"|"createdAt"|"updatedAt">;
type Source = ToolkitRequest["sources"][number];
type Step = "attach"|"setup"|"needs"|"run"|"gaps"|"outputs";
type SetupFields = Partial<Pick<ToolkitRequest,"title"|"track"|"routing"|"programs"|"scope"|"question">>;
const STEPS: [Step,string][] = [
  ["attach","Attach the document"],
  ["setup","Check the setup"],
  ["needs","See what is still needed"],
  ["run","Run the analysis"],
  ["gaps","Close the gaps"],
  ["outputs","Download the outputs"],
];
const emptyRequest = (): ToolkitRequest => ({ title: "", question: "", context: "", track: "full", scope: "division", programs: [], goals: [], sources: [], routing: { priorAnalysisIntegrated: false, materialChange: false, knownDisparities: false, timeLimited: false }, answers: {} });
const readReview = { evidence: false, perspectives: false, actions: false };
const shownDate = (value: string) => new Date(value).toLocaleDateString(undefined,{ year:"numeric",month:"short",day:"numeric" });
const plainError = (cause: unknown, fallback: string) => cause instanceof Error ? cause.message : fallback;
/** Typed notes stay with the case; only notes that belong to the selected track's questions are kept. */
const answersFor = (answers: ToolkitRequest["answers"], track: ToolkitRequest["track"]) => { const ids = new Set(getQuestions(track).map(question=>question.id)); return Object.fromEntries(Object.entries(answers).filter(([id])=>ids.has(id))); };
const fileName = (header: string|null, fallback: string) => /filename="([^"]+)"/.exec(header||"")?.[1] || fallback;
const POLICY_ERROR = "The Equity Policy Analyzer could not open this analysis. Your work here is unchanged.";
const LINKED_SOURCE_ERROR = "That course could not be loaded. Attach the document or paste its text instead. Your work here is unchanged.";

export function ConsultantToolkitWorkspace() {
  const [request,setRequest] = useState<ToolkitRequest>(emptyRequest);
  const [programText,setProgramText] = useState("");
  const [result,setResult] = useState<ToolkitResponse|null>(null);
  const [saved,setSaved] = useState<ToolkitCase|null>(null);
  const [cases,setCases] = useState<CaseSummary[]>([]);
  const [nextOffset,setNextOffset] = useState<number|null>(null);
  const [availability,setAvailability] = useState<Availability|null>(null);
  const [step,setStep] = useState<Step>("attach");
  const [dirty,setDirty] = useState(false);
  const [busy,setBusy] = useState("");
  const [message,setMessage] = useState("");
  const [error,setError] = useState("");
  const [contextNote,setContextNote] = useState("");
  const [review,setReview] = useState(readReview);
  const [library,setLibrary] = useState(false);
  const [pendingOpen,setPendingOpen] = useState<string|null>(null);
  const [removeConfirm,setRemoveConfirm] = useState(false);
  const [lastRunGaps,setLastRunGaps] = useState<string[]|null>(null);
  const [closed,setClosed] = useState<{ questionId: string; title: string }[]>([]);
  const [addingMore,setAddingMore] = useState(false);
  const fileInput = useRef<HTMLInputElement>(null);
  const mainHeading = useRef<HTMLHeadingElement>(null);
  const locked = saved?.status === "final";
  const unavailable = availability?.analysisAvailable === false;
  const instrument = getInstrument(request.track);
  const allReviewed = Object.values(review).every(Boolean);
  const prompts = useMemo(()=>new Map(getQuestions(request.track).map(question=>[question.id,question.prompt])),[request.track]);
  const userMaterial = useMemo(()=>request.sources.filter(source=>source.origin!=="application-context").map(source=>`${source.title}\n${source.text}`).join("\n\n"),[request.sources]);
  const suggestion = useMemo(()=>userMaterial.trim()?suggestSetup({title:request.title,text:`${userMaterial}\n${request.context}`},{today:new Date()}):null,[request.title,request.context,userMaterial]);
  const needsBefore = useMemo(()=>beforeRun(request),[request]);
  const needsAfter = useMemo(()=>result?afterRun(request,result):[],[request,result]);

  useEffect(()=>{
    const controller = new AbortController();
    void Promise.all([
      fetch("/api/consultant/toolkit",{ signal:controller.signal,cache:"no-store" }).then(async response=>{ const body=await response.json(); if(!response.ok) throw new Error(body.error||"The workspace could not connect."); setAvailability(body); }),
      fetch("/api/consultant/toolkit/cases",{ signal:controller.signal,cache:"no-store" }).then(async response=>{ const body=await response.json(); if(response.ok && Array.isArray(body.cases)){setCases(body.cases);setNextOffset(body.nextOffset??null);} }),
    ]).catch(cause=>{ if(!controller.signal.aborted)setError(plainError(cause,"The workspace could not connect. You can still prepare your material.")); });
    return ()=>controller.abort();
  },[]);
  // A course opened from its own page (?source=course:<id>) arrives as one pasted source. Nothing is run or saved.
  useEffect(()=>{
    const requested=new URLSearchParams(window.location.search).get("source");
    if(requested===null)return;
    const controller=new AbortController();
    Promise.resolve(parseLinkedSource(requested)).then(async linked=>{
      if(!linked)throw new Error(LINKED_SOURCE_ERROR);
      setBusy("Loading the course…");
      const response=await fetch(linkedSourceTextHref(linked),{signal:controller.signal,cache:"no-store",credentials:"same-origin"});
      if(!response.ok)throw new Error(LINKED_SOURCE_ERROR);
      const text=(await response.text()).trim();
      if(!text)throw new Error(LINKED_SOURCE_ERROR);
      const id=linkedSourceId(linked),title=linkedSourceTitle(text,linked);
      setRequest(previous=>previous.sources.some(source=>source.id===id)||previous.sources.length>=TOOLKIT_LIMITS.sources?previous:{...previous,sources:[...previous.sources,{id,title,text:text.slice(0,TOOLKIT_LIMITS.sourceCharacters),origin:"user"}]});
      setDirty(true);
      setMessage(`${title} is loaded as a source. Check it below, then continue to the setup. Nothing has been run or saved.`);
    }).catch(()=>{ if(!controller.signal.aborted)setError(LINKED_SOURCE_ERROR); }).finally(()=>{ if(!controller.signal.aborted)setBusy(""); });
    return ()=>controller.abort();
  },[]);
  useEffect(()=>{
    if(!dirty)return;
    const warn=(event:BeforeUnloadEvent)=>{ event.preventDefault(); event.returnValue=""; };
    window.addEventListener("beforeunload",warn); return ()=>window.removeEventListener("beforeunload",warn);
  },[dirty]);

  function changed() { setDirty(true); setReview(readReview); setError(""); setMessage(""); }
  function staleResult() { if(result){ setResult(null); setContextNote(""); setMessage("The material or setup changed. Run the analysis again so it matches. Your typed notes are kept."); } }
  function update<K extends keyof ToolkitRequest>(key:K,value:ToolkitRequest[K]) {
    if(locked)return;
    changed(); setRequest(previous=>({...previous,[key]:value,...(key==="track"?{answers:answersFor(previous.answers,value as ToolkitRequest["track"])}:{})}));
    staleResult();
  }
  function applySetup(fields:SetupFields,label:string) {
    if(locked)return;
    changed();
    setRequest(previous=>({...previous,...fields,...(fields.track?{answers:answersFor(previous.answers,fields.track)}:{})}));
    if(fields.programs)setProgramText(fields.programs.join(", "));
    staleResult();
    setMessage(label==="setup"?"The suggested setup is now in use. You can still change any field below.":`The suggested ${label} is now in use. You can still change it below.`);
  }
  function editResult(next:ToolkitResponse) { if(locked)return; changed(); setResult(next); }
  function editAnswer(id:string,text:string) {
    if(!result)return;
    editResult({...result,answers:result.answers.map(answer=>answer.questionId===id?{...answer,text,kind:answer.kind === "gap" ? "gap" : "inference"}:answer)});
  }
  async function jsonRequest(path:string,method:string,body?:unknown) {
    const response = await fetch(path,{method,cache:"no-store",headers:body?{"Content-Type":"application/json"}:undefined,body:body?JSON.stringify(body):undefined});
    const value = await response.json();
    if(!response.ok)throw new Error(typeof value.error==="string"?value.error:"That request could not be completed. Your work is still here.");
    return value;
  }
  function applyCase(value:ToolkitCase) {
    setSaved(value);setRequest(value.request);setProgramText(value.request.programs.join(", "));setResult(value.result);setDirty(false);setReview(readReview);setContextNote("");setPendingOpen(null);setError("");setRemoveConfirm(false);
    setCases(previous=>[value,...previous.filter(item=>item.id!==value.id)]);
  }
  async function save(status:ToolkitCase["status"]="draft",approveFinal=false) {
    setError("");setMessage("");
    const parsed=casePayloadSchema.safeParse({request,result});
    if(!parsed.success){ setError(parsed.error.issues[0]?.message||"Check the title, question, and source material before saving.");return null; }
    if(status==="final" && (!allReviewed || dirty || saved?.status!=="review")){setError("Save the review, then check the three review statements before marking it final.");return null;}
    setBusy("Saving your analysis…");
    try {
      let body;
      let current=saved;
      if(status==="review"&&(!current||dirty)){
        const draftBody=current?await jsonRequest(`/api/consultant/toolkit/cases/${encodeURIComponent(current.id)}`,"PUT",{expectedVersion:current.version,payload:parsed.data,status:"draft"}):await jsonRequest("/api/consultant/toolkit/cases","POST",{payload:parsed.data});
        current=toolkitCaseSchema.parse(draftBody.case);applyCase(current);
      }
      if(current) body=await jsonRequest(`/api/consultant/toolkit/cases/${encodeURIComponent(current.id)}`,"PUT",{expectedVersion:current.version,payload:parsed.data,status,approveFinal});
      else body=await jsonRequest("/api/consultant/toolkit/cases","POST",{payload:parsed.data});
      const value=toolkitCaseSchema.parse(body.case);applyCase(value);
      setMessage(value.status==="final"?"Final copy saved. You can download it below.":value.status==="review"?"Saved for your final review.":"Draft saved in your private case library.");
      return value;
    } catch(cause){setError(plainError(cause,"This analysis could not be saved. Your work is still here."));return null;}
    finally{setBusy("");}
  }
  async function openCase(id:string) {
    if(dirty){setPendingOpen(id);return;}
    await loadCase(id);
  }
  async function moreCases(){
    if(nextOffset===null)return;setBusy("Loading more saved analyses…");setError("");
    try{const body=await jsonRequest(`/api/consultant/toolkit/cases?offset=${nextOffset}`,"GET");setCases(previous=>[...previous,...body.cases.filter((item:CaseSummary)=>!previous.some(entry=>entry.id===item.id))]);setNextOffset(body.nextOffset??null);}
    catch(cause){setError(plainError(cause,"More saved analyses could not be loaded."));}finally{setBusy("");}
  }
  async function loadCase(id:string) {
    setBusy("Opening your saved analysis…");setError("");
    try{ const body=await jsonRequest(`/api/consultant/toolkit/cases/${encodeURIComponent(id)}`,"GET");const value=toolkitCaseSchema.parse(body.case);applyCase(value);setLastRunGaps(value.result?gapQuestionIds(value.result):null);setClosed([]);setAddingMore(false);setStep(value.result?"run":"attach");setLibrary(false);setMessage("Saved analysis opened."); }
    catch(cause){setError(plainError(cause,"That analysis could not be opened."));}
    finally{setBusy("");}
  }
  function newCase(force=false) {
    if(dirty&&!force){setPendingOpen("new");return;}
    setRequest(emptyRequest());setProgramText("");setResult(null);setSaved(null);setDirty(false);setReview(readReview);setMessage("");setError("");setContextNote("");setStep("attach");setPendingOpen(null);setRemoveConfirm(false);setLastRunGaps(null);setClosed([]);setAddingMore(false);
  }
  async function reopen() {
    if(!saved)return;setBusy("Reopening the analysis…");setError("");
    try{const body=await jsonRequest(`/api/consultant/toolkit/cases/${encodeURIComponent(saved.id)}`,"PUT",{expectedVersion:saved.version,payload:{request,result},status:"draft"});applyCase(toolkitCaseSchema.parse(body.case));setMessage("Reopened as a draft. It will need your review again before it can be marked final.");}
    catch(cause){setError(plainError(cause,"This analysis could not be reopened."));}finally{setBusy("");}
  }
  async function deleteCase() {
    if(!saved)return;setBusy("Removing the saved case…");setError("");
    try{await jsonRequest(`/api/consultant/toolkit/cases/${encodeURIComponent(saved.id)}`,"DELETE",{expectedVersion:saved.version});setCases(previous=>previous.filter(item=>item.id!==saved.id));newCase(true);setMessage("The saved case has been removed.");}
    catch(cause){setError(plainError(cause,"The case could not be removed."));}finally{setBusy("");}
  }
  async function upload(files:FileList|null) {
    if(!files?.length || locked)return;
    setError("");setMessage("");
    const added:Source[]=[];
    let uploadError="";
    setBusy("Reading your documents…");
    try{
      for(const file of Array.from(files)){
        if(!/\.(pdf|docx|pptx|txt|csv|tsv|xlsx)$/i.test(file.name)||file.size>20*1024*1024)throw new Error("Choose a PDF, Word, PowerPoint, Excel, comma-separated, tab-separated or plain text file no larger than 20 megabytes.");
        if(request.sources.length+added.length>=TOOLKIT_LIMITS.sources)throw new Error(`Use up to ${TOOLKIT_LIMITS.sources} documents or pasted sources at a time.`);
        const form=new FormData();form.append("file",file);
        const response=await fetch("/api/consultant/toolkit/upload",{method:"POST",body:form});
        const body=await response.json();if(!response.ok)throw new Error(body.error||`${file.name} could not be read.`);
        const source=body.source as Source;
        if(!source||typeof source.text!=="string"||typeof source.title!=="string")throw new Error("The document text could not be read.");
        added.push({...source,id:`upload-${crypto.randomUUID()}`,origin:"user"});
      }
    }catch(cause){uploadError=plainError(cause,"A document could not be read.");}
    finally{
      if(added.length){update("sources",[...request.sources,...added]);setMessage(`${added.length} ${added.length===1?"document added":"documents added"}. Review the extracted text; images, charts, and scanned pages may need a separate written description. A suggested setup is ready in step 2.`);}
      if(uploadError)setError(uploadError);
      setBusy("");if(fileInput.current)fileInput.current.value="";
    }
  }
  async function analyze() {
    setError("");setMessage("");
    const parsed=toolkitRequestSchema.safeParse(request);
    if(!parsed.success){setError(parsed.error.issues[0]?.message||"Complete the title, question and evidence before running the analysis.");return;}
    setBusy("Running the analysis…");
    const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),240000);
    try{
      const response=await fetch("/api/consultant/toolkit/analyze",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({request:parsed.data}),signal:controller.signal});
      const body=await response.json();if(!response.ok)throw new Error(body.error||"The analysis could not be prepared.");
      const analysis=toolkitResponseSchema.parse(body.analysis);
      // Typed notes (answers) travel with the request and are kept as they were.
      const nextRequest=toolkitRequestSchema.parse({...parsed.data,sources:body.sources??parsed.data.sources});
      const closedNow=lastRunGaps?closedSinceLastRun(lastRunGaps,analysis):[];
      setResult(analysis);setRequest(nextRequest);setDirty(true);setReview(readReview);setContextNote(typeof body.contextNote==="string"?body.contextNote:"");setClosed(closedNow);setLastRunGaps(gapQuestionIds(analysis));setAddingMore(false);
      setStep("run");
      setMessage(`Analysis ready. Review each answer and its evidence, then save.${closedNow.length?` ${closedNow.length} ${closedNow.length===1?"need was":"needs were"} closed since the last run.`:""}`);
      setTimeout(()=>mainHeading.current?.focus(),0);
    }catch(cause){setError(controller.signal.aborted?"The analysis took longer than expected. Your material is still here; no automatic retry was made.":plainError(cause,"The analysis could not be prepared. Your material is still here."));}
    finally{clearTimeout(timeout);setBusy("");}
  }
  async function download(kind:DownloadKind,format:DownloadFormat) {
    if(!saved||dirty){setError("Save your current changes before downloading so the file matches this analysis.");return;}
    setBusy("Preparing your download…");setError("");
    try{
      const response=await fetch("/api/consultant/toolkit/export",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({caseId:saved.id,format,kind,expectedVersion:saved.version})});
      if(!response.ok){const body=await response.json();throw new Error(body.error||"The download could not be prepared.");}
      const blob=await response.blob();const url=URL.createObjectURL(blob);const anchor=document.createElement("a");anchor.href=url;anchor.download=fileName(response.headers.get("content-disposition"),`equity-${kind}.${format==="word"?"docx":format}`);document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);setMessage("Your download is ready. It contains the saved analysis and its review status.");
    }catch(cause){setError(plainError(cause,"The download could not be prepared."));}finally{setBusy("");}
  }
  async function policyChanges() {
    if(!result)return;
    setBusy("Opening the Equity Policy Analyzer…");setError("");
    try{
      const response=await fetch("/api/equity-workspace/policy-analysis/cases",{method:"POST",cache:"no-store",headers:{"Content-Type":"application/json"},body:JSON.stringify(policyCaseBody(saved?.title||request.title,request,result))});
      const body=await response.json().catch(()=>({}));
      const id=body?.case?.id;
      if(response.status!==201||typeof id!=="string")throw new Error(typeof body?.error==="string"?body.error:POLICY_ERROR);
      navigation.assign(`/equity-workspace/policy-analyzer?case=${encodeURIComponent(id)}`);
    }catch(cause){setError(plainError(cause,POLICY_ERROR));setBusy("");}
  }
  function sourceChange(index:number,key:"title"|"text"|"url",value:string) {update("sources",request.sources.map((source,i)=>{if(i!==index)return source;const next={...source,[key]:value,origin:"user" as const};if(key==="url"&&!value)delete next.url;return next;}));}
  function showStep(next:Step){setStep(next);setTimeout(()=>mainHeading.current?.focus(),0);}
  function attachMore(){setAddingMore(true);showStep("attach");}
  const routeRecommendation=recommendTrack(request.routing);
  const stepIndex=STEPS.findIndex(([id])=>id===step);
  const continueTo=(next:Step,label:string)=><div className={styles.actions}><button type="button" className={styles.primary} onClick={()=>showStep(next)}>{label}</button></div>;

  return <div className={styles.workspace} aria-busy={Boolean(busy)}>
    <div className={styles.toolbar}>
      <div><span className={styles.badge}>{locked?"Final":saved?.status==="review"&&!dirty?"Ready for review":"Draft"}</span><p className={styles.muted}>{saved?`${dirty?"Unsaved changes · ":""}Saved ${shownDate(saved.updatedAt)}`:"Your case stays private to this workspace."}</p></div>
      <div className={styles.actions}><button type="button" className={styles.secondary} disabled={Boolean(busy)} onClick={()=>setLibrary(!library)} aria-expanded={library}>Saved analyses</button><button type="button" className={styles.secondary} disabled={Boolean(busy)} onClick={()=>newCase()}>New analysis</button>{!locked&&<button type="button" className={styles.primary} disabled={Boolean(busy)||availability?.caseSavingAvailable===false} onClick={()=>void save()}>Save draft</button>}</div>
    </div>
    {library&&<section className={styles.panel} aria-label="Saved analyses"><h2>Your saved analyses</h2>{cases.length?<ul className={styles.library}>{cases.map(item=><li key={item.id}><div><strong>{item.title}</strong><span className={styles.muted}>{item.status==="final"?"Final":item.status==="review"?"For review":"Draft"} · {shownDate(item.updatedAt)}</span></div><button type="button" className={styles.secondary} aria-label={`Open ${item.title}`} disabled={Boolean(busy)} onClick={()=>void openCase(item.id)}>Open</button></li>)}</ul>:<p>No saved analyses yet. Give your work a title and save a draft to return to it later.</p>}{nextOffset!==null&&<button type="button" className={styles.textButton} disabled={Boolean(busy)} onClick={()=>void moreCases()}>Show more saved analyses</button>}</section>}
    {pendingOpen&&<div className={styles.notice}><p>You have unsaved changes. Save them before opening another analysis, or discard them.</p><div className={styles.actions}><button type="button" className={styles.primary} disabled={Boolean(busy)} onClick={async()=>{const next=pendingOpen;if(await save()){if(next==="new")newCase(true);else await loadCase(next);}}}>Save and continue</button><button type="button" className={styles.secondary} disabled={Boolean(busy)} onClick={()=>pendingOpen==="new"?newCase(true):void loadCase(pendingOpen)}>Discard changes and continue</button><button type="button" className={styles.textButton} onClick={()=>setPendingOpen(null)}>Keep working</button></div></div>}
    {error&&<p className={styles.error} role="alert">{error}</p>}
