    {locked&&<div className={styles.notice}><p>This is the final saved copy. Reopen it as a draft to make changes and review it again.</p><button type="button" className={styles.secondary} disabled={Boolean(busy)} onClick={()=>void reopen()}>Reopen as draft</button></div>}
    <nav aria-label="Analysis steps"><ol className={styles.steps}>{STEPS.map(([id,label],index)=><li key={id}><button type="button" aria-current={step===id?"step":undefined} onClick={()=>showStep(id)}>{index+1}. {label}</button></li>)}</ol></nav>
    <h2 ref={mainHeading} tabIndex={-1}>Step {stepIndex+1} of {STEPS.length}: {STEPS[stepIndex][1]}</h2>

    {step==="attach"&&<>
      {addingMore&&<div className={styles.notice}><p>Add the new material below. The same case and your typed notes are kept. Then run the analysis again.</p><button type="button" className={styles.secondary} disabled={Boolean(busy)} onClick={()=>showStep("run")}>Go to step 4 and run again</button></div>}
      <section className={styles.panel}><div className={styles.sourceHeader}><h3>The document to analyze</h3><span className={styles.muted}>{request.sources.length} / {TOOLKIT_LIMITS.sources} sources</span></div>
        <fieldset disabled={locked||Boolean(busy)} className={styles.fields}><label className={styles.field}><span>Analysis title</span><input value={request.title} maxLength={200} onChange={event=>update("title",event.target.value)} placeholder="For example, improving access to a service notice" /></label></fieldset>
        <p>Attach the document, or paste its text, along with any data, engagement notes or earlier analyses you have. You can check and correct the extracted text before running the analysis.</p>
        <div className={styles.actions}><input ref={fileInput} type="file" multiple accept=".pdf,.docx,.pptx,.txt,.csv,.tsv,.xlsx" className={styles.hidden} tabIndex={-1} aria-hidden="true" onChange={event=>void upload(event.target.files)} /><button type="button" className={`${styles.secondary} ${styles.attach}`} disabled={locked||Boolean(busy)||request.sources.length>=TOOLKIT_LIMITS.sources} onClick={()=>fileInput.current?.click()}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true"><path d="m8 12 7-7a4 4 0 0 1 6 6L10 22a6 6 0 0 1-8-8L13 3a2 2 0 0 1 3 3L5 17" /></svg>Attach documents</button><button type="button" className={styles.textButton} disabled={locked||Boolean(busy)||request.sources.length>=TOOLKIT_LIMITS.sources} onClick={()=>update("sources",[...request.sources,{id:`paste-${crypto.randomUUID()}`,title:"",text:"",origin:"user"}])}>Paste a document</button></div>
        <p className={styles.muted}>PDF with selectable text, Word, PowerPoint, Excel, comma-separated, tab-separated or plain text, up to 20 megabytes each. Scanned pages and image-only content need text added separately. Original files are read into text; the case stores the extracted text.</p>
        <details className={styles.disclosure}><summary>Use long-term services and supports data to inform the analysis</summary><p>Explore the official dashboards, then attach the relevant spreadsheet or paste selected figures. Include the reporting period, program, population, geography, and denominator. Opening a dashboard does not load its data into this analysis.</p>{LTSS_RESOURCES.map(resource=><p key={resource.id}><SourceLink href={resource.url} target="_blank" rel="noopener noreferrer">{spelledOut(resource.title)}</SourceLink><br/><span className={styles.muted}>{resource.description}</span></p>)}<p className={styles.muted}>Keep suppressed or missing values as reported. Combine the figures with the experiences and perspectives of affected people.</p></details>
        {request.sources.map((source,index)=><div className={styles.source} key={source.id}><div className={styles.sourceHeader}><h3>{source.title||`Source ${index+1}`}</h3>{!locked&&<button type="button" className={styles.textButton} disabled={Boolean(busy)} onClick={()=>update("sources",request.sources.filter((_,i)=>i!==index))}>Remove<span className={styles.hidden}> source {index+1}</span></button>}</div>{sourceNotes(source).map(note=><p className={styles.muted} key={note}>{note}</p>)}<fieldset disabled={locked||Boolean(busy)} className={styles.fields}><label className={styles.field}><span>Source title</span><input value={source.title} maxLength={500} onChange={event=>sourceChange(index,"title",event.target.value)} /></label><Field label="Source text" value={source.text} maxLength={TOOLKIT_LIMITS.sourceCharacters} rows={6} onChange={value=>sourceChange(index,"text",value)} /><label className={styles.field}><span>Source web address, if available</span><input type="url" value={source.url||""} onChange={event=>sourceChange(index,"url",event.target.value)} placeholder="https://" /></label></fieldset></div>)}
      </section>
      {continueTo("setup","Continue to check the setup")}
    </>}

    {step==="setup"&&<>
      {suggestion?<SuggestedSetupPanel suggestion={suggestion} request={request} disabled={locked||Boolean(busy)} onUse={applySetup} />:<p className={styles.notice}>Attach or paste a document in step 1 to get a suggested setup. You can also fill in the setup yourself.</p>}
      <section className={styles.panel}><h3>Your setup</h3><fieldset disabled={locked||Boolean(busy)} className={styles.fields}>
        <Field label="Decision or question" value={request.question} onChange={value=>update("question",value)} maxLength={2000} hint="Describe the proposed change, who it could affect, and the decision this analysis should inform." />
        <div className={styles.twoColumns}><label className={styles.field}><span>Scope of the work</span><select value={request.scope} onChange={event=>update("scope",event.target.value as ToolkitRequest["scope"])}>{(Object.keys(SCOPE_LABELS) as (keyof typeof SCOPE_LABELS)[]).map(scope=><option key={scope} value={scope}>{SCOPE_LABELS[scope]}</option>)}</select></label><label className={styles.field}><span>Programs and service lines</span><input value={programText} maxLength={2000} onChange={event=>{setProgramText(event.target.value);changed();}} onBlur={()=>{const programs=programText.split(",").map(value=>value.trim()).filter(Boolean);if(JSON.stringify(programs)!==JSON.stringify(request.programs))update("programs",programs);}} placeholder="For example, Community First Services and Supports, MnCHOICES, housing" /><small>Separate names with commas. Relevant published resources from this application will be considered.</small></label></div>
        <Field label="Background and constraints" value={request.context} onChange={value=>update("context",value)} maxLength={12000} hint="Include timing, resources, earlier decisions, and what you still need to learn." />
      </fieldset>
      <details className={styles.disclosure}><summary>Connect Aging and Disability Services Administration implementation goals</summary><p className={styles.muted}>Select goals that apply to this work. Leave these unselected for work outside the Aging and Disability Services Administration.</p><fieldset disabled={locked||Boolean(busy)} className={styles.fields}>{ADSA_GOALS.map(goal=><label className={styles.choice} key={goal.id}><input type="checkbox" checked={request.goals.includes(goal.id)} onChange={event=>update("goals",event.target.checked?[...request.goals,goal.id]:request.goals.filter(id=>id!==goal.id))} /><span>{goal.title}</span></label>)}</fieldset></details>
      </section>
      <section className={styles.panel}><h3>Depth of the analysis</h3><p className={styles.muted}>Use a scan to identify concerns and next steps. Use the full analysis to work through evidence, participation, alternatives, and implementation in depth.</p><fieldset disabled={locked||Boolean(busy)} className={styles.fields}><legend className={styles.hidden}>Depth of the analysis</legend><div className={styles.twoColumns}><label className={`${styles.choice} ${styles.track}`}><input type="radio" name="toolkit-track" value="scan" checked={request.track==="scan"} onChange={()=>update("track","scan")} /><span><strong>{TRACK_LABELS.scan}</strong>A concise, adapted six-question review.</span></label><label className={`${styles.choice} ${styles.track}`}><input type="radio" name="toolkit-track" value="full" checked={request.track==="full"} onChange={()=>update("track","full")} /><span><strong>{TRACK_LABELS.full}</strong>Work through all six Department of Human Services toolkit stages.</span></label></div>
        <details className={styles.disclosure}><summary>The four routing answers</summary><div className={styles.fields}>{ROUTING_LABELS.map(([key,label])=><label className={styles.choice} key={key}><input type="checkbox" checked={request.routing[key]} onChange={event=>update("routing",{...request.routing,[key]:event.target.checked})} /><span>{label}</span></label>)}</div><div className={styles.notice}><strong>Suggested depth: {routeRecommendation.track==="full"?"full analysis":"equity scan"}</strong>{routeRecommendation.reasons.map(reason=><p key={reason}>{fullNames(reason)}</p>)}<p className={styles.muted}>This is a suggestion for your judgment, not an agency routing decision.</p></div></details>
      </fieldset><details className={styles.disclosure}><summary>About this toolkit</summary><p>{fullNames(instrument.authorityNote)}</p><p className={styles.muted}>Your review marks an analysis final; it does not confer agency approval.</p></details></section>
      {continueTo("needs","Continue to see what is still needed")}
    </>}

    {step==="needs"&&<>
      <InformationNeededPanel items={needsBefore} mode="before" prompts={prompts}><div className={styles.actions}><button type="button" className={styles.secondary} onClick={attachMore}>Attach more material</button></div></InformationNeededPanel>
      <details className={styles.panel}><summary>Notes you already have for the toolkit questions</summary><p className={styles.muted}>Optional. Existing findings, engagement notes, and open questions help the analysis reflect work already done. They are kept when you run the analysis again.</p><fieldset disabled={locked||Boolean(busy)} className={styles.fields}>{getQuestions(request.track).map(question=><Field key={question.id} label={question.prompt} hint={question.help} value={request.answers[question.id]||""} onChange={value=>update("answers",{...request.answers,[question.id]:value})} />)}</fieldset></details>
      {continueTo("run","Continue to run the analysis")}
    </>}

    {step==="run"&&<>
      <section className={styles.panel}><h3>{result?"The analysis":"Run the analysis"}</h3><p>{availability?.privateProcessingNote||"Your selected material is sent to the configured analysis service only when you run the analysis. It is not published to staff or leadership."}</p>{unavailable&&<p className={styles.notice}>{availability.analysisUnavailableReason||"The analysis service is not available yet. You can prepare and save your material."}</p>}<div className={styles.actions}><button type="button" className={styles.primary} disabled={locked||Boolean(busy)||!availability?.analysisAvailable} onClick={()=>void analyze()}>{result||lastRunGaps?"Run the analysis again":`Run the ${request.track==="scan"?"scan":"full analysis"}`}</button></div></section>
      <ClosedSinceLastRun closed={closed} />
      {result?<><AnalysisView request={request} result={result} locked={locked} busy={Boolean(busy)} contextNote={contextNote} editResult={editResult} editAnswer={editAnswer} />{continueTo("gaps","Continue to close the gaps")}</>:<p className={styles.muted}>The analysis will appear here, with supporting quotations and what remains unknown.</p>}
    </>}

    {step==="gaps"&&<>
      <ClosedSinceLastRun closed={closed} />
      {result?<InformationNeededPanel items={needsAfter} mode="after" prompts={prompts}><div className={styles.actions}><button type="button" className={styles.primary} disabled={locked||Boolean(busy)} onClick={attachMore}>Attach more material and run again</button><button type="button" className={styles.secondary} onClick={()=>showStep("outputs")}>Download a request for this information</button></div></InformationNeededPanel>
        :<section className={styles.panel}><p>{lastRunGaps?"The material changed since the last run. Run the analysis again to see what is still needed.":"Run the analysis first. Its gaps, limits and open questions will be listed here."}</p><div className={styles.actions}><button type="button" className={styles.primary} onClick={()=>showStep("run")}>Go to step 4</button></div></section>}
      {continueTo("outputs","Continue to download the outputs")}
    </>}

    {step==="outputs"&&<>
      <section className={styles.panel}><h3>{locked?"Your final copy is saved":"Review before marking final"}</h3>{!result?<p>Run the analysis before completing your review.</p>:locked?<p>The downloads below reflect this final version. Reopen it as a draft if a source, finding, or recommendation changes.</p>:<><p>Check the evidence and the proposed actions. Missing engagement or data should stay visible as a gap, with a plan to address it.</p><fieldset disabled={Boolean(busy)||dirty||saved?.status!=="review"} className={styles.reviewList}><legend className={styles.hidden}>Review statements</legend><label className={styles.choice}><input type="checkbox" checked={review.evidence} onChange={event=>setReview({...review,evidence:event.target.checked})} /><span>I reviewed the source quotations, conclusions, and limitations.</span></label><label className={styles.choice}><input type="checkbox" checked={review.perspectives} onChange={event=>setReview({...review,perspectives:event.target.checked})} /><span>I checked whose perspectives are represented and recorded where input is still needed.</span></label><label className={styles.choice}><input type="checkbox" checked={review.actions} onChange={event=>setReview({...review,actions:event.target.checked})} /><span>I reviewed the alternatives, responsibilities, measures, and follow-up.</span></label></fieldset><div className={styles.actions}>{(dirty||saved?.status!=="review")&&<button type="button" className={styles.primary} disabled={Boolean(busy)||availability?.caseSavingAvailable===false} onClick={()=>void save("review")}>Save for review</button>}<button type="button" className={styles.primary} disabled={Boolean(busy)||dirty||saved?.status!=="review"||!allReviewed} onClick={()=>void save("final",true)}>Approve final copy</button></div><p className={styles.muted}>This records your review. It does not replace an agency decision or required approval.</p></>}</section>
      <OutputsPanel trackLabel={TRACK_LABELS[request.track]} canDownload={Boolean(saved)} dirty={dirty} busy={Boolean(busy)} hasResult={Boolean(result)} onDownload={(kind,format)=>void download(kind,format)} onPolicyChanges={()=>void policyChanges()} />
      {saved&&<details className={styles.disclosure}><summary>Manage this saved case</summary>{!removeConfirm?<button type="button" className={styles.textButton} disabled={Boolean(busy)} onClick={()=>setRemoveConfirm(true)}>Remove saved case</button>:<div className={styles.notice}><p>Remove “{saved.title}” from the private case library? Downloaded copies will remain wherever you saved them.</p><div className={styles.actions}><button type="button" className={styles.secondary} disabled={Boolean(busy)} onClick={()=>void deleteCase()}>Remove this case</button><button type="button" className={styles.textButton} onClick={()=>setRemoveConfirm(false)}>Keep it</button></div></div>}</details>}
    </>}
  </div>;
}

import Link from "@/components/app-link";
import { SELF_DIRECTED_COURSES, selfDirectedHref } from "@/lib/content/self-directed";
import { ExplainerVideo } from "@/components/explainer-video";

/** The Core 15: the courses every staff member is encouraged to start with. Approved by the program lead, Oct 25, 2026. */
const CORE_FIFTEEN = [
  { title: "Start here", note: "A shared language for equity, access and everyday judgment", numbers: ["F21", "F02", "F05", "F09", "F10", "F15"] },
  { title: "Apply it", note: "Equity brought into real decisions and services", numbers: ["I09", "I10", "I21", "I15", "I17", "I06"] },
  { title: "Lead it", note: "The systems view that policy and leadership require", numbers: ["A09", "A20", "A21"] },
] as const;

export function CoreFifteen({ standalone = false }: { standalone?: boolean }) {
  const groups = CORE_FIFTEEN.map(group => ({
    ...group,
    courses: group.numbers.flatMap(number => {
      const course = SELF_DIRECTED_COURSES.find(item => item.number === number);
      const href = course ? selfDirectedHref("self-directed-" + course.number) : undefined;
      return course && href ? [{ number, title: course.title, href }] : [];
    }),
  }));
  const content = <div id="start-here" className="scroll-mt-24 space-y-4">
      <p className="max-w-3xl">Fifteen recommended courses for staff. Choose a course that fits your work and learn at your own pace.</p>
      <div className={standalone ? "space-y-8" : "grid gap-6 md:grid-cols-3"}>
        {groups.map(group => <div key={group.title}>
          <h3 className="text-lg font-bold">{group.title}</h3>
          <p className="text-muted">{group.note}</p>
          <ol className="mt-2 list-decimal space-y-1 pl-5">{group.courses.map(course => <li key={course.number}><Link href={course.href}>{course.title}</Link></li>)}</ol>
        </div>)}
      </div>
      <p><Link href="/learn/self-directed">See all 72 courses in the self-directed series</Link></p>
      <ExplainerVideo id="core-fifteen" />
    </div>;
  return standalone ? content : <details className="course-more-item" suppressHydrationWarning>
    <summary><h2 id="core-fifteen-title">The Core 15</h2></summary>
    {content}
  </details>;
}

"use client";
import { SourceLink } from "@/components/app-link";

import { useEffect, useState } from "react";
import { LearningAudio } from "@/components/learning-audio";
import { FeaturedMediaPanel } from "@/components/featured-media-panel";
type Guidance = {kind?:string;id:string;title:string;text:string;src?:string;afterBlock?:number;beforeScenario?:boolean};
type Discussion = { guidance?:Guidance[]; checkIn?:string; title:string; src:string; before:string; after:string; turns:{host:string;text:string}[] };
export function CourseAudioDiscussion({id}:{id:string}) {
 const [discussion,setDiscussion]=useState<Discussion>();
 useEffect(()=>{let active=true; fetch(`/learning/audio-discussions/${encodeURIComponent(id)}.json`).then(r=>r.ok?r.json():null).then(value=>{if(active&&value)setDiscussion(value);}).catch(()=>{});return()=>{active=false;};},[id]);
 if(!discussion)return null;
 return <FeaturedMediaPanel kind="audio"><section aria-label="Listen and reflect"><h2>{discussion.title}</h2><p>{discussion.before}</p><p>You can listen or read the conversation below, at your own pace.</p><LearningAudio src={discussion.src} title={discussion.title} /><p><SourceLink href={discussion.src} download>Download the discussion</SourceLink></p><details><summary>Read the complete conversation</summary>{discussion.turns.map((turn,index)=><p key={index}><strong>{turn.host==="host1"?"Host":"Co-host"}</strong><br/>{turn.text}</p>)}</details><p>{discussion.after}</p>{discussion.checkIn ? <details><summary>A moment to reflect</summary><p>{discussion.checkIn}</p></details> : null}</section></FeaturedMediaPanel>;
}

export function CourseAudioGuidance({id,afterBlock,beforeScenario}:{id:string;afterBlock?:number;beforeScenario?:boolean}) {
 const [clips,setClips]=useState<Guidance[]>([]);
 useEffect(()=>{let active=true;fetch(`/learning/audio-discussions/${encodeURIComponent(id)}.json`).then(r=>r.ok?r.json():null).then(d=>{if(active)setClips(d?.guidance??[]);}).catch(()=>{});return()=>{active=false;};},[id]);
 const selected=clips.filter(c=>beforeScenario?c.beforeScenario:afterBlock!==undefined&&c.afterBlock===afterBlock);
 if(!selected.length)return null;
 return <aside aria-label="A little more to consider">{selected.map(c=><section key={c.id}><h2>{c.title}</h2>{c.src?<><LearningAudio src={c.src} title={c.title} /><p><SourceLink href={c.src} download>Download audio</SourceLink></p></>:null}<details open={!c.src}><summary>{c.kind==="explainer"?"Read this explanation":"Read this reflection"}</summary><p>{c.text}</p></details></section>)}</aside>;
}

"use client";
import { GeffenLessonReadAloud } from "./geffen-course-read-aloud";
import { useEffect, useId, useState, type ReactNode } from "react";
import Link from "@/components/app-link";
import { CourseAudioDiscussion, CourseAudioGuidance } from "./course-audio-discussion";
import { CourseMediaSlot } from "./course-media-for-page";
import type { Block, Lesson } from "@/lib/content/courses/source-types";
import { lessonImageOverrides } from "@/lib/content/courses/lesson-image-overrides";
import { duplicateLessonImageKeys } from "@/lib/content/courses/lesson-image-repeat-suppression";
import { FocusedSections } from "./focused-sections";

type State={schemaVersion:1;fields:Record<string,string>;submitted:Record<string,boolean>;completed:boolean};
const blank=():State=>({schemaVersion:1,fields:{},submitted:{},completed:false});
function validState(value:unknown):value is State { if(!value||typeof value!=="object"||Array.isArray(value))return false; const state=value as State;return state.schemaVersion===1&&typeof state.completed==="boolean"&&!!state.fields&&typeof state.fields==="object"&&!Array.isArray(state.fields)&&!!state.submitted&&typeof state.submitted==="object"&&!Array.isArray(state.submitted)&&Object.values(state.fields).every(item=>typeof item==="string")&&Object.values(state.submitted).every(item=>typeof item==="boolean"); }
function Rich({text}:{text:string}) {return <div className="course-rich" dangerouslySetInnerHTML={{__html:text}}/>;}
/** Authored blocks that close a lesson; they join the "Finish this lesson" tabs instead of standing as sections of their own. */
const CLOSING_BLOCK_HEADINGS=/^(continue your learning|put this lesson into practice|put this lesson to work)$/i;
export function CourseLesson({courseId,lesson,objectives,previous,next,companion,courseOverviewHref}:{courseId:string;lesson:Lesson;objectives:string[];previous?:string;next?:string;companion?:ReactNode;courseOverviewHref?:string}) {
  const overviewHref=courseOverviewHref??`/courses/${courseId}`;
  const [state,setState]=useState<State>(blank); const [loaded,setLoaded]=useState(false); const [message,setMessage]=useState(""); const uid=useId();
  const storageKey=`pac-course:${courseId}:${lesson.id}`;
  useEffect(()=>{let active=true;Promise.resolve().then(()=>{if(!active)return;try{const raw=localStorage.getItem(storageKey);if(raw){const saved:unknown=JSON.parse(raw);if(!validState(saved))throw new Error("Invalid saved notes");setState(saved);}}catch{setMessage("Your saved progress could not be opened. You can still work through this lesson.");}setLoaded(true);});return()=>{active=false;};},[storageKey]);
  function save(nextState:State) {setState(nextState);try{localStorage.setItem(storageKey,JSON.stringify(nextState));localStorage.setItem(`pac-course-resume:${courseId}`,lesson.id);setMessage("Saved.");}catch{setMessage("Your progress could not be saved. You can continue while this page is open; note your place before leaving.");}}
  const field=(key:string,value:string)=>save({...state,fields:{...state.fields,[key]:value},submitted:{...state.submitted,[key]:false}});
  const submit=(key:string)=>save({...state,submitted:{...state.submitted,[key]:true}});
  const reset=(key:string)=>save({...state,fields:{...state.fields,[key]:""},submitted:{...state.submitted,[key]:false}});
  function downloadDraft(text:string,index:number) {
    let url:string|undefined;let link:HTMLAnchorElement|undefined;
    try {url=URL.createObjectURL(new Blob([text],{type:"text/plain;charset=utf-8"}));link=document.createElement("a");link.href=url;link.download=`${courseId}-${lesson.id}-${index}.txt`;document.body.appendChild(link);link.click();setMessage("Your download has started. Look for the example in your downloads.");}
    catch {setMessage("The download could not start. You can copy the example shown above and keep it in your own document.");}
    finally {link?.remove();if(url){const pending=url;setTimeout(()=>URL.revokeObjectURL(pending),1000);}}
  }
  function render(block:Block,index:number) {
    const key=`block-${index}`;const inputId=`${uid}-${key}`;
    switch(block.type){
      case "text":return <section>{block.heading?<h2>{block.heading}</h2>:null}<Rich text={block.body}/></section>;
      case "image":{const replacement=lessonImageOverrides[block.src];const caption=replacement?.caption??block.caption;if(duplicateLessonImageKeys.has(`${courseId}|${lesson.id}|${index}`))return caption?<p className="course-image-note">{caption}</p>:null;return <figure><img src={replacement?.src??block.src} alt={replacement?.alt??block.alt} loading="lazy"/>{caption?<figcaption>{caption}</figcaption>:null}</figure>;}
      case "statement":return <aside className="course-statement"><Rich text={block.body}/></aside>;
      case "quote":return <blockquote><Rich text={block.text}/>{block.cite?<cite>{block.cite}</cite>:null}</blockquote>;
      case "list":{const List=block.ordered?"ol":"ul";return <section>{block.heading?<h2>{block.heading}</h2>:null}<List>{block.items.map((item,i)=><li key={i}><Rich text={item}/></li>)}</List></section>;}
      case "leaderMove":return <section><h2>{block.heading??"Put it into practice"}</h2><h3>What you can change</h3><Rich text={block.control}/><h3>What to watch for</h3><Rich text={block.failure}/><h3>Your next step</h3><Rich text={block.next}/></section>;
      case "accordion":return <section>{block.heading?<h2>{block.heading}</h2>:null}{block.items.map((item,i)=><details key={i}><summary>{item.title}</summary><Rich text={item.body}/></details>)}</section>;
      case "flashcards":return <section>{block.heading?<h2>{block.heading}</h2>:null}<div className="course-flashcards">{block.cards.map((card,i)=><details key={i}><summary><Rich text={card.front}/></summary><Rich text={card.back}/></details>)}</div></section>;
      case "tabs":{const saved=Number(state.fields[key]??0);const selected=Number.isInteger(saved)&&saved>=0&&saved<block.tabs.length?saved:0;return <section>{block.heading?<h2>{block.heading}</h2>:null}<div role="tablist" aria-label={block.heading??"Explore perspectives"}>{block.tabs.map((tab,i)=><button key={i} role="tab" id={`${inputId}-tab-${i}`} aria-controls={`${inputId}-panel-${i}`} aria-selected={selected===i} tabIndex={selected===i?0:-1} onKeyDown={event=>{const count=block.tabs.length;const nextIndex=event.key==="ArrowRight"?(i+1)%count:event.key==="ArrowLeft"?(i+count-1)%count:event.key==="Home"?0:event.key==="End"?count-1:undefined;if(nextIndex!==undefined){event.preventDefault();field(key,String(nextIndex));document.getElementById(`${inputId}-tab-${nextIndex}`)?.focus();}}} onClick={()=>field(key,String(i))}>{tab.label}</button>)}</div>{block.tabs.map((tab,i)=><div key={i} role="tabpanel" id={`${inputId}-panel-${i}`} aria-labelledby={`${inputId}-tab-${i}`} hidden={selected!==i}><Rich text={tab.body}/></div>)}</section>;}
      case "timeline":return <section>{block.heading?<h2>{block.heading}</h2>:null}<ol className="course-timeline">{block.events.map((event,i)=><li key={i}><h3>{event.year} — {event.title}</h3><Rich text={event.body}/></li>)}</ol></section>;
      case "knowledgeCheck":{const chosen=state.fields[key];const checked=state.submitted[key];const correct=block.options[Number(chosen)]?.correct;return <fieldset><legend>{block.question}</legend>{block.options.map((option,i)=><label key={i} className="course-choice"><input type="radio" name={inputId} checked={chosen===String(i)} onChange={()=>field(key,String(i))}/><Rich text={option.text}/></label>)}<button disabled={!loaded||chosen===undefined||chosen===""} onClick={()=>submit(key)}>Check answer</button><button onClick={()=>reset(key)}>Try again</button>{checked?<div role="status"><Rich text={correct?block.feedbackCorrect:block.feedbackIncorrect}/></div>:null}</fieldset>;}
      case "sorting":{const selections=block.items.map((_,i)=>state.fields[`${key}-${i}`]??"");return <fieldset><legend>{block.heading??"Match each example"}</legend>{block.items.map((item,i)=><label className="course-sort" key={i}><Rich text={item.text}/><select aria-label={`Category for ${item.text.replace(/<[^>]*>/g,"")}`} value={selections[i]} onChange={event=>save({...state,fields:{...state.fields,[`${key}-${i}`]:event.target.value},submitted:{...state.submitted,[key]:false}})}><option value="">Choose a category</option>{block.categories.map(category=><option key={category}>{category}</option>)}</select>{state.submitted[key]?<span>{selections[i]===item.category?"That fits.":`Consider: ${item.category}`}</span>:null}</label>)}<button disabled={!loaded||selections.some(value=>!value)} onClick={()=>submit(key)}>Check matches</button><button onClick={()=>save({...state,fields:{...state.fields,...Object.fromEntries(block.items.map((_,i)=>[`${key}-${i}`,""]))},submitted:{...state.submitted,[key]:false}})}>Reset</button></fieldset>;}
      case "artifact":return <section><h2>{block.title}</h2><Rich text={block.summary}/>{block.fields.map((item,i)=><p className="course-note" key={i}><strong>{item.label}</strong> {item.value}</p>)}<Rich text={block.action}/><p className="notice" role="note">Download this example to adapt it in your own document.</p><button onClick={()=>downloadDraft(block.title+"\n\n"+block.fields.map((item)=>item.label+": "+item.value).join("\n\n"),index)}>Download this example</button></section>;
      default:throw new Error(`Unsupported course block: ${block.type}`);
    }
  }
  // The lesson's closing parts (a situation to try, what to carry forward, a next step, and
  // the authored "put it into practice" and "continue your learning" blocks) used to stack as
  // five or six full sections. They now share one "Finish this lesson" area with a tab for each
  // part. Every word is still on the page; only one part is open at a time.
  const closingIndexes=lesson.blocks.flatMap((block,index)=>"heading" in block&&typeof block.heading==="string"&&CLOSING_BLOCK_HEADINGS.test(block.heading.trim())?[index]:[]);
  // Keep supporting images, examples and quotations with their authored topic.
  // Original block indexes remain the keys for saved answers and audio cues.
  const topics: Array<{ title: string; indexes: number[] }> = [];
  lesson.blocks.forEach((block,index) => {
    if (closingIndexes.includes(index)) return;
    const title = "heading" in block && block.heading ? block.heading
      : block.type === "artifact" ? block.title
      : block.type === "knowledgeCheck" ? "Check your understanding"
      : block.type === "sorting" ? "Match each example"
      : block.type === "leaderMove" ? "Put it into practice" : "";
    if (title || !topics.length) topics.push({ title: title || "Explore the lesson", indexes: [] });
    topics[topics.length - 1].indexes.push(index);
  });
  const finishParts:Array<{label:string;body:ReactNode}>=[
    ...(lesson.scenario?[{label:"Try a situation",body:<><Rich text={lesson.scenario.context}/><fieldset><legend>{lesson.scenario.prompt}</legend>{lesson.scenario.options.map((option,i)=><label className="course-choice" key={i}><input type="radio" name={`${uid}-scenario`} checked={state.fields.scenario===String(i)} onChange={()=>field("scenario",String(i))}/><Rich text={option.label}/></label>)}<button disabled={!state.fields.scenario} onClick={()=>submit("scenario")}>Consider your choice</button><button onClick={()=>reset("scenario")}>Try another response</button>{state.submitted.scenario?<div role="status"><Rich text={lesson.scenario.options[Number(state.fields.scenario)]?.response??""}/></div>:null}</fieldset></>}]:[]),
    ...(lesson.learning?.takeaways.length?[{label:"Carry this forward",body:<><ul>{lesson.learning.takeaways.map((item,i)=><li key={i}><Rich text={item}/></li>)}</ul><Rich text={lesson.learning.evidence}/><Rich text={lesson.learning.appliedNextStep}/></>}]:[]),
    ...(lesson.transfer?[{label:"Your next step",body:<><Rich text={lesson.transfer.prompt}/>{lesson.transfer.options.map((option,i)=><label className="course-choice" key={i}><input type="radio" name={`${uid}-transfer`} checked={state.fields.transfer===String(i)} onChange={()=>field("transfer",String(i))}/><Rich text={option}/></label>)}</>}]:[]),
    ...closingIndexes.map(index=>{const block=lesson.blocks[index];return {label:("heading" in block&&typeof block.heading==="string"?block.heading:"More"),body:<div className="course-finish-block" data-course-block={block.type}>{render(block,index)}</div>};}),
  ];
  const savedFinish=Number(state.fields.finish??0);
  const finishSelected=Number.isInteger(savedFinish)&&savedFinish>=0&&savedFinish<finishParts.length?savedFinish:0;
  const finishId=`${uid}-finish`;
  return <article className="course-lesson"><p>{lesson.minutes} minutes</p><h1>{lesson.title}</h1><Rich text={lesson.summary}/>{/* Listening comes right under the title, before the objectives and activities. */}<GeffenLessonReadAloud courseId={courseId} lesson={lesson} objectives={objectives} />{courseId === "gc-structural-racism" && lesson.id === "gc-structural-racism-1" ? <CourseAudioDiscussion id="gc-structural-racism" /> : null}<CourseMediaSlot /><section><h2>What you’ll be able to do</h2><ul>{objectives.map((objective,i)=><li key={i}>{objective}</li>)}</ul></section><fieldset disabled={!loaded} className="course-activities"><FocusedSections label="In this lesson">{topics.map((topic,topicIndex)=><section key={topicIndex} id={`lesson-topic-${topicIndex+1}`} data-topic-title={topic.title}>{topic.indexes.map(index=><div key={index} data-course-block={lesson.blocks[index].type}>{render(lesson.blocks[index],index)}{courseId === "gc-structural-racism" && lesson.id === "gc-structural-racism-1" ? <CourseAudioGuidance id="gc-structural-racism" afterBlock={index} /> : null}</div>)}</section>)}
    {companion ? <section id="lesson-companion" data-topic-title="Explore further">{companion}</section> : null}
    {courseId === "gc-structural-racism" && lesson.id === "gc-structural-racism-1" ? <CourseAudioGuidance id="gc-structural-racism" beforeScenario /> : null}
    {finishParts.length?<section className="course-finish" aria-labelledby={`${finishId}-title`}><h2 id={`${finishId}-title`}>Finish this lesson</h2>
      {finishParts.length>1?<div role="tablist" aria-label="Finish this lesson">{finishParts.map((part,i)=><button key={i} type="button" role="tab" id={`${finishId}-tab-${i}`} aria-controls={`${finishId}-panel-${i}`} aria-selected={finishSelected===i} tabIndex={finishSelected===i?0:-1} onKeyDown={event=>{const count=finishParts.length;const nextIndex=event.key==="ArrowRight"?(i+1)%count:event.key==="ArrowLeft"?(i+count-1)%count:event.key==="Home"?0:event.key==="End"?count-1:undefined;if(nextIndex!==undefined){event.preventDefault();field("finish",String(nextIndex));document.getElementById(`${finishId}-tab-${nextIndex}`)?.focus();}}} onClick={()=>field("finish",String(i))}>{part.label}</button>)}</div>:<h3>{finishParts[0].label}</h3>}
      {finishParts.map((part,i)=><div key={i} className="course-finish-panel" role={finishParts.length>1?"tabpanel":undefined} id={`${finishId}-panel-${i}`} aria-labelledby={finishParts.length>1?`${finishId}-tab-${i}`:undefined} hidden={finishParts.length>1&&finishSelected!==i}>{part.body}</div>)}
      <p className="course-finish-plan"><Link href={`/my-work/action-plan?from=${encodeURIComponent(lesson.title)}`}>Turn this lesson into an action plan</Link>: one change you will try, a first step and a date to look back. It stays on this computer.</p>
    </section>:null}
    </FocusedSections>
    <p className="notice" role="note">Your activity choices and lesson progress are saved in this browser. Keep any personal reflection notes in your own document.</p>
    <label className="course-choice"><input type="checkbox" checked={state.completed} onChange={event=>save({...state,completed:event.target.checked})}/>Mark this lesson complete</label>
    <button onClick={()=>{if(window.confirm("Clear your answers and progress for this lesson?"))save(blank());}}>Reset this lesson</button></fieldset><p role="status">{message}</p><nav aria-label="Lesson navigation">{previous?<Link href={previous}>Previous lesson</Link>:<Link href={overviewHref}>Course overview</Link>}{next?<Link href={next}>Next lesson</Link>:<Link href={overviewHref}>Back to course</Link>}</nav></article>;
}

"use client";
import { SourceLink } from "@/components/app-link";

import { FeaturedMediaPanel } from "@/components/featured-media-panel";

import { useState } from "react";
import content from "@/lib/content/cultural-intelligence-explainer-draft.json";

export type ExplainerMedia = { video: string; captions: string };

/** Shape checking is not media verification. The future parent must supply only independently verified assets. */
function availableMedia(id: string, media?: ExplainerMedia): media is ExplainerMedia {
  if (!/^0[1-3]$/.test(id) || !media) return false;
  const base = `/learning/cultural-intelligence/${id}/`;
  return media.video === `${base}lesson.mp4` && media.captions === `${base}captions.vtt`;
}

/** Isolated draft. Not connected to a route; finished, verified media must be integrated separately. */
export function CulturalIntelligenceExplainerDraft({ media = {} }: { media?: Record<string, ExplainerMedia> }) {
  const [selected, setSelected] = useState<Record<string, number>>({});

  return <div className="space-y-10">
    <p>Explore these topics in any order. Your practice choices stay on this page and are not saved when you leave or reload it.</p>
    {content.lessons.map(lesson => <section key={lesson.id} aria-labelledby={`explainer-${lesson.id}`} className="space-y-5 border-t border-line pt-6">
      <h4 id={`explainer-${lesson.id}`} className="text-2xl font-semibold">{lesson.title}</h4>
      {availableMedia(lesson.id, media[lesson.id]) ? <FeaturedMediaPanel kind="video"><div className="space-y-3">
        <video controls playsInline preload="metadata" aria-label={lesson.title}>
          <source src={media[lesson.id].video} type="video/mp4" />
          <track kind="captions" src={media[lesson.id].captions} srcLang="en" label="English" default />
          Your browser cannot play this video. You can read the lesson below.
        </video>
        <p><SourceLink href={media[lesson.id].captions}>Download the captions</SourceLink></p>
      </div></FeaturedMediaPanel> : <p>You can read the lesson below.</p>}
      <p>If you’re reading, take a moment to choose your response before continuing.</p>
      <details className="rounded-xl border border-line p-5">
        <summary className="cursor-pointer font-semibold">Read {lesson.title}</summary>
        <div className="mt-5 space-y-6">{lesson.chapters.map(chapter => <section key={chapter.title}>
          <h5 className="text-xl font-semibold">{chapter.title}</h5>
          {chapter.paragraphs.map((paragraph, index) => <p key={index} className="mt-3 leading-7">{paragraph}</p>)}
        </section>)}</div>
      </details>
      <fieldset className="space-y-3 rounded-xl border border-line p-5">
        <legend className="font-semibold">{lesson.question}</legend>
        {lesson.choices.map((choice, index) => <label key={index} className="flex cursor-pointer items-start gap-3">
          <input type="radio" name={`practice-${lesson.id}`} value={index} checked={selected[lesson.id] === index}
            onChange={() => setSelected(current => ({ ...current, [lesson.id]: index }))} />
          <span>{choice.text}</span>
        </label>)}
        <div role="status" aria-live="polite" className="leading-7">
          {selected[lesson.id] !== undefined ? lesson.choices[selected[lesson.id]].feedback : ""}
        </div>
      </fieldset>
    </section>)}
  </div>;
}

"use client";

