const BLANK_WAVE = { wave: "", fielded: "", respondents: "", responseRate: "", belonging: "", inclusion: "", engagement: "" };

function SurveySection({ waves, onChanged }: { waves: SurveyWave[]; onChanged: (result: Promise<{ ok: boolean; error?: string }> | { ok: boolean; error?: string }) => Promise<void> }) {
  const [form, setForm] = useState(BLANK_WAVE);
  const [status, setStatus] = useState("");
  const [busy, setBusy] = useState(false);
  const setF = (k: keyof typeof BLANK_WAVE) => (v: string) => setForm((f) => ({ ...f, [k]: v }));

  const edit = (w: SurveyWave) => setForm({ wave: w.wave, fielded: w.fielded, respondents: String(w.respondents), responseRate: String(Math.round(w.responseRate * 100)), belonging: String(w.belonging), inclusion: String(w.inclusion), engagement: String(w.engagement) });

  async function save(e: FormEvent) {
    e.preventDefault();
    setBusy(true);
    setStatus("");
    const values: SurveyWaveValues = { fielded: form.fielded.trim(), respondents: Number(form.respondents), responseRate: Number(form.responseRate) / 100, belonging: Number(form.belonging), inclusion: Number(form.inclusion), engagement: Number(form.engagement) };
    const result = await post("/api/equity-analysis/survey-waves", { eventId: crypto.randomUUID(), wave: form.wave.trim(), action: "set", values });
    await onChanged(result);
    if (result.ok) { setStatus(`Wave ${form.wave.trim()} saved. The Equity Policy page now uses it.`); setForm(BLANK_WAVE); }
    setBusy(false);
  }

  async function remove(wave: string) {
    if (!window.confirm(`Remove the ${wave} wave? It stays in the change history and can be restored.`)) return;
    await onChanged(await post("/api/equity-analysis/survey-waves", { eventId: crypto.randomUUID(), wave, action: "remove" }));
  }

  const editing = Boolean(form.wave) && waves.some((w) => w.wave === form.wave.trim());

  return (
    <section aria-labelledby="survey-title">
      <h2 id="survey-title" className="m-0 text-2xl font-bold">Culture survey results</h2>
      <p className="mt-2 max-w-3xl">One row per survey wave: percent favorable for the three items the Equity Policy page tracks, respondents, and response rate. {waves.length ? "The Equity Policy page shows these results." : "Until the first wave is entered, the Equity Policy page shows no survey figures."}</p>
      <div className="mt-4 grid gap-6 lg:grid-cols-5">
        <div className="min-w-0 self-start overflow-x-auto rounded border border-line bg-white lg:col-span-3">
          <table className="data w-full min-w-[40rem]">
            <thead>
              <tr><th scope="col">Wave</th><th scope="col">Fielded</th><th scope="col" className="text-right">Belonging</th><th scope="col" className="text-right">Inclusion</th><th scope="col" className="text-right">Engagement</th><th scope="col" className="text-right">Respondents</th><th scope="col" className="text-right">Response</th><th scope="col" className="relative"><span className="sr-only">Actions</span></th></tr>
            </thead>
            <tbody>
              {waves.length ? waves.map((w) => (
                <tr key={w.wave}>
                  <td className="font-semibold">{w.wave}</td><td>{w.fielded}</td>
                  <td className="text-right tabular-nums">{w.belonging}%</td><td className="text-right tabular-nums">{w.inclusion}%</td><td className="text-right tabular-nums">{w.engagement}%</td>
                  <td className="text-right tabular-nums">{fmt(w.respondents)}</td><td className="text-right tabular-nums">{Math.round(w.responseRate * 100)}%</td>
                  <td className="whitespace-nowrap"><button type="button" className="btn btn--ghost !min-h-0 !px-2 !py-1 !text-xs" onClick={() => edit(w)}>Edit</button> <button type="button" className="btn btn--ghost !min-h-0 !px-2 !py-1 !text-xs" onClick={() => remove(w.wave)}>Remove</button></td>
                </tr>
              )) : <tr><td colSpan={8} className="text-muted">No waves entered yet.</td></tr>}
            </tbody>
          </table>
        </div>
        <form onSubmit={save} className="card min-w-0 lg:col-span-2">
          <h3 className="m-0 text-xl font-bold">{editing ? `Update ${form.wave.trim()}` : "Add a wave"}</h3>
          <div className="mt-3 grid grid-cols-2 gap-3">
            <Text label="Wave" value={form.wave} onChange={setF("wave")} placeholder="2026" required />
            <Text label="Fielded (year-month)" value={form.fielded} onChange={setF("fielded")} placeholder="2026-10" required />
            <Text label="Belonging %" type="number" value={form.belonging} onChange={setF("belonging")} required />
            <Text label="Inclusion %" type="number" value={form.inclusion} onChange={setF("inclusion")} required />
            <Text label="Engagement %" type="number" value={form.engagement} onChange={setF("engagement")} required />
            <Text label="Respondents" type="number" value={form.respondents} onChange={setF("respondents")} required />
            <Text label="Response rate %" type="number" value={form.responseRate} onChange={setF("responseRate")} required />
          </div>
          {status ? <p role="status" className="mt-3 text-sm text-green-strong">{status}</p> : null}
          <div className="mt-4 flex flex-wrap gap-3">
            <button type="submit" className="btn" disabled={busy}>{busy ? "Saving…" : "Save wave"}</button>
            {form !== BLANK_WAVE ? <button type="button" className="btn btn--light" onClick={() => setForm(BLANK_WAVE)}>Clear</button> : null}
          </div>
        </form>
      </div>
    </section>
  );
}

function Text({ label, value, onChange, type = "text", placeholder, width = "w-full", required }: { label: string; value: string; onChange: (v: string) => void; type?: string; placeholder?: string; width?: string; required?: boolean }) {
  return (
    <label className="field block text-sm">
      <span className="font-semibold">{label}</span>
      <input type={type} value={value} placeholder={placeholder} required={required} onChange={(e) => onChange(e.target.value)} className={`${width} min-w-0 max-w-full`} />
    </label>
  );
}

function Select({ label, value, onChange, options }: { label: string; value: string; onChange: (v: string) => void; options: readonly (readonly [string, string])[] }): ReactNode {
  return (
    <label className="field block text-sm">
      <span className="font-semibold">{label}</span>
      <select value={value} onChange={(e) => onChange(e.target.value)} className="max-w-full">
        <option value="">All</option>
        {options.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
      </select>
    </label>
  );
}

"use client";

import { useEffect, useMemo, useState, useSyncExternalStore, type ChangeEvent, type ReactNode } from "react";
import Link from "@/components/app-link";
import { useRouter } from "next/navigation";
import { useProgramContext } from "@/components/program-context";
import { BROWSER_STORAGE_KEYS } from "@/lib/client/storage-keys";
import { formatDate } from "@/lib/equity-analysis/format";
import {
  ANALYSIS_KINDS,
  ANSWER_FIELD_IDS,
  choiceLabel,
  KIND_LABEL,
  missingRequired,
  stepsFor,
  type AnalysisKind,
  type Answers,
  type Field,
  type Step,
} from "@/lib/equity-analysis/model";

const DRAFT_KEY = BROWSER_STORAGE_KEYS.equityAnalysisDraft;

type Draft = { kind: AnalysisKind; answers: Answers; step: number };
type Screen = { view: "intro" } | { view: "step"; index: number } | { view: "review" };

function readStoredDraft(): string | null {
  try {
    return window.localStorage.getItem(DRAFT_KEY);
  } catch {
    return null;
  }
}

const noSubscription = () => () => {};

function parseDraft(raw: string | null): Draft | null {
  try {
    if (!raw) return null;
    const d = JSON.parse(raw) as Partial<Draft>;
    if (!d.kind || !ANALYSIS_KINDS.includes(d.kind)) return null;
    return { kind: d.kind, answers: d.answers ?? {}, step: typeof d.step === "number" ? d.step : 0 };
  } catch {
    return null;
  }
}

function writeDraft(draft: Draft | null) {
  try {
    if (draft) window.localStorage.setItem(DRAFT_KEY, JSON.stringify(draft));
    else window.localStorage.removeItem(DRAFT_KEY);
  } catch {
    /* the walkthrough still works for this visit */
  }
}

export function EquityAnalysisWalkthrough() {
  const router = useRouter();
  const { context } = useProgramContext();
  const [kind, setKind] = useState<AnalysisKind>("full");
  const [answers, setAnswers] = useState<Answers>({});
  const [screen, setScreen] = useState<Screen>({ view: "intro" });
  const [showErrors, setShowErrors] = useState(false);
  const [consent, setConsent] = useState(false);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [submissionId, setSubmissionId] = useState<string | null>(null);

  // The saved draft lives on the device, so it is read as an external value (empty during the first paint).
  const storedDraft = useSyncExternalStore(noSubscription, readStoredDraft, () => null);
  const savedDraft = useMemo(() => parseDraft(storedDraft), [storedDraft]);

  const steps = useMemo(() => stepsFor(kind), [kind]);
  const started = screen.view !== "intro";

  useEffect(() => {
    if (!started) return;
    writeDraft({ kind, answers, step: screen.view === "step" ? screen.index : steps.length });
  }, [started, kind, answers, screen, steps.length]);

  const set = (id: string, value: string) => setAnswers((a) => ({ ...a, [id]: value }));

  const goTo = (next: Screen) => {
    setShowErrors(false);
    setMessage("");
    setScreen(next);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const start = (k: AnalysisKind) => {
    setKind(k);
    setAnswers({});
    setConsent(false);
    goTo({ view: "step", index: 0 });
  };

  // A link can open the walkthrough on a chosen form, for example the Equity Pause path's "record this pause" link.
  useEffect(() => {
    if (started) return;
    const requested = new URLSearchParams(window.location.search).get("kind");
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (requested && (ANALYSIS_KINDS as readonly string[]).includes(requested)) start(requested as AnalysisKind);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const resume = () => {
    if (!savedDraft) return;
    setKind(savedDraft.kind);
    setAnswers(savedDraft.answers);
    const count = stepsFor(savedDraft.kind).length;
    goTo(savedDraft.step >= count ? { view: "review" } : { view: "step", index: savedDraft.step });
  };

  const continueFrom = (index: number) => {
    if (missingRequired(kind, answers, steps[index]).length) {
      setShowErrors(true);
      return;
    }
    goTo(index + 1 < steps.length ? { view: "step", index: index + 1 } : { view: "review" });
  };

  async function submit() {
    if (busy) return;
    setBusy(true);
    setMessage("");
    const id = submissionId ?? crypto.randomUUID();
    setSubmissionId(id);
    const detail: Record<string, string> = {};
    for (const key of ANSWER_FIELD_IDS) if (answers[key]?.trim()) detail[key] = answers[key].trim();
    try {
      const response = await fetch("/api/equity-analysis", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          submissionId: id,
          programScope: context === "one_dsd" ? "dsd" : "one-dhs",
          kind,
          workTitle: answers.work_title?.trim(),
          workType: answers.work_type,
          administration: answers.administration,
          approvalDate: answers.approval_date || undefined,
          disposition: answers.disposition,
          answers: detail,
          consent: true,
          sourceRoute: "/equity-policy/analysis",
        }),
      });
      const result = await response.json();
      if (!response.ok) {
        setMessage(result.error || "Your analysis could not be added. Your draft is still here.");
        return;
      }
      writeDraft(null);
      router.push(`/equity-policy/analysis/${result.id}`);
    } catch {
      setMessage("Your analysis could not be confirmed. Your draft is still here; you can try again.");
    } finally {
      setBusy(false);
    }
  }

  if (screen.view === "intro") return <Intro savedDraft={savedDraft} onStart={start} onResume={resume} />;

  const stepHeading = screen.view === "step" ? steps[screen.index].title : "Review and add to the record";

  return (
    <div className="space-y-6">
      <div className="card">
        <p className="kicker m-0">{KIND_LABEL[kind]}</p>
        <h2 className="m-0 mt-1 text-2xl font-bold">{stepHeading}</h2>
        <Progress steps={steps} screen={screen} onJump={(i) => goTo({ view: "step", index: i })} />
      </div>
      {screen.view === "step" ? (
        <StepScreen
          step={steps[screen.index]}
          index={screen.index}
          count={steps.length}
          kind={kind}
          answers={answers}
          showErrors={showErrors}
          onChange={set}
          onBack={() => goTo(screen.index === 0 ? { view: "intro" } : { view: "step", index: screen.index - 1 })}
          onContinue={() => continueFrom(screen.index)}
        />
      ) : (
        <Review
          kind={kind}
          steps={steps}
          answers={answers}
          consent={consent}
          onConsent={setConsent}
          busy={busy}
          message={message}
          onEdit={(i) => goTo({ view: "step", index: i })}
          onSubmit={submit}
        />
      )}
    </div>
  );
}

function Progress({ steps, screen, onJump }: { steps: Step[]; screen: Screen; onJump: (index: number) => void }) {
  const current = screen.view === "step" ? screen.index : steps.length;
  return (
    <ol className="m-0 mt-4 flex list-none flex-wrap gap-1.5 p-0" aria-label="Progress">
      {steps.map((s, i) => {
        const state = i < current ? "done" : i === current ? "current" : "todo";
        const label = s.number === 0 ? "Start" : s.number === 9 ? "Decide" : `Step ${s.number}`;
        return (
          <li key={s.id}>
            {state === "done" ? (
              <button type="button" onClick={() => onJump(i)} className="btn btn--light !min-h-0 !px-2.5 !py-1 !text-xs">
                {label}
              </button>
            ) : (
              <span aria-current={state === "current" ? "step" : undefined} className={`inline-block rounded px-2.5 py-1 text-xs font-semibold ${state === "current" ? "bg-navy text-white" : "bg-panel text-muted"}`}>
                {label}
              </span>
            )}
          </li>
        );
      })}
      <li>
        <span aria-current={screen.view === "review" ? "step" : undefined} className={`inline-block rounded px-2.5 py-1 text-xs font-semibold ${screen.view === "review" ? "bg-navy text-white" : "bg-panel text-muted"}`}>
          Review
        </span>
      </li>
    </ol>
  );
}

