export type CountyMapProps = {
  /** Group shown first. Ignored when fixedGroup is set. */
  initialGroup?: GroupId;
  initialMeasure?: MeasureId;
  /** Locks the map to one group, for example on a community page. Hides the group picker. */
  fixedGroup?: GroupId;
  /** Smaller layout for embedding inside another page. */
  compact?: boolean;
  /** Heading text. */
  heading?: string;
  headingLevel?: 2 | 3;
};

type Tab = "map" | "ranked" | "table";
type SortKey = "name" | "value" | "difference" | "count" | "population";

const TABS: { id: Tab; label: string }[] = [
  { id: "map", label: "Map" },
  { id: "ranked", label: "Ranked list" },
  { id: "table", label: "Table" },
];

const MEASURE_TEXT: Record<MeasureId, { short: string; column: string; help: (date: string) => string }> = {
  population: {
    short: "Share of population",
    column: "Share of county population",
    help: date => `Share of each county's people who are in this group, ${date}.`,
  },
  services: {
    short: "Share of people receiving services",
    column: "Share of people receiving services",
    help: date =>
      `Share of people receiving home and community-based services in each county who are in this group, ${date}.`,
  },
  comparison: {
    short: "Services compared with population",
    column: "Service share compared with population share",
    help: () =>
      `Service share divided by population share. 1 means they match. Above 1 means the group is a bigger share of people receiving services than of the county. Shown only when at least ${MIN_COMPARE_COUNT} people in the group receive services.`,
  },
  "earned-income": {
    short: "Earned income",
    column: "Share who earned income",
    help: date => `Share of people receiving home and community-based waiver services who earned income, ${date}.`,
  },
};

const REQUIRED_NOTE =
  "County is the county responsible for paying for services, which may not be where a person lives. Figures describe groups and conditions, not any one person. Counts under 6 are not shown by the Department of Human Services.";

type Row = { place: Place; v: MeasureValue; diff: number | null };

type Bins = { breaks: number[]; labels: string[]; diverging: boolean };

function niceShare(v: number): number {
  return Math.round(v * 1000) / 1000;
}

function makeBins(measure: MeasureId, values: number[]): Bins {
  if (measure === "comparison") {
    return {
      breaks: [0.5, 0.8, 1.25, 2],
      labels: ["Under 0.5 times", "0.5 to under 0.8 times", "0.8 to under 1.25 times (close to a match)", "1.25 to under 2 times", "2 times or more"],
      diverging: true,
    };
  }
  const sorted = [...values].sort((a, b) => a - b);
  const breaks: number[] = [];
  if (sorted.length > 0) {
    for (const q of [0.2, 0.4, 0.6, 0.8]) {
      const b = niceShare(sorted[Math.min(sorted.length - 1, Math.floor(q * sorted.length))]);
      if (b > sorted[0] && (breaks.length === 0 || b > breaks[breaks.length - 1])) breaks.push(b);
    }
  }
  const labels: string[] = [];
  for (let i = 0; i <= breaks.length; i++) {
    if (breaks.length === 0) labels.push("All counties shown");
    else if (i === 0) labels.push(`Under ${formatPercent(breaks[0])}`);
    else if (i === breaks.length) labels.push(`${formatPercent(breaks[i - 1])} or more`);
    else labels.push(`${formatPercent(breaks[i - 1])} to under ${formatPercent(breaks[i])}`);
  }
  return { breaks, labels, diverging: false };
}

function binIndex(bins: Bins, v: number): number {
  let i = 0;
  while (i < bins.breaks.length && v >= bins.breaks[i]) i++;
  // Sequential scales with fewer than 5 bins still use the darkest color for the top bin.
  return bins.diverging ? i : i + (5 - (bins.breaks.length + 1));
}

function valueText(measure: MeasureId, v: MeasureValue): string {
  return v.status === "ok" ? formatValue(measure, v.value) : statusText(v.status);
}

export default function CountyMap({
  initialGroup = "all",
  initialMeasure = "population",
  fixedGroup,
  compact = false,
  heading = "Minnesota counties",
  headingLevel = 2,
}: CountyMapProps) {
  const data = getCountyData();
  const shapes = getCountyShapes();
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const startGroup = fixedGroup ?? initialGroup;
  const [groupState, setGroup] = useState<GroupId>(startGroup);
  const group = fixedGroup ?? groupState;
  const [measureState, setMeasure] = useState<MeasureId>(initialMeasure);
  const measure: MeasureId = measureAppliesTo(group, measureState) ? measureState : "earned-income";
  const [tab, setTab] = useState<Tab>("map");
  const [selected, setSelected] = useState<string>(STATEWIDE_FIPS);
  const [hovered, setHovered] = useState<string | null>(null);
  const [focusFips, setFocusFips] = useState<string>(counties()[0].fips);
  const [sort, setSort] = useState<{ key: SortKey; dir: "asc" | "desc" }>({ key: "name", dir: "asc" });
  const [filter, setFilter] = useState("");
  const pathRefs = useRef(new Map<string, SVGPathElement>());
  const tabRefs = useRef(new Map<Tab, HTMLButtonElement>());

  const countyList = useMemo(() => counties(), []);
  const state = statewide(group, measure);
  const measureMeta = data.measures[measure];

  const rows: Row[] = useMemo(
    () =>
      countyList.map(place => {
        const v = measureFor(place, group, measure);
        const diff = v.value != null && state.value != null ? v.value - state.value : null;
        return { place, v, diff };
      }),
    [countyList, group, measure, state.value],
  );
  const rowByFips = useMemo(() => new Map(rows.map(r => [r.place.fips, r])), [rows]);
  const bins = useMemo(
    () => makeBins(measure, rows.filter(r => r.v.value != null).map(r => r.v.value as number)),
    [measure, rows],
  );

  const Heading = headingLevel === 3 ? "h3" : "h2";
  const SubHeading = headingLevel === 3 ? "h4" : "h3";
  const hatchId = `${uid}-hatch`;

  function fillFor(v: MeasureValue): { className: string; style?: CSSProperties } {
    if (v.status === "ok" && v.value != null) {
      const i = binIndex(bins, v.value);
      return { className: bins.diverging ? styles[`div${i}`] : styles[`seq${i}`] };
    }
    if (v.status === "suppressed" || v.status === "too-few") {
      return { className: styles.hatched, style: { fill: `url(#${hatchId})` } };
    }
    return { className: styles.noData };
  }

  function chooseGroup(g: GroupId) {
    setGroup(g);
  }

  function selectPlace(fips: string) {
    setSelected(fips);
    setFocusFips(fips === STATEWIDE_FIPS ? focusFips : fips);
  }

  function onCountyKey(e: KeyboardEvent<SVGPathElement>, fips: string) {
    const idx = countyList.findIndex(c => c.fips === fips);
    let next = -1;
    if (e.key === "ArrowRight" || e.key === "ArrowDown") next = (idx + 1) % countyList.length;
    else if (e.key === "ArrowLeft" || e.key === "ArrowUp") next = (idx - 1 + countyList.length) % countyList.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = countyList.length - 1;
    else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      selectPlace(fips);
      return;
    } else if (e.key === "Escape") {
      setHovered(null);
      return;
    }
    if (next >= 0) {
      e.preventDefault();
      const f = countyList[next].fips;
      setFocusFips(f);
      pathRefs.current.get(f)?.focus();
    }
  }

  function onTabKey(e: KeyboardEvent<HTMLButtonElement>, current: Tab) {
    const i = TABS.findIndex(t => t.id === current);
    let n = -1;
    if (e.key === "ArrowRight") n = (i + 1) % TABS.length;
    else if (e.key === "ArrowLeft") n = (i - 1 + TABS.length) % TABS.length;
    else if (e.key === "Home") n = 0;
    else if (e.key === "End") n = TABS.length - 1;
    if (n >= 0) {
      e.preventDefault();
      setTab(TABS[n].id);
      tabRefs.current.get(TABS[n].id)?.focus();
    }
  }

  // ---------- Table ----------
  const tableRows = useMemo(() => {
    const q = filter.trim().toLowerCase();
    const list = rows.filter(r => !q || r.place.name.toLowerCase().includes(q));
    const dir = sort.dir === "asc" ? 1 : -1;
    const num = (r: Row): number | null => {
      switch (sort.key) {
        case "value":
          return r.v.value;
        case "difference":
          return r.diff;
        case "count":
          return r.v.count;
        case "population":
          return r.place.totalPopulation2025;
        default:
          return null;
      }
    };
    return [...list].sort((a, b) => {
      if (sort.key === "name") return dir * a.place.name.localeCompare(b.place.name);
      const x = num(a);
      const y = num(b);
      if (x == null && y == null) return a.place.name.localeCompare(b.place.name);
      if (x == null) return 1; // missing values always last
      if (y == null) return -1;
      return dir * (x - y) || a.place.name.localeCompare(b.place.name);
    });
  }, [rows, filter, sort]);

  function toggleSort(key: SortKey) {
    setSort(s => (s.key === key ? { key, dir: s.dir === "asc" ? "desc" : "asc" } : { key, dir: key === "name" ? "asc" : "desc" }));
  }

  function ariaSort(key: SortKey): "ascending" | "descending" | "none" {
    return sort.key === key ? (sort.dir === "asc" ? "ascending" : "descending") : "none";
  }

  const showCount = measure !== "population";
  const countHeader =
    measure === "earned-income" ? "People who earned income" : "People in this group receiving services";

  // ---------- Ranked list ----------
  const ranked = rows.filter(r => r.v.value != null).sort((a, b) => (b.v.value as number) - (a.v.value as number));
  const unranked = rows.filter(r => r.v.value == null);
  const maxValue = Math.max(state.value ?? 0, ...ranked.map(r => r.v.value as number), 0.0001);

  // ---------- Details ----------
  const selectedPlace = selected === STATEWIDE_FIPS ? statewidePlace() : rowByFips.get(selected)?.place ?? statewidePlace();
  const tip = hovered ? rowByFips.get(hovered) : undefined;
  const tipShape = hovered ? shapes.counties.find(c => c.fips === hovered) : undefined;

  const groupOptions = data.groups;
  const label = groupLabel(group);
  const scopeText = `${label}. ${MEASURE_TEXT[measure].short}`;

  return (
    <section className={`${styles.root} ${compact ? styles.compact : ""}`} aria-labelledby={`${uid}-title`}>
      <Heading id={`${uid}-title`} className={styles.title}>
        {heading}
      </Heading>

      <div className={styles.controls}>
        {fixedGroup ? (
          <p className={styles.fixedGroup}>
            Group: <strong>{label}</strong>
          </p>
        ) : (
          <div className={styles.field}>
            <label htmlFor={`${uid}-group`}>Group</label>
            <select id={`${uid}-group`} value={group} onChange={e => chooseGroup(e.target.value as GroupId)}>
              {groupOptions.map(g => (
                <option key={g.id} value={g.id}>
                  {g.label}
                </option>
              ))}
            </select>
          </div>
        )}
        <fieldset className={styles.measures}>
          <legend>What to show</legend>
          {(Object.keys(MEASURE_TEXT) as MeasureId[]).map(m => {
            const applies = measureAppliesTo(group, m);
            return (
              <label key={m} className={`${styles.measure} ${!applies ? styles.measureOff : ""}`}>
                <input
                  type="radio"
                  name={`${uid}-measure`}
                  value={m}
                  checked={measure === m}
                  disabled={!applies}
                  aria-describedby={!applies ? `${uid}-allnote` : undefined}
                  onChange={() => setMeasure(m)}
                />
                <span>{MEASURE_TEXT[m].short}</span>
              </label>
            );
          })}
          {group === "all" ? (
            <p id={`${uid}-allnote`} className={styles.hint}>
              For all people, shares are 100% in every county. Choose a group to see shares and comparisons.
            </p>
          ) : null}
        </fieldset>
      </div>

      <p className={styles.help}>{MEASURE_TEXT[measure].help(measureMeta.date)}</p>
      <p className={styles.statewideLine}>
        Statewide: <strong>{valueText(measure, state)}</strong>
      </p>

      <div role="tablist" aria-label="Ways to view the county figures" className={styles.tabs}>
        {TABS.map(t => (
          <button
            key={t.id}
            type="button"
            role="tab"
            id={`${uid}-tab-${t.id}`}
            aria-selected={tab === t.id}
            aria-controls={`${uid}-panel-${t.id}`}
            tabIndex={tab === t.id ? 0 : -1}
            className={styles.tab}
            ref={el => {
              if (el) tabRefs.current.set(t.id, el);
            }}
            onClick={() => setTab(t.id)}
            onKeyDown={e => onTabKey(e, t.id)}
          >
            {t.label}
          </button>
        ))}
      </div>

      <div className={styles.body}>
        <div className={styles.views}>
          {/* Map */}
          <div
            role="tabpanel"
            id={`${uid}-panel-map`}
            aria-labelledby={`${uid}-tab-map`}
            hidden={tab !== "map"}
            className={styles.panel}
          >
            <p id={`${uid}-maphelp`} className={styles.hint}>
              Point to or tab to a county to see its figure. Use the arrow keys to move between counties and Enter to
              show details. The table has the same figures.
            </p>
            <div className={styles.mapWrap}>
              <svg
                viewBox={shapes.viewBox}
                className={styles.map}
                role="group"
                aria-label={`Map of Minnesota counties. ${scopeText}.`}
                aria-describedby={`${uid}-maphelp`}
              >
                <defs>
                  <pattern id={hatchId} patternUnits="userSpaceOnUse" width="6" height="6" patternTransform="rotate(45)">
                    <rect width="6" height="6" className={styles.hatchBg} />
                    <line x1="0" y1="0" x2="0" y2="6" className={styles.hatchLine} />
                  </pattern>
                </defs>
                {shapes.counties.map(c => {
                  const r = rowByFips.get(c.fips);
                  if (!r) return null;
                  const f = fillFor(r.v);
                  const cmp = compareWithStatewide(measure, r.v.value, state.value);
                  return (
                    <path
                      key={c.fips}
                      d={c.d}
                      ref={el => {
                        if (el) pathRefs.current.set(c.fips, el);
                        else pathRefs.current.delete(c.fips);
                      }}
                      className={`${styles.county} ${f.className}`}
                      style={f.style}
                      tabIndex={focusFips === c.fips ? 0 : -1}
                      role="button"
                      aria-pressed={selected === c.fips}
                      aria-label={`${c.name}: ${valueText(measure, r.v)}${cmp ? `. ${cmp}` : ""}`}
                      data-fips={c.fips}
                      onMouseEnter={() => setHovered(c.fips)}
                      onMouseLeave={() => setHovered(h => (h === c.fips ? null : h))}
                      onFocus={() => {
                        setHovered(c.fips);
                        setFocusFips(c.fips);
                      }}
                      onBlur={() => setHovered(h => (h === c.fips ? null : h))}
                      onClick={() => selectPlace(c.fips)}
                      onKeyDown={e => onCountyKey(e, c.fips)}
                    />
                  );
                })}
                {[selected, hovered].map((fips, i) => {
                  const c = fips && fips !== STATEWIDE_FIPS ? shapes.counties.find(s => s.fips === fips) : undefined;
                  return c ? (
                    <path key={`outline-${i}`} d={c.d} className={i === 0 ? styles.selectedOutline : styles.hoverOutline} aria-hidden="true" />
                  ) : null;
                })}
              </svg>
              {tip && tipShape ? (
                <div
                  className={styles.tooltip}
                  aria-hidden="true"
                  style={{
                    left: `${Math.min(80, Math.max(20, (tipShape.labelX / shapes.width) * 100))}%`,
                    top: `${(tipShape.labelY / shapes.height) * 100}%`,
                  }}
                >
                  <strong>{tip.place.name}</strong>
                  <span>{valueText(measure, tip.v)}</span>
                  {tip.v.status === "ok" ? (
                    <span className={styles.muted}>{compareWithStatewide(measure, tip.v.value, state.value)}</span>
                  ) : null}
                </div>
              ) : null}
            </div>

            <div className={styles.legend} aria-label="Map key" role="group">
              <p className={styles.legendTitle}>{MEASURE_TEXT[measure].column}</p>
              <ul>
                {bins.labels.map((l, i) => {
                  const idx = bins.diverging ? i : i + (5 - bins.labels.length);
                  return (
                    <li key={l}>
                      <svg width="18" height="14" aria-hidden="true" className={styles.swatch}>
                        <rect width="18" height="14" className={bins.diverging ? styles[`div${idx}`] : styles[`seq${idx}`]} />
                      </svg>
                      {l}
                    </li>
                  );
                })}
                <li>
                  <svg width="18" height="14" aria-hidden="true" className={styles.swatch}>
                    <rect width="18" height="14" style={{ fill: `url(#${hatchId})` }} className={styles.hatched} />
                  </svg>
                  {measure === "comparison" ? "Too few people to show or compare" : "Too few people to show"}
                </li>
                <li>
                  <svg width="18" height="14" aria-hidden="true" className={styles.swatch}>
                    <rect width="18" height="14" className={styles.noData} />
                  </svg>
                  No figure in the source
                </li>
              </ul>
            </div>
          </div>

          {/* Ranked list */}
          <div
            role="tabpanel"
            id={`${uid}-panel-ranked`}
            aria-labelledby={`${uid}-tab-ranked`}
            hidden={tab !== "ranked"}
            className={styles.panel}
          >
            <p className={styles.hint}>
              Counties from highest to lowest. The line in each bar marks the statewide figure,{" "}
              {valueText(measure, state)}.
            </p>
            <ol className={styles.ranked}>
              {ranked.map(r => (
                <li key={r.place.fips}>
                  <button
                    type="button"
                    className={`${styles.rankButton} ${selected === r.place.fips ? styles.rankSelected : ""}`}
                    aria-pressed={selected === r.place.fips}
                    onClick={() => selectPlace(r.place.fips)}
                  >
                    <span className={styles.rankName}>{r.place.name}</span>
                    <span className={styles.rankValue}>{formatValue(measure, r.v.value)}</span>
                    <span className={styles.bar} aria-hidden="true">
                      <span
                        className={`${styles.barFill} ${fillFor(r.v).className}`}
                        style={{ width: `${((r.v.value as number) / maxValue) * 100}%` }}
                      />
                      {state.value != null ? (
                        <span className={styles.stateMark} style={{ left: `${(state.value / maxValue) * 100}%` }} />
                      ) : null}
                    </span>
                    <span className={styles.rankCompare}>{compareWithStatewide(measure, r.v.value, state.value)}</span>
                  </button>
                </li>
              ))}
            </ol>
            {unranked.length > 0 ? (
              <>
                <SubHeading className={styles.smallHeading}>No figure shown ({unranked.length} counties)</SubHeading>
                <ul className={styles.unranked}>
                  {unranked.map(r => (
                    <li key={r.place.fips}>
                      {r.place.name}: {statusText(r.v.status).toLowerCase()}
                    </li>
                  ))}
                </ul>
              </>
            ) : null}
          </div>

          {/* Table */}
          <div
            role="tabpanel"
            id={`${uid}-panel-table`}
            aria-labelledby={`${uid}-tab-table`}
            hidden={tab !== "table"}
            className={styles.panel}
          >
            <div className={styles.field}>
              <label htmlFor={`${uid}-filter`}>Filter counties by name</label>
              <input
                id={`${uid}-filter`}
                type="search"
                value={filter}
                onChange={e => setFilter(e.target.value)}
                autoComplete="off"
              />
            </div>
            <p className={styles.hint} aria-live="polite">
              Showing {tableRows.length} of {rows.length} counties, plus Statewide.
            </p>
            <table className={styles.table}>
              <caption>
                {scopeText}, {measureMeta.date}. Select a column heading to sort.
              </caption>
              <thead>
                <tr>
                  {(
                    [
                      ["name", "County"],
                      ["value", MEASURE_TEXT[measure].column],
                      ["difference", "Compared with statewide"],
                      ...(showCount ? [["count", countHeader]] : []),
                      ["population", "Total population, 2025"],
                    ] as [SortKey, string][]
                  ).map(([k, text]) => (
                    <th key={k} scope="col" aria-sort={ariaSort(k)}>
                      <button type="button" className={styles.sortButton} onClick={() => toggleSort(k)}>
                        {text}
                        <span aria-hidden="true" className={styles.sortMark}>
                          {sort.key === k ? (sort.dir === "asc" ? " ▲" : " ▼") : ""}
                        </span>
                      </button>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {[{ place: statewidePlace(), v: state, diff: null } as Row, ...tableRows].map(r => {
                  const isState = r.place.fips === STATEWIDE_FIPS;
                  return (
                    <tr key={r.place.fips} className={isState ? styles.stateRow : undefined}>
                      <th scope="row" data-label="County">
                        <button type="button" className={styles.linkButton} onClick={() => selectPlace(r.place.fips)}>
                          {r.place.name}
                        </button>
                      </th>
                      <td data-label={MEASURE_TEXT[measure].column}>{valueText(measure, r.v)}</td>
                      <td data-label="Compared with statewide">
                        {isState ? "" : compareWithStatewide(measure, r.v.value, state.value)}
                      </td>
                      {showCount ? (
                        <td data-label={countHeader}>
                          {r.v.count != null
                            ? formatCount(r.v.count)
                            : r.v.status === "suppressed"
                              ? "Under 6"
                              : ""}
                        </td>
                      ) : null}
                      <td data-label="Total population, 2025">{formatCount(r.place.totalPopulation2025)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        <Details
          place={selectedPlace}
          group={group}
          measure={measure}
          onClear={() => setSelected(STATEWIDE_FIPS)}
          SubHeading={SubHeading}
        />
      </div>

      <p className={styles.note}>{REQUIRED_NOTE}</p>
      <SourceList SubHeading={SubHeading} />
    </section>
  );
}

function Details({
  place,
  group,
  measure,
  onClear,
  SubHeading,
}: {
  place: Place;
  group: GroupId;
  measure: MeasureId;
  onClear: () => void;
  SubHeading: "h3" | "h4";
}) {
  const isState = place.fips === STATEWIDE_FIPS;
  const measures: MeasureId[] = ["population", "services", "comparison", "earned-income"];
  const services = measureFor(place, group, "services");
  const cmp = measureFor(place, group, "comparison");
  const share2018 = populationShare2018(place, group);
  return (
    <aside className={styles.details} aria-live="polite" aria-label="Details for the selected place">
      <SubHeading className={styles.detailsTitle}>{place.name}</SubHeading>
      <p className={styles.muted}>{groupLabel(group)}</p>
      <dl className={styles.facts}>
        {measures
          .filter(m => measureAppliesTo(group, m))
          .map(m => {
            const v = measureFor(place, group, m);
            const s = statewide(group, m);
            return (
              <div key={m} className={m === measure ? styles.currentFact : undefined}>
                <dt>{MEASURE_TEXT[m].short}</dt>
                <dd>
                  {valueText(m, v)}
                  {!isState && v.status === "ok" && s.value != null ? (
                    <span className={styles.muted}>
                      {" "}
                      ({compareWithStatewide(m, v.value, s.value).toLowerCase()}; statewide {formatValue(m, s.value)})
                    </span>
                  ) : null}
                  {m === "population" && share2018 != null && v.value != null ? (
                    <span className={styles.muted}> In 2018: {formatPercent(share2018)}.</span>
                  ) : null}
                </dd>
              </div>
            );
          })}
        {group !== "all" ? (
          <div>
            <dt>People counted for the comparison</dt>
            <dd>
              {services.count != null && services.countyCount != null
                ? `${formatCount(services.count)} of ${formatCount(services.countyCount)} people receiving services`
                : services.status === "suppressed"
                  ? "Under 6 people. Too few people to show."
                  : "No figure in the source."}
              {cmp.status === "too-few" ? ` Too few people to compare (fewer than ${MIN_COMPARE_COUNT}).` : ""}
            </dd>
          </div>
        ) : null}
        <div>
          <dt>Total population, 2025</dt>
          <dd>{formatCount(place.totalPopulation2025) || "No figure in the source"}</dd>
        </div>
        <div>
          <dt>Speak a language other than English at home</dt>
          <dd>{place.nonEnglishShare != null ? formatPercent(place.nonEnglishShare) : "No figure in the source"}</dd>
        </div>
      </dl>
      {!isState ? (() => {
        const agency = agencyForCounty(place.fips);
        return agency ? <p>
          <strong>County agency:</strong> <SourceLink href={`/community-outreach/county-agencies#county-${agency.fips}`}>{agency.agencyName}</SourceLink>
          {agency.phone ? <>, <SourceLink href={`tel:${agency.phone.replace(/[^0-9]/g, "")}`}>{agency.phone}</SourceLink></> : null}
          {" · "}<SourceLink href={`/community-outreach/providers?county=${encodeURIComponent(place.name)}`}>Providers and designated agencies</SourceLink>
        </p> : null;
      })() : null}
      {!isState ? (
        <button type="button" className={styles.clear} onClick={onClear}>
          Show statewide figures
        </button>
      ) : (
        <p className={styles.hint}>Select a county on the map, list or table to see its figures here.</p>
      )}
    </aside>
  );
}

function SourceList({ SubHeading }: { SubHeading: "h3" | "h4" }) {
  const data = getCountyData();
  const m = data.measures;
  const dates: [string, string][] = [
    ["Share of population", `${m.population.date} (also ${m.population.compareDate})`],
    ["People receiving home and community-based services", `${m.services.date}, all ages`],
    ["Earned income", `${m["earned-income"].date}, all ages, everyone receiving waiver services`],
    ["Total population", m.totalPopulation.date],
    ["Language spoken at home", "5-year survey estimates, labeled 2017 to 2021 in the file"],
  ];
  return (
    <div className={styles.sources}>
      <SubHeading className={styles.smallHeading}>Sources and dates</SubHeading>
      <ul>
        {dates.map(([k, v]) => (
          <li key={k}>
            {k}: {v}
          </li>
        ))}
      </ul>
      <ul>
        {data.sources.map(s => (
          <li key={s.id}>
            <SourceLink href={s.url}>{s.title}</SourceLink>. {s.publisher}. {s.date}.
          </li>
        ))}
      </ul>
      <p className={styles.muted}>
        People whose services are paid for by a multi-county human services agency or a Tribal Nation are counted in
        the statewide figures but not in any county.
      </p>
    </div>
  );
}

import { GROUP_IDS, groupLabel, statewidePlace, formatPercent, getCountyData } from "@/lib/content/hub/county-data";

/**
 * Statewide: each group's share of Minnesota's population beside its share of the people receiving home and
 * community-based services. Public Department of Human Services figures (county-data.json). Two series, one axis
 * (percent), a legend, a value at each bar end, a hover title on each bar and a table for screen readers and print.
 * Colors were checked for color-vision separation and contrast (population #2563eb, services #15803d).
 */
const POP = "#2563eb", SVC = "#15803d";

export function StatewideServicesChart() {
  const data = getCountyData();
  const state = statewidePlace();
  const rows = GROUP_IDS.filter(id => id !== "all").map(id => {
    const g = state.groups[id];
    return { id, label: groupLabel(id), population: g?.population?.share2022 ?? null, services: g?.services?.status === "reported" ? g.services.share ?? null : null };
  });
  const max = Math.max(...rows.flatMap(r => [r.population ?? 0, r.services ?? 0]));
  const scaleMax = Math.ceil(max * 10) / 10; // round up to the next 10%
  const labelW = 230, plotW = 470, barH = 14, gap = 3, rowH = barH * 2 + gap + 20, top = 8;
  const width = labelW + plotW + 60, height = top + rows.length * rowH + 28;
  const x = (v: number) => labelW + (v / scaleMax) * plotW;
  const ticks = Array.from({ length: Math.round(scaleMax * 10) + 1 }, (_, i) => i / 10).filter((_, i, a) => a.length <= 6 || i % 2 === 0);
  const pop = data.measures.population, svc = data.measures.services;
  return <figure className="statewide-chart" aria-labelledby="statewide-chart-title">
    <h2 id="statewide-chart-title">Who lives in Minnesota, and who receives home and community-based services</h2>
    <p className="statewide-chart-note">Statewide. Population share, {pop.date}; services share, {svc.date}, all ages. A difference is a question to look into, not an explanation.</p>
    <ul className="statewide-chart-legend" aria-hidden="true">
      <li><span style={{ background: POP }} />Share of Minnesota population</li>
      <li><span style={{ background: SVC }} />Share of people receiving services</li>
    </ul>
    <svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="Paired bars by race and ethnicity; the same figures are in the table below." className="statewide-chart-svg">
      {ticks.map(t => <g key={t}>
        <line x1={x(t)} x2={x(t)} y1={top - 4} y2={height - 22} stroke="#e2e8f0" strokeWidth={1} />
        <text x={x(t)} y={height - 6} textAnchor="middle" fontSize={12} fill="#475569">{Math.round(t * 100)}%</text>
      </g>)}
      {rows.map((r, i) => {
        const y = top + i * rowH;
        const bar = (v: number | null, dy: number, color: string, name: string) => v === null ? null : <g>
          <rect x={labelW} y={y + dy} width={Math.max(2, x(v) - labelW)} height={barH} rx={4} fill={color}><title>{`${r.label}: ${name} ${formatPercent(v)}`}</title></rect>
          <text x={x(v) + 6} y={y + dy + barH - 2} fontSize={12.5} fill="#183247" fontWeight={600}>{formatPercent(v)}</text>
        </g>;
        return <g key={r.id}>
          <text x={labelW - 12} y={y + barH + 3} textAnchor="end" fontSize={13.5} fill="#183247">{r.label}</text>
          {bar(r.population, 0, POP, "share of population")}
          {bar(r.services, barH + gap, SVC, "share of people receiving services")}
        </g>;
      })}
    </svg>
    <details className="statewide-chart-table">
      <summary>Show the figures as a table</summary>
      <table>
        <thead><tr><th scope="col">Race or ethnicity</th><th scope="col">Share of population</th><th scope="col">Share of people receiving services</th></tr></thead>
        <tbody>{rows.map(r => <tr key={r.id}><th scope="row">{r.label}</th><td>{formatPercent(r.population)}</td><td>{formatPercent(r.services)}</td></tr>)}</tbody>
      </table>
      <p>People whose race is not recorded count in the services total but in no group, so the service shares add to less than 100%.</p>
    </details>
    <style>{`
      .statewide-chart { margin: 1.5rem 0 2rem; padding: 1.25rem 1.5rem; background: #fff; border: 1px solid #cbd5e1; border-top: 4px solid var(--page-accent, ${SVC}); border-radius: 10px; }
      .statewide-chart h2 { margin: 0 0 .35rem; font-size: 1.25rem; color: #183247; }
      .statewide-chart-note { margin: 0 0 .75rem; color: #475569; font-size: .95rem; max-width: 70ch; }
      .statewide-chart-legend { list-style: none; display: flex; flex-wrap: wrap; gap: .4rem 1.5rem; margin: 0 0 .5rem; padding: 0; font-size: .92rem; color: #183247; }
      .statewide-chart-legend span { display: inline-block; width: 14px; height: 14px; border-radius: 3px; margin-right: .45rem; vertical-align: -2px; }
      .statewide-chart-svg { width: 100%; height: auto; max-width: 820px; display: block; }
      .statewide-chart-table summary { cursor: pointer; min-height: 44px; display: flex; align-items: center; font-weight: 600; color: #183247; }
      .statewide-chart-table table { border-collapse: collapse; margin: .5rem 0; font-size: .95rem; }
      .statewide-chart-table :is(th, td) { padding: .4rem .9rem .4rem 0; border-bottom: 1px solid #e2e8f0; text-align: left; }
      .statewide-chart-table td { font-variant-numeric: tabular-nums; }
      @media (forced-colors: active) { .statewide-chart-svg rect { fill: CanvasText; } }
    `}</style>
  </figure>;
}

"use client";

import Link from "@/components/app-link";
import { useRef, useState } from "react";
import { ActionList, Field, Notice } from "@/components/ui";
import { PROGRAM } from "@/lib/constants";
import { getPath } from "@/lib/content/paths";
import {
  ACCESS_LABEL,
  ACCESS_NEEDS,
  MEETING_MODES,
  POPULATIONS,
  POPULATION_LABEL,
  ROLES,
  ROLE_LABEL,
  STAGES,
  STAGE_LABEL_CR,
  SUPPORT_LABEL,
  SUPPORT_TYPES,
  TIMING,
  TIMING_LABEL,
  type HeadsUpPacket,
} from "@/lib/intelligence/consult/schema";
import type { IntakeResult } from "@/lib/intelligence/agents/intake";
import { PacketView } from "@/components/packet-view";
import { newId, useStored, writeStored } from "@/lib/client/storage";
import { BROWSER_STORAGE_KEYS } from "@/lib/client/storage-keys";
import { participationContract } from "@/lib/participation/contracts";

type FormState = {
  requester_role: string;
  work_name: string;
  stage: string;
  goals: string;
  equity_questions_considered: string;
  desired_support_type: string[];
  support_other_note: string;
  timing_urgency: string;
  deadline_date: string;
  affected_populations: string[];
  populations_note: string;
  access_language_needs: string[];
  access_note: string;
  preferred_meeting_mode: string;
  links: string;
  attachment_notes: string;
  situation: string;
  dsd_eligibility_attestation: boolean;
  share_confirmation: boolean;
};

const EMPTY: FormState = {
  requester_role: "",
  work_name: "",
  stage: "conceptual",
  goals: "",
  equity_questions_considered: "",
  desired_support_type: ["scoping_goals"],
  support_other_note: "",
  timing_urgency: "exploratory",
  deadline_date: "",
  affected_populations: [],
  populations_note: "",
  access_language_needs: [],
  access_note: "",
  preferred_meeting_mode: "",
  links: "",
  attachment_notes: "",
  situation: "",
  dsd_eligibility_attestation: false,
  share_confirmation: false,
};

const NONE_SAVED: Array<{ id: string; key: string; work_name: string; at: string }> = [];
const MEETING_LABEL: Record<string, string> = { in_person: "In person", virtual: "Virtual", either: "Either", not_sure: "Not sure yet" };
const PREVIEW_ONLY_MESSAGE = "Consultation requests are not open yet. You can review the summary that would be shared, but no request is created and nothing you type is kept.";
const SUBMISSION_CONTRACT = participationContract("consultation_submission");

type IntakeRefusalField =
  | "work_name"
  | "goals"
  | "equity_questions_considered"
  | "situation"
  | "attachment_notes"
  | "populations_note"
  | "access_note"
  | "support_other_note"
  | "affected_populations"
  | "ask_context";

const INTAKE_FIELD_LABEL: Record<IntakeRefusalField, string> = {
  work_name: "program or work name",
  goals: "goals",
  equity_questions_considered: "equity questions already considered",
  situation: "what you would like help with",
  attachment_notes: "documents you plan to bring",
  populations_note: "communities or populations note",
  access_note: "access and language needs note",
  support_other_note: "other support",
  affected_populations: "communities or populations",
  ask_context: "information carried over from Ask",
};

function intakeFieldLabel(field: string): string {
  return Object.prototype.hasOwnProperty.call(INTAKE_FIELD_LABEL, field)
    ? INTAKE_FIELD_LABEL[field as IntakeRefusalField]
    : "information you entered";
}

type Prefill = Record<string, unknown>;
const NO_PREFILL: Prefill | null = null;

function buildInitial(pf: Prefill | null, path: ReturnType<typeof getPath>, gap?: string): { form: FormState; ask: { session_id: string; intents_tried: string[]; excerpt: string } | null } {
  const next: FormState = { ...EMPTY };
  let ask: { session_id: string; intents_tried: string[]; excerpt: string } | null = null;
  if (path) {
    next.desired_support_type = [path.consultSupportType];
    if (path.id === "gp-1") next.stage = "conceptual";
  }
  if (gap === "community") {
    next.desired_support_type = ["stakeholder_partner_map"];
    next.affected_populations = ["specific_minnesota_community"];
  }
  if (pf) {
    if (typeof pf.work_name === "string") next.work_name = pf.work_name;
    if (typeof pf.stage === "string") next.stage = pf.stage;
    if (typeof pf.goals === "string" && pf.goals) next.goals = pf.goals;
    if (typeof pf.equity_questions_considered === "string") next.equity_questions_considered = pf.equity_questions_considered;
    if (Array.isArray(pf.desired_support_type)) next.desired_support_type = pf.desired_support_type as string[];
    const ac = pf.ask_context as { session_id: string; intents_tried: string[]; excerpt: string } | undefined;
    if (ac) ask = ac;
  }
  return { form: next, ask };
}

export function IntakeClient({
  pathId,
  askSession,
  gap,
  intakeEnabled,
  programContext,
}: {
  pathId?: string;
  askSession?: string;
  gap?: string;
  intakeEnabled: boolean;
  programContext: "one_dsd";
}) {
  const path = pathId ? getPath(pathId) : undefined;
  const [storedPrefill] = useStored<Prefill | null>("session", BROWSER_STORAGE_KEYS.consultationPrefill, NO_PREFILL);
  // Prefill applies only when arriving from Ask, a path, or a community gap; a stale prefill never leaks into a fresh request.
  const prefill = pathId || askSession || gap ? storedPrefill : null;
  const initial = buildInitial(prefill, path, gap);
  const [edited, setEdited] = useState<FormState | null>(null);
  const form = edited ?? initial.form;
  const askContext = initial.ask;
  const [issues, setIssues] = useState<Record<string, string>>({});
  const [refusal, setRefusal] = useState<{ message: string; field: string; alternatives?: Array<{ label: string; href: string }>; redirect?: { label: string; href: string } } | null>(null);
  const [preview, setPreview] = useState<HeadsUpPacket | null>(null);
  const [created, setCreated] = useState<{ request_id: string; access_key: string; duplicate: boolean; savedOnDevice: boolean } | null>(null);
  const [busy, setBusy] = useState(false);
  const [netError, setNetError] = useState("");
  const [rememberOnDevice, setRememberOnDevice] = useState(false);
  const idemKey = useRef<string>("");
  const [recentRequests, setRecentRequests] = useStored<Array<{ id: string; key: string; work_name: string; at: string }>>("session", BROWSER_STORAGE_KEYS.recentConsultationReferences, NONE_SAVED);
  const [savedRequests, setSavedRequests] = useStored<Array<{ id: string; key: string; work_name: string; at: string }>>("local", BROWSER_STORAGE_KEYS.savedConsultationReferences, NONE_SAVED);

  function set<K extends keyof FormState>(k: K, v: FormState[K]) {
    setEdited({ ...form, [k]: v });
  }
  function toggle(k: "desired_support_type" | "affected_populations" | "access_language_needs", v: string) {
    setEdited({ ...form, [k]: form[k].includes(v) ? form[k].filter((x) => x !== v) : [...form[k], v] });
  }

  function payload() {
    return {
      requester_role: form.requester_role || undefined,
      program_context: programContext,
      dsd_eligibility_attestation: form.dsd_eligibility_attestation,
      work_name: form.work_name,
      stage: form.stage,
      goals: form.goals,
      equity_questions_considered: form.equity_questions_considered,
      desired_support_type: form.desired_support_type,
      support_other_note: form.support_other_note,
      timing_urgency: form.timing_urgency,
      deadline_date: form.deadline_date,
      affected_populations: form.affected_populations,
      populations_note: form.populations_note,
      access_language_needs: form.access_language_needs,
      access_note: form.access_note,
      preferred_meeting_mode: form.preferred_meeting_mode || undefined,
      links: form.links.split(/\s+/).map((s) => s.trim()).filter(Boolean),
      attachment_notes: form.attachment_notes,
      situation: form.situation,
      ask_context: askContext ?? undefined,
      path_id: path?.id,
      participation_notice_id: SUBMISSION_CONTRACT.id,
      participation_notice_version: `${SUBMISSION_CONTRACT.version}.0.0`,
      share_confirmation: form.share_confirmation,
    };
  }

  async function call(mode: "preview" | "submit") {
    if (mode === "submit" && !intakeEnabled) {
      setNetError(PREVIEW_ONLY_MESSAGE);
      return;
    }
    setBusy(true);
    setNetError("");
    setIssues({});
    setRefusal(null);
    try {
      if (!idemKey.current) idemKey.current = newId("ik");
      const res = await fetch("/api/intake", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ mode, input: payload(), idempotency_key: idemKey.current }) });
      const data = (await res.json()) as
        | Exclude<IntakeResult, { kind: "created" }>
        | { kind: "preview"; packet: HeadsUpPacket }
        | { kind: "created"; duplicate: boolean; request: { request_id: string; access_key: string; work_name: string; created_at: string } }
        | { error: string };
      if ("error" in data) {
        setNetError(data.error);
        return;
      }
      if (data.kind === "invalid") {
        const map: Record<string, string> = {};
        for (const i of data.issues) map[i.path || "form"] = i.message;
        setIssues(map);
      } else if (data.kind === "refusal") {
        setRefusal({ message: data.safety.message ?? "", field: data.field, alternatives: data.safety.alternatives, redirect: data.safety.redirect });
      } else if (data.kind === "conflict") {
        setNetError(data.message);
      } else if (data.kind === "preview") {
        setPreview(data.packet);
      } else if (data.kind === "created") {
        const reference = { id: data.request.request_id, key: data.request.access_key, work_name: data.request.work_name, at: data.request.created_at };
        setRecentRequests([reference, ...recentRequests.filter((item) => item.id !== reference.id)].slice(0, 20));
        const savedOnDevice = rememberOnDevice && setSavedRequests([reference, ...savedRequests.filter((item) => item.id !== reference.id)].slice(0, 20));
        setCreated({ request_id: data.request.request_id, access_key: data.request.access_key, duplicate: data.duplicate, savedOnDevice });
        writeStored("session", BROWSER_STORAGE_KEYS.consultationPrefill, null);
      }
    } catch {
      setNetError("We couldn't complete that request just now. Your responses are still in the form, so you can try again in a moment.");
    } finally {
      setBusy(false);
    }
  }

  if (created && intakeEnabled) {
    return (
      <div className="card" aria-live="polite">
        <p className="kicker">Eligibility review</p>
        <h2 className="text-2xl font-extrabold">Your request is ready for DSD eligibility review</h2>
        <p>
          Reference ID: <strong>{created.request_id}</strong>
          <br />
          Access key: <strong>{created.access_key}</strong>
        </p>
        <p className="text-sm">Please keep both. You will need the reference ID and access key to check or withdraw the request. They remain available until you close this tab{created.savedOnDevice ? ", and you chose to save them on this device until you delete them" : ""}. Anyone using this computer may see a copy you chose to save. Deleting that copy does not withdraw or delete the request. {created.duplicate ? "This request was already received; a second copy was not created." : ""}</p>
        <p>An authorized staff member will first confirm that the request concerns DSD work. The {PROGRAM.practiceOwnerRole} takes it up only after that is confirmed. Meetings are scheduled separately, so no calendar invitation has been sent.</p>
        <ActionList
          heading="What you can do now"
          actions={[
            { label: "Track this request", href: `/support/track?id=${created.request_id}` },
            { label: "Continue with the self-guided steps", href: path ? `/practice/${path.id}` : "/practice" },
            { label: "Search Resources", href: "/library" },
          ]}
        />
      </div>
    );
  }

  return (
    <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_22rem]">
      <form
        className="card"
        onSubmit={(e) => {
          e.preventDefault();
          call("submit");
        }}
        noValidate
      >
        {!intakeEnabled ? (
          <Notice tone="warn">
            <strong>No consultation request will be created. </strong>
            Complete the form only if you would like to review the summary a consultation request would create.
          </Notice>
        ) : null}
        {path ? (
          <div className="notice mb-4">
            <strong>Your practice path may have what you need. </strong>
            This request is connected to the &quot;{path.staffLabel}&quot; path. For a routine question, its tools may help you move forward without waiting for a meeting. {intakeEnabled ? "A consultation remains available." : "You can review the summary, but requests are not open yet."}
          </div>
        ) : (
          <div className="notice mb-4">
            <strong>You may be able to keep moving without a meeting. </strong>
          <Link href="/ask">Ask</Link>, <Link href="/library">Library</Link>, and <Link href="/minnesota-communities">Minnesota Communities</Link> can help with many routine questions. {intakeEnabled ? "A consultation is available when you need more." : "You can fill in the form to see the summary, but it will not send or save your information."}
          </div>
        )}
        {askContext ? (
          <p className="text-sm text-muted">
            {intakeEnabled
              ? `This form includes a short excerpt from your recent Ask question. It will be included with anything you submit, so remove anything you do not want the ${PROGRAM.practiceOwnerRole} to receive:`
              : "This summary includes a short excerpt from your recent Ask question. It will not be sent or saved, but you can still review what it says:"}{" "}
            &quot;{askContext.excerpt}&quot;
          </p>
        ) : null}

        <Field id="requester_role" label="Your role (optional)" help="Your answer will not be used to rank or evaluate you.">
          <select id="requester_role" value={form.requester_role} onChange={(e) => set("requester_role", e.target.value)}>
            <option value="">Prefer not to say</option>
            {ROLES.map((r) => (
              <option key={r} value={r}>
                {ROLE_LABEL[r]}
              </option>
            ))}
          </select>
        </Field>
        <Field id="work_name" label="Program or work name (required)" help="Enter the name of the program, policy, tool, or initiative. Please do not use a client's name." error={issues.work_name}>
          <input id="work_name" type="text" value={form.work_name} onChange={(e) => set("work_name", e.target.value)} aria-invalid={Boolean(issues.work_name)} />
        </Field>
        <Field id="stage" label="Stage (required)" help="Choose where the work stands today." error={issues.stage}>
          <select id="stage" value={form.stage} onChange={(e) => set("stage", e.target.value)}>
            {STAGES.map((s) => (
              <option key={s} value={s}>
                {STAGE_LABEL_CR[s]}
              </option>
            ))}
          </select>
        </Field>
        <Field id="goals" label="Goals (required)" help="What are you trying to achieve? Describe it in general terms and leave out case details." error={issues.goals}>
          <textarea id="goals" value={form.goals} onChange={(e) => set("goals", e.target.value)} aria-invalid={Boolean(issues.goals)} />
        </Field>
        <Field id="eqc" label="Equity questions already considered" help="What have you already asked or checked through Ask, a checklist, or conversations with partners? This helps the consultant build on what you have done." error={issues.equity_questions_considered}>
          <textarea id="eqc" value={form.equity_questions_considered} onChange={(e) => set("equity_questions_considered", e.target.value)} />
        </Field>

        <fieldset className="field" aria-describedby={issues.desired_support_type ? "desired-support-error" : undefined} aria-invalid={Boolean(issues.desired_support_type)}>
          <legend className="font-bold" style={{ color: "var(--blue-dark)" }}>
            What kind of support would be most useful? (choose at least one)
          </legend>
          <div className="checks">
            {SUPPORT_TYPES.map((s) => (
              <label key={s}>
                <input type="checkbox" checked={form.desired_support_type.includes(s)} onChange={() => toggle("desired_support_type", s)} />
                <span>{SUPPORT_LABEL[s]}</span>
              </label>
            ))}
          </div>
          {issues.desired_support_type ? <p className="error" id="desired-support-error" role="alert">{issues.desired_support_type}</p> : null}
        </fieldset>
        {form.desired_support_type.includes("other") ? (
          <Field id="support_other_note" label="Other support (describe)" error={issues.support_other_note}>
            <input id="support_other_note" type="text" value={form.support_other_note} onChange={(e) => set("support_other_note", e.target.value)} />
          </Field>
        ) : null}

        <Field id="timing" label="When do you need support? (required)" help="Choose the option that best reflects your timing." error={issues.timing_urgency}>
          <select id="timing" value={form.timing_urgency} onChange={(e) => set("timing_urgency", e.target.value)}>
            {TIMING.map((t) => (
              <option key={t} value={t}>
                {TIMING_LABEL[t]}
              </option>
            ))}
          </select>
        </Field>
        {form.timing_urgency === "hard_deadline" ? (
          <Field id="deadline_date" label="Deadline date" help="Include a date only when the work has a firm external deadline. It will not be used to rank requests." error={issues.deadline_date}>
            <input id="deadline_date" type="date" value={form.deadline_date} onChange={(e) => set("deadline_date", e.target.value)} />
          </Field>
        ) : null}

        <fieldset className="field">
          <legend className="font-bold" style={{ color: "var(--blue-dark)" }}>
            Communities or populations (general terms only)
          </legend>
          <p className="help m-0">Please leave out client names. Work involving a Tribal Nation must be referred first to the Office of Indian Policy.</p>
          <div className="checks">
            {POPULATIONS.map((p) => (
              <label key={p}>
                <input type="checkbox" checked={form.affected_populations.includes(p)} onChange={() => toggle("affected_populations", p)} />
                <span>{POPULATION_LABEL[p]}</span>
              </label>
            ))}
          </div>
          <label htmlFor="populations_note" className="mt-2 text-sm font-bold">
            Note (optional, up to 300 characters)
          </label>
          <input id="populations_note" type="text" value={form.populations_note} onChange={(e) => set("populations_note", e.target.value)} maxLength={300} />
        </fieldset>

        <fieldset className="field">
          <legend className="font-bold" style={{ color: "var(--blue-dark)" }}>
            Access and language needs for the consultation
          </legend>
          <div className="checks">
            {ACCESS_NEEDS.map((a) => (
              <label key={a}>
                <input type="checkbox" checked={form.access_language_needs.includes(a)} onChange={() => toggle("access_language_needs", a)} />
                <span>{ACCESS_LABEL[a]}</span>
              </label>
            ))}
          </div>
          <label htmlFor="access_note" className="mt-2 text-sm font-bold">
            Note (optional)
          </label>
          <input id="access_note" type="text" value={form.access_note} onChange={(e) => set("access_note", e.target.value)} maxLength={300} />
        </fieldset>

        <Field id="mode" label="How you would like to meet">
          <select id="mode" value={form.preferred_meeting_mode} onChange={(e) => set("preferred_meeting_mode", e.target.value)}>
            <option value="">Not stated</option>
            {MEETING_MODES.map((m) => (
              <option key={m} value={m}>
                {MEETING_LABEL[m]}
              </option>
            ))}
          </select>
        </Field>
        <Field id="links" label="Public reference links (up to 5)" help="You may include links to public web pages, one per line. Please do not include intranet pages, shared-drive links, case records, or anything that requires a staff account to open." error={issues.links || issues["links.0"]}>
          <textarea id="links" value={form.links} onChange={(e) => set("links", e.target.value)} rows={2} />
        </Field>
        <Field id="attachment_notes" label="Documents you plan to bring" help="List any documents you plan to bring to the consultation. Attachments cannot be added here. Please leave out case, medical, and personnel information." error={issues.attachment_notes}>
          <textarea id="attachment_notes" value={form.attachment_notes} onChange={(e) => set("attachment_notes", e.target.value)} rows={2} maxLength={500} />
        </Field>
        <Field id="situation" label="What would you like help with? (required)" help="Briefly describe the situation and the support you need. Please leave out case names, Social Security numbers, medical details, complaints about named people, and personnel information." error={issues.situation}>
          <textarea id="situation" value={form.situation} onChange={(e) => set("situation", e.target.value)} rows={6} aria-invalid={Boolean(issues.situation)} />
        </Field>

        <div className="checks mb-4">
          <label>
            <input
              type="checkbox"
              checked={form.dsd_eligibility_attestation}
              onChange={(e) => set("dsd_eligibility_attestation", e.target.checked)}
              aria-describedby={issues.dsd_eligibility_attestation ? "dsd-attestation-error" : undefined}
              aria-invalid={Boolean(issues.dsd_eligibility_attestation)}
            />
            <span>I confirm that this request concerns work within the Disability Services Division. Direct consultation through this program is limited to DSD work. (required)</span>
          </label>
          {issues.dsd_eligibility_attestation ? <p className="error" id="dsd-attestation-error" role="alert">{issues.dsd_eligibility_attestation}</p> : null}
        </div>

        {refusal ? (
          <div className="mb-4">
            <Notice tone="stop">
              <strong>This request has not been saved. Please review the &quot;{intakeFieldLabel(refusal.field)}&quot; response. </strong>
              {refusal.message}
            </Notice>
            {refusal.redirect ? (
              <p className="mt-2">
                <Link href={refusal.redirect.href} className="btn btn--primary">
                  {refusal.redirect.label}
                </Link>
              </p>
            ) : null}
            <ActionList heading="Other ways to get help" actions={refusal.alternatives ?? []} />
          </div>
        ) : null}

        <div className="checks mb-4">
          <label>
            <input
              type="checkbox"
              checked={form.share_confirmation}
              onChange={(e) => set("share_confirmation", e.target.checked)}
              aria-describedby={issues.share_confirmation ? "share-confirmation-error" : undefined}
              aria-invalid={Boolean(issues.share_confirmation)}
            />
            <span>{intakeEnabled ? "I understand that submitting is voluntary. I am choosing to share this request with an authorized DSD staff member. It is a program consultation request, not an official DHS record. (required)" : "I understand that this is only a private review. No request will be created, the form and summary will not be kept, and neither will be sent to the consultant. (required)"}</span>
          </label>
          {issues.share_confirmation ? <p className="error" id="share-confirmation-error" role="alert">{issues.share_confirmation}</p> : null}
        </div>
        {intakeEnabled ? (
          <div className="checks mb-4">
            <label>
              <input
                type="checkbox"
                checked={rememberOnDevice}
                onChange={(event) => setRememberOnDevice(event.target.checked)}
              />
              <span>Remember my reference ID and private access key on this device after I close this tab. This is optional; do not select it on a shared device.</span>
            </label>
          </div>
        ) : null}
        {netError ? <p className="error" role="alert">{netError}</p> : null}
        <div className="flex flex-wrap gap-3">
          <button type="button" className="btn btn--light" disabled={busy} onClick={() => call("preview")}>
            Review the summary
          </button>
          {intakeEnabled ? (
            <button type="submit" className="btn btn--primary" disabled={busy}>
              Submit request
            </button>
          ) : null}
        </div>
      </form>

      <aside className="space-y-4">
        {preview ? (
          <div className="card" aria-live="polite">
            <p className="kicker">{intakeEnabled ? "Before you submit" : "Your summary"}</p>
            <h2 className="text-lg font-extrabold">{intakeEnabled ? `What the ${PROGRAM.practiceOwnerRole} will see` : `What the ${PROGRAM.practiceOwnerRole} would see if submissions open`}</h2>
            <PacketView packet={preview} compact />
          </div>
        ) : (
          <div className="panel">
            <p className="kicker">{intakeEnabled ? "What happens next" : "How this works"}</p>
