      { key: "requestHref", label: "Consultation link destination" },
      { key: "trackLabel", label: "Request follow-up link wording" },
      { key: "trackHref", label: "Request follow-up destination" },
      { key: "escalationLabel", label: "Other help link wording", rows: 3 },
      { key: "escalationHref", label: "Other help link destination" },
    ],
  },
  {
    heading: "Privacy and access",
    fields: [
      { key: "privacyHeading", label: "Section heading" },
      { key: "privacyText", label: "Privacy and access wording", rows: 7 },
    ],
  },
] as const;

type ResponseBody = {
  state?: PageBlockEditingState;
  message?: string;
  error?: string;
};

const SURFACE_LABEL: Record<PageBlockSurface, string> = {
  home: "Home page",
  footer: "page footer",
};

export function PageCopyEditor<TCopy extends PageBlockCopy>({
  surface,
  initial,
}: {
  surface: PageBlockSurface;
  initial: PageBlockEditingState<TCopy>;
}) {
  const router = useRouter();
  const [state, setState] = useState<PageBlockEditingState<TCopy>>(initial);
  const [copy, setCopy] = useState<TCopy>(initial.copy);
  const [changeNote, setChangeNote] = useState("");
  const [decisionReason, setDecisionReason] = useState("");
  const [rollbackRevisionId, setRollbackRevisionId] = useState("");
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const groups = surface === "home" ? HOME_COPY_FIELD_GROUPS : FOOTER_COPY_FIELD_GROUPS;
  const rollbackChoices = useMemo(
    () => state.history.filter((entry) => !entry.isCurrent),
    [state.history],
  );

  // Unsaved edits live only in this component: warn before the page is left.
  const dirty = JSON.stringify(copy) !== JSON.stringify(state.copy) || changeNote !== "";
  useEffect(() => {
    if (!dirty) return;
    const guard = (event: BeforeUnloadEvent) => {
      event.preventDefault();
      event.returnValue = "";
    };
    window.addEventListener("beforeunload", guard);
    return () => window.removeEventListener("beforeunload", guard);
  }, [dirty]);

  function updateField(key: FieldKey, value: string) {
    setCopy((current) => ({ ...current, [key]: value }));
  }

  async function send(action: PageCopyAction, refreshStaffView = false) {
    setBusy(true);
    setMessage("");
    setError("");
    try {
      const response = await fetch(`/api/consultant/page-copy/${surface}`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(action),
      });
      const result = (await response.json().catch(() => ({}))) as ResponseBody;
      if (!response.ok || !result.state) {
        setError(result.error ?? "The change could not be confirmed. Reload the page to check the saved wording.");
        return;
      }
      const next = result.state as PageBlockEditingState<TCopy>;
      setState(next);
      setCopy(next.copy);
      setMessage(result.message ?? "The change was saved.");
      if (refreshStaffView) router.refresh();
    } catch {
      setError("The change could not be confirmed. Reload the page to check the saved wording.");
    } finally {
      setBusy(false);
    }
  }

  function saveChanges(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    void send({
      action: "save_changes",
      expectedRevisionId: state.expectedRevisionId,
      expectedPublicationDecisionId: state.publicationDecisionId,
      copy,
      changeNote: changeNote.trim() || null,
    }, true);
  }

  return (
    <section className="card mt-6 text-left" aria-labelledby={`${surface}-wording-editor-heading`}>
          <p className="kicker">Consultant Workspace</p>
      <h2 className="text-xl font-extrabold" id={`${surface}-wording-editor-heading`}>
        Edit the {SURFACE_LABEL[surface]}
      </h2>
      <p className="mt-2 mb-0">
        Save to update what staff see. Earlier wording stays available below.
      </p>

      {!state.isPublished ? (
        <div className="mt-4">
          <Notice tone="warn">Staff are not seeing this section right now. You can bring back earlier wording below.</Notice>
        </div>
      ) : state.hasUnpublishedChanges ? (
        <div className="mt-4">
          <Notice tone="warn">You have a draft in progress. Save to show this wording to staff.</Notice>
        </div>
      ) : null}

      <form className="mt-6" onSubmit={saveChanges}>
        {groups.map((group) => (
          <fieldset className="panel mb-5" key={group.heading}>
            <legend className="font-bold text-navy-deep">{group.heading}</legend>
            <div className="mt-3 grid gap-x-6 md:grid-cols-2">
              {group.fields.map((field) => {
                const value = (copy as unknown as Record<string, string>)[field.key] ?? "";
                const id = `${surface}-${field.key}`;
                return (
                  <Field id={id} label={field.label} help={field.help} key={field.key}>
                    {field.rows ? (
                      <textarea
                        id={id}
                        value={value}
                        rows={field.rows}
                        maxLength={4_000}
                        required={field.key !== "heroNote"}
                        disabled={busy}
                        onChange={(event) => updateField(field.key, event.target.value)}
                      />
                    ) : (
                      <input
                        id={id}
                        type="text"
                        value={value}
                        maxLength={2_000}
                        required={field.key !== "heroNote"}
                        disabled={busy}
                        onChange={(event) => updateField(field.key, event.target.value)}
                      />
                    )}
                  </Field>
                );
              })}
            </div>
          </fieldset>
        ))}
        <Field
          id={`${surface}-change-note`}
          label="Note about these changes"
          help="Optional. A few words that help you recognize this version later."
        >
          <textarea
            id={`${surface}-change-note`}
            value={changeNote}
            rows={3}
            maxLength={1_000}
            onChange={(event) => setChangeNote(event.target.value)}
          />
        </Field>
        <div className="flex flex-wrap gap-3">
          <button className="btn btn--primary" type="submit" disabled={busy}>
            {busy ? "Saving" : "Save changes"}
          </button>
          <button
            className="btn btn--light"
            type="button"
            disabled={busy}
            onClick={() => {
              setCopy(state.copy);
              setChangeNote("");
              setError("");
              setMessage("");
            }}
          >
            Reset unsaved changes
          </button>
        </div>
      </form>

      <section className="panel mt-6" aria-labelledby={`${surface}-release-heading`}>
        <h3 className="text-lg font-bold" id={`${surface}-release-heading`}>What staff see</h3>
        <p className="mt-1 text-sm text-muted">Take the current wording down, or bring back an earlier version. Add a short note for the record first; staff never see it.</p>
        <Field id={`${surface}-decision-reason`} label="Why you are making this change">
          <textarea
            id={`${surface}-decision-reason`}
            value={decisionReason}
            rows={3}
            maxLength={500}
            required
            onChange={(event) => setDecisionReason(event.target.value)}
          />
        </Field>
        <div className="flex flex-wrap gap-3">
          {state.publishedRevisionId ? (
            <button
              className="btn btn--light"
              type="button"
              disabled={busy || !decisionReason.trim()}
              onClick={() => void send({
                action: "withdraw",
                expectedPublishedRevisionId: state.publishedRevisionId!,
                expectedPublicationDecisionId: state.publicationDecisionId!,
                reason: decisionReason.trim(),
              }, true)}
            >
              Take this wording down
            </button>
          ) : null}
        </div>


        {rollbackChoices.length ? (
          <div className="mt-6 border-t border-line pt-5">
            <Field id={`${surface}-earlier-version`} label="Earlier wording">
              <select
                id={`${surface}-earlier-version`}
                value={rollbackRevisionId}
                onChange={(event) => setRollbackRevisionId(event.target.value)}
              >
                <option value="">Choose an earlier version</option>
                {rollbackChoices.map((entry) => (
                  <option key={entry.revisionId} value={entry.revisionId}>
                    {entry.label} — {entry.publishedAt.slice(0, 10)}
                  </option>
                ))}
              </select>
            </Field>
            <button
              className="btn btn--light"
              type="button"
              disabled={busy || !rollbackRevisionId || !decisionReason.trim()}
              onClick={() => void send({
                action: "rollback",
                expectedPublishedRevisionId: state.publishedRevisionId,
                targetRevisionId: rollbackRevisionId,
                expectedPublicationDecisionId: state.publicationDecisionId,
                reason: decisionReason.trim(),
              }, true)}
            >
              Bring back this wording
            </button>
          </div>
        ) : null}
      </section>

      {error ? <p className="error mt-4" role="alert">{error}</p> : null}
      {message ? <p className="notice mt-4" role="status">{message}</p> : null}
    </section>
  );
}

export type HomePageCopyEditorState = PageBlockEditingState<HomePageCopy>;
export type FooterCopyEditorState = PageBlockEditingState<FooterCopy>;

"use client";

import { useCallback, useEffect, useRef, useState, type CSSProperties } from "react";
import type { LinkRun, PageEditEngine, TextRun } from "@/lib/content/page-edit-dom";
import { writeRun } from "@/lib/content/page-edit-dom";
import { cleanReplacementText, comparableText, linkAddressIsAllowed, pagePathIsOwnerOnly, PAGE_EDIT_LIMITS } from "@/lib/content/page-edit-keys";

/** The owner's controls for editing any page in place. Loaded only for a signed-in owner. */
export type PageEditEntry = {
  key: string;
  scope: "page" | "site";
  kind: "text" | "link";
  original: string;
  value: string;
  updatedAt: string;
  publicOriginPath?: string;
};

export type PageEditsResponse = {
  ok: true;
  canEdit: boolean;
  page: Record<string, string>;
  site: Record<string, string>;
  entries?: PageEditEntry[];
  degraded?: boolean;
};

export type PageEditControlsProps = {
  path: string;
  engine: PageEditEngine;
  data: PageEditsResponse;
  onChange: (next: PageEditsResponse) => void;
};

type Selection = {
  run: TextRun | null;
  link: LinkRun | null;
  returnFocus: HTMLElement | null;
};

const TARGET = "data-pac-page-edit-target";
const ACTIVE = "data-pac-page-edit-active";
const FOCUSABLE = "a[href],button,summary,input,select,textarea,[tabindex]";

const NAVY = "#003865";
const shell: CSSProperties = { position: "fixed", left: 16, bottom: 16, zIndex: 1001, width: "min(420px, calc(100vw - 32px))", maxHeight: "calc(100vh - 32px)", overflowY: "auto", display: "flex", flexDirection: "column", gap: 8, fontSize: 15, lineHeight: 1.45, color: "#111" };
const card: CSSProperties = { background: "#fff", color: "#111", border: `2px solid ${NAVY}`, borderRadius: 10, padding: "12px 14px", boxShadow: "0 4px 16px rgba(0,0,0,0.25)", maxHeight: "60vh", overflowY: "auto" };
const primary: CSSProperties = { background: NAVY, color: "#fff", border: `2px solid ${NAVY}`, borderRadius: 8, padding: "8px 14px", minHeight: 44, fontWeight: 600, cursor: "pointer", fontSize: 15 };
const secondary: CSSProperties = { ...primary, background: "#fff", color: NAVY };
const field: CSSProperties = { display: "block", width: "100%", boxSizing: "border-box", padding: "8px 10px", border: "1px solid #555", borderRadius: 6, fontSize: 15, fontFamily: "inherit", color: "#111", background: "#fff" };
const row: CSSProperties = { display: "flex", gap: 8, flexWrap: "wrap" };

const PAGE_STYLE = `
  [${TARGET}] { outline: 1px dashed #1f6f8b; outline-offset: 1px; cursor: text; }
  [${TARGET}]:hover { outline: 2px dashed #123f60; }
  [${TARGET}]:focus-visible { outline: 3px solid #123f60; outline-offset: 2px; }
  [${ACTIVE}] { outline: 3px solid #b42318 !important; outline-offset: 2px; }
  [data-pac-editor] { display: none !important; }
  [data-pac-page-edit-ui] button:focus-visible, [data-pac-page-edit-ui] textarea:focus-visible, [data-pac-page-edit-ui] input:focus-visible { outline: 3px solid #b42318; outline-offset: 2px; }
`;

function shorten(text: string, limit = 90): string {
  const flat = comparableText(text);
  return flat.length > limit ? `${flat.slice(0, limit - 1)}…` : flat;
}

function isVisible(element: Element): boolean {
  return element.getClientRects().length > 0;
}

async function send(body: Record<string, unknown>): Promise<PageEditsResponse> {
  let response: Response;
  try {
    response = await fetch("/api/page-edits", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(body),
    });
  } catch {
    throw new Error("The change could not be saved. Check your connection and try again.");
  }
  const parsed: unknown = await response.json().catch(() => null);
  if (!response.ok) {
    const message = parsed && typeof parsed === "object" ? (parsed as { error?: unknown }).error : null;
    throw new Error(typeof message === "string" && message ? message : `The change could not be saved (error ${response.status}).`);
  }
  return parsed as PageEditsResponse;
}

/** The wording under the pointer, using the caret position where the browser offers it. */
function runFromPoint(runs: TextRun[], target: Element, x: number, y: number): TextRun | null {
  const pointDocument = target.ownerDocument as Document & {
    caretPositionFromPoint?: (px: number, py: number) => { offsetNode: Node } | null;
    caretRangeFromPoint?: (px: number, py: number) => Range | null;
  };
  const node = pointDocument.caretPositionFromPoint?.(x, y)?.offsetNode
    ?? pointDocument.caretRangeFromPoint?.(x, y)?.startContainer
    ?? null;
  if (node) {
    const exact = runs.find((run) => run.nodes.includes(node as Text));
    if (exact && target.contains(exact.parent)) return exact;
  }
  return runs.find((run) => run.parent === target) ?? runs.find((run) => target.contains(run.parent)) ?? null;
}

export function PageEditControls({ path, engine, data, onChange }: PageEditControlsProps) {
  const [editing, setEditing] = useState(false);
  const [selection, setSelection] = useState<Selection | null>(null);
  const [textValue, setTextValue] = useState("");
  const [linkValue, setLinkValue] = useState("");
  const [everyPage, setEveryPage] = useState(false);
  const [problem, setProblem] = useState("");
  const [status, setStatus] = useState("");
  const [busy, setBusy] = useState(false);
  const [listOpen, setListOpen] = useState(false);
  const [present, setPresent] = useState<Set<string>>(() => engine.present());
  const textBox = useRef<HTMLTextAreaElement | null>(null);
  const linkBox = useRef<HTMLInputElement | null>(null);
  const toggle = useRef<HTMLButtonElement | null>(null);
  const tagged = useRef<Array<{ element: HTMLElement; addedTabIndex: boolean }>>([]);

  const entries = data.entries ?? [];
  const degraded = data.degraded === true;
  const ownerOnlyPage = pagePathIsOwnerOnly(path);

  const clearTargets = useCallback(() => {
    for (const { element, addedTabIndex } of tagged.current) {
      element.removeAttribute(TARGET);
      if (addedTabIndex) element.removeAttribute("tabindex");
    }
    tagged.current = [];
  }, []);

  /** Mark everything editable and reachable by keyboard. Only attributes change; React ignores them. */
  const markTargets = useCallback(() => {
    clearTargets();
    const elements = new Set<HTMLElement>();
    for (const run of engine.textRuns()) elements.add(run.parent);
    for (const link of engine.links()) elements.add(link.element);
    for (const element of elements) {
      if (element.tagName === "BODY" || element.tagName === "MAIN") continue;
      element.setAttribute(TARGET, "true");
      const addedTabIndex = !element.matches(FOCUSABLE);
      if (addedTabIndex) element.setAttribute("tabindex", "0");
      tagged.current.push({ element, addedTabIndex });
    }
  }, [engine, clearTargets]);

  useEffect(() => engine.subscribe(() => {
    setPresent(engine.present());
    if (editing && !selection) markTargets();
  }), [engine, editing, selection, markTargets]);

  const stopEditing = useCallback(() => {
    document.querySelectorAll(`[${ACTIVE}]`).forEach((element) => element.removeAttribute(ACTIVE));
    // In this order: resuming while still in edit mode puts back any unsaved preview.
    engine.resume();
    engine.setEditing(false);
    // Last, because each engine step above tells the listener to mark targets again.
    clearTargets();
    setEditing(false);
    setSelection(null);
    setProblem("");
  }, [engine, clearTargets]);

  // Leaving the page (this component is keyed by path) always removes every mark it added.
  useEffect(() => () => {
    document.querySelectorAll(`[${ACTIVE}]`).forEach((element) => element.removeAttribute(ACTIVE));
    engine.resume();
    engine.setEditing(false);
    clearTargets();
  }, [engine, clearTargets]);

  const open = useCallback((run: TextRun | null, link: LinkRun | null, returnFocus: HTMLElement | null) => {
    if (!run && !link) return;
    engine.pause();
    const current = run ? engine.edits().page[run.key] ?? (run.inMain ? undefined : engine.edits().site[run.siteKey]) : undefined;
    const currentLink = link ? engine.edits().page[link.key] ?? (link.inMain ? undefined : engine.edits().site[link.siteKey]) : undefined;
    setSelection({ run, link, returnFocus });
    setTextValue(run ? current ?? comparableText(run.original) : "");
    setLinkValue(link ? currentLink ?? link.original : "");
    // Header and footer wording repeats on every page, so that is the starting choice for it.
    const inChrome = run ? !run.inMain : link ? !link.inMain : false;
    const savedOnPageOnly = (run && Object.hasOwn(engine.edits().page, run.key)) || (link && Object.hasOwn(engine.edits().page, link.key));
    setEveryPage(inChrome && !savedOnPageOnly && !ownerOnlyPage);
    setProblem("");
    setStatus("");
    (run?.parent ?? link?.element)?.setAttribute(ACTIVE, "true");
  }, [engine, ownerOnlyPage]);

  // Move focus into the editor when it opens or moves to another piece of wording.
  useEffect(() => {
    if (!selection) return;
    (selection.run ? textBox.current : linkBox.current)?.focus();
    // Bring the wording clear of this panel only if the panel would cover it.
    const chosen = selection.run?.parent ?? selection.link?.element;
    if (chosen && chosen.getBoundingClientRect().bottom > window.innerHeight - 360) chosen.scrollIntoView?.({ block: "center" });
  }, [selection]);

  const closeSelection = useCallback((message?: string) => {
    const closing = selection;
    if (closing) (closing.run?.parent ?? closing.link?.element)?.removeAttribute(ACTIVE);
    setSelection(null);
    setProblem("");
    if (message) setStatus(message);
    // Resuming puts back saved wording in place of any unsaved preview.
    engine.resume();
    const focusTarget = closing?.returnFocus;
    if (focusTarget?.isConnected) focusTarget.focus();
  }, [engine, selection]);

  // While editing, clicks choose wording instead of operating the page.
  useEffect(() => {
    if (!editing) return;
    const inControls = (element: Element | null) => Boolean(element?.closest("[data-pac-page-edit-ui]"));
    const choose = (element: Element, x: number | null, y: number | null) => {
      const runs = engine.textRuns();
      const anchor = element.closest<HTMLAnchorElement>("a[href]");
      const run = x !== null && y !== null
        ? runFromPoint(runs, element, x, y)
        : runs.find((item) => item.parent === element) ?? runs.find((item) => element.contains(item.parent)) ?? null;
      const link = anchor ? engine.links().find((item) => item.element === anchor) ?? null : null;
      if (!run && !link) {
        if (element.closest("img, picture, svg, video, audio")) setStatus("Pictures and media cannot be changed here.");
        else if (element.closest("input, textarea, select")) setStatus("Form fields cannot be changed here.");
        return;
      }
      if (selection) (selection.run?.parent ?? selection.link?.element)?.removeAttribute(ACTIVE);
      // Moving on from unsaved wording puts the saved wording back.
      engine.resume();
      open(run, link, element.closest<HTMLElement>(`[${TARGET}]`) ?? null);
    };
    const onClick = (event: MouseEvent) => {
      const element = event.target instanceof Element ? event.target : null;
      if (!element || inControls(element)) return;
      event.preventDefault();
      event.stopPropagation();
      if (!busy) choose(element, event.clientX, event.clientY);
    };
    const onKey = (event: KeyboardEvent) => {
      const element = event.target instanceof Element ? event.target : null;
      if (inControls(element)) return;
      if (event.key === "Escape") {
        event.preventDefault();
        stopEditing();
        setStatus("Editing is off.");
        toggle.current?.focus();
        return;
      }
      if ((event.key === "Enter" || event.key === " ") && element?.hasAttribute(TARGET)) {
        event.preventDefault();
        event.stopPropagation();
        if (!busy) choose(element, null, null);
      }
    };
    const stop = (event: Event) => {
      if (event.target instanceof Element && inControls(event.target)) return;
      event.preventDefault();
      event.stopPropagation();
    };
    // On window, in the capture phase: this runs before React and next/link see the event.
    window.addEventListener("click", onClick, true);
    window.addEventListener("keydown", onKey, true);
    window.addEventListener("submit", stop, true);
    window.addEventListener("auxclick", stop, true);
    return () => {
      window.removeEventListener("click", onClick, true);
      window.removeEventListener("keydown", onKey, true);
      window.removeEventListener("submit", stop, true);
      window.removeEventListener("auxclick", stop, true);
    };
  }, [editing, engine, open, busy, selection, stopEditing]);

  const startEditing = () => {
    if (document.querySelector("[data-pac-editable]")) {
      setStatus("Finish with the wording and images editor first.");
      return;
    }
    engine.setEditing(true);
    setEditing(true);
    setListOpen(false);
    markTargets();
    setStatus("Editing is on. Click any text, or press Tab to reach it and Enter to choose it. Links and buttons will not operate until you turn editing off. Press Escape to finish.");
  };

  const step = (direction: 1 | -1) => {
    const current = selection?.run;
    engine.resume();
    if (selection) (selection.run?.parent ?? selection.link?.element)?.removeAttribute(ACTIVE);
    const runs = engine.textRuns().filter((run) => isVisible(run.parent));
    if (!runs.length) return;
    const position = current ? runs.findIndex((run) => run.nodes[0] === current.nodes[0]) : -1;
    const next = runs[(position + direction + runs.length) % runs.length];
    const anchor = next.parent.closest<HTMLAnchorElement>("a[href]");
    const link = anchor ? engine.links().find((item) => item.element === anchor) ?? null : null;
    open(next, link, selection?.returnFocus ?? null);
  };

  const preview = (value: string) => {
    setTextValue(value);
    if (selection?.run && value.trim()) writeRun(selection.run, value, engine.memory);
  };

  const save = async () => {
    if (!selection || busy) return;
    const { run, link } = selection;
    const scope = everyPage ? "site" : "page";
    let latest: PageEditsResponse | null = null;
    setBusy(true);
    setProblem("");
    try {
      if (run) {
        const cleaned = cleanReplacementText(textValue);
        if (!cleaned) throw new Error("Text cannot be empty. Use Undo to bring back the original.");
        const showing = engine.edits().page[run.key] ?? (run.inMain ? undefined : engine.edits().site[run.siteKey]) ?? run.original;
        const unpublished = everyPage && entries.some(entry => entry.scope === "site" && entry.key === run.siteKey && !entry.publicOriginPath);
        if (comparableText(cleaned) !== comparableText(showing) || (everyPage && !Object.hasOwn(engine.edits().site, run.siteKey)) || unpublished) {
          latest = await send({ action: "save", path, kind: "text", original: comparableText(run.original), occurrence: run.occurrence, value: cleaned, scope });
        }
      }
      if (link) {
        const address = linkValue.trim();
        if (!linkAddressIsAllowed(address)) throw new Error("Use a local path starting with /, an anchor starting with #, or an address starting with https://.");
        const showing = engine.edits().page[link.key] ?? (link.inMain ? undefined : engine.edits().site[link.siteKey]) ?? link.original;
        const unpublished = everyPage && entries.some(entry => entry.scope === "site" && entry.key === link.siteKey && !entry.publicOriginPath);
        if (address !== showing || unpublished) {
          latest = await send({ action: "save", path, kind: "link", original: link.original.trim(), occurrence: link.occurrence, value: address, scope });
        }
      }
      if (latest) onChange(latest);
      closeSelection(latest ? (everyPage ? "Saved. It now shows on every page for everyone." : ownerOnlyPage ? "Saved. Only the signed-in owner can see this page edit." : "Saved. It now shows on this page for everyone.") : "Nothing changed.");
    } catch (error) {
      if (latest) onChange(latest);
      setProblem(error instanceof Error ? error.message : "The change could not be saved.");
    } finally {
      setBusy(false);
    }
  };

  const undo = async (key: string, scope: "page" | "site", after?: () => void) => {
    if (busy) return;
    setBusy(true);
    setProblem("");
    try {
      onChange(await send({ action: "undo", path, key, scope }));
      setStatus("Undone. The original is back for everyone.");
      after?.();
    } catch (error) {
      setProblem(error instanceof Error ? error.message : "The change could not be undone.");
    } finally {
      setBusy(false);
    }
  };

  /** Every saved edit behind the current selection, page-only edits first. */
  const savedForSelection = (): Array<{ key: string; scope: "page" | "site" }> => {
    if (!selection) return [];
    const edits = engine.edits();
    const found: Array<{ key: string; scope: "page" | "site" }> = [];
    for (const item of [selection.run, selection.link]) {
      if (!item) continue;
      if (Object.hasOwn(edits.page, item.key)) found.push({ key: item.key, scope: "page" });
      else if (!item.inMain && Object.hasOwn(edits.site, item.siteKey)) found.push({ key: item.siteKey, scope: "site" });
    }
    return found;
  };

  const undoSelection = async () => {
    const saved = savedForSelection();
    for (const [index, item] of saved.entries()) {
      await undo(item.key, item.scope, index === saved.length - 1 ? () => closeSelection("Undone. The original is back for everyone.") : undefined);
    }
  };

  const selectionTarget = selection?.run ?? selection?.link ?? null;
  const showScopeChoice = Boolean(selectionTarget && !selectionTarget.inMain && !ownerOnlyPage);

  return (
    <div data-pac-page-edit-ui="true" role="region" aria-label="Page editing" style={shell}>
      {editing ? <style>{PAGE_STYLE}</style> : null}

      {degraded ? (
        <p role="alert" style={{ ...card, margin: 0, borderColor: "#b42318" }}>
          The saved page edits could not be read, so this page shows its original wording and new edits cannot be saved. Nothing has been lost.
        </p>
      ) : null}

      {problem ? <p role="alert" style={{ ...card, margin: 0, borderColor: "#b42318" }}>{problem}</p> : null}

      <p role="status" aria-live="polite" style={status ? { ...card, margin: 0, background: NAVY, color: "#fff" } : { position: "absolute", width: 1, height: 1, overflow: "hidden", clipPath: "inset(50%)", margin: 0 }}>
        {status}
      </p>

      {selection ? (
        <div
          role="dialog"
          aria-modal="false"
          aria-label="Edit the selected text"
          style={card}
          onKeyDown={(event) => {
            if (event.key === "Escape") {
              event.stopPropagation();
              closeSelection("Change discarded.");
            }
          }}
        >
          {selection.run ? (
            <label style={{ display: "block", marginBottom: 8, fontWeight: 600 }}>
              Text
              <textarea
                ref={textBox}
                value={textValue}
                maxLength={PAGE_EDIT_LIMITS.text}
                rows={Math.min(8, Math.max(2, Math.ceil(textValue.length / 45)))}
                spellCheck
                onChange={(event) => preview(event.target.value)}
                style={{ ...field, marginTop: 4, fontWeight: 400 }}
              />
            </label>
          ) : null}
          {selection.link ? (
            <label style={{ display: "block", marginBottom: 8, fontWeight: 600 }}>
              Link address
              <input
                ref={linkBox}
                type="text"
                inputMode="url"
                value={linkValue}
                maxLength={PAGE_EDIT_LIMITS.href}
                spellCheck={false}
                aria-describedby="pac-page-edit-link-help"
                onChange={(event) => setLinkValue(event.target.value)}
                style={{ ...field, marginTop: 4, fontWeight: 400 }}
              />
              <span id="pac-page-edit-link-help" style={{ display: "block", marginTop: 4, fontWeight: 400, fontSize: 14 }}>
                A local path (/library), an anchor (#section), or an address starting with https://.
              </span>
            </label>
          ) : null}
          {showScopeChoice ? (
            <label style={{ display: "flex", gap: 8, alignItems: "flex-start", marginBottom: 8 }}>
              <input type="checkbox" checked={everyPage} onChange={(event) => setEveryPage(event.target.checked)} style={{ width: 20, height: 20, flex: "none", marginTop: 2 }} />
              <span>Change this on every page. It is part of the header or footer, which every page shows.</span>
            </label>
          ) : null}
          {ownerOnlyPage ? <p>Edits on this page are visible only to the signed-in owner. To change the header or footer for everyone, open a public page.</p> : null}
          <div style={row}>
            <button type="button" style={primary} disabled={busy || degraded} onClick={() => void save()}>{busy ? "Saving…" : "Save"}</button>
            <button type="button" style={secondary} disabled={busy} onClick={() => closeSelection("Change discarded.")}>Cancel</button>
            {savedForSelection().length ? (
              <button type="button" style={secondary} disabled={busy || degraded} onClick={() => void undoSelection()}>Undo: restore original</button>
            ) : null}
          </div>
          <div style={{ ...row, marginTop: 8 }}>
            <button type="button" style={secondary} disabled={busy} onClick={() => step(-1)}>Previous text</button>
            <button type="button" style={secondary} disabled={busy} onClick={() => step(1)}>Next text</button>
          </div>
        </div>
      ) : null}

      {listOpen ? (
        <div style={card}>
          <h2 style={{ margin: "0 0 8px", fontSize: 17, color: "#111" }}>Edits on this page</h2>
          {entries.length === 0 ? <p style={{ margin: 0 }}>There are no saved edits on this page.</p> : (
            <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "grid", gap: 10 }}>
              {entries.map((entry) => {
                const missing = !present.has(entry.key);
                return (
                  <li key={`${entry.scope}:${entry.key}`} style={{ borderTop: "1px solid #ccc", paddingTop: 8 }}>
                    <p style={{ margin: "0 0 2px" }}><strong>{entry.kind === "link" ? "Link address" : "Text"}{entry.scope === "site" ? ", every page" : ""}</strong></p>
                    <p style={{ margin: "0 0 2px", overflowWrap: "anywhere" }}>Was: {shorten(entry.original)}</p>
                    <p style={{ margin: "0 0 4px", overflowWrap: "anywhere" }}>Now: {shorten(entry.value)}</p>
                    {entry.scope === "site" && !entry.publicOriginPath ? <p style={{ margin: "0 0 4px", color: "#7a271a" }}>This older every-page edit is visible only to the owner. To publish it again, open a public page, select the wording, and save it as an every-page change.</p> : null}
                    {missing ? (
                      <p style={{ margin: "0 0 4px", color: "#7a271a" }}>
                        {entry.scope === "site"
                          ? "The original is not in the header or footer of this page. It may still apply on other pages."
                          : "The original is not on this page right now, so this edit is not showing. The wording may have changed, or it may appear only after opening a section."}
                      </p>
                    ) : null}
                    <button
                      type="button"
                      style={secondary}
                      disabled={busy || degraded}
                      aria-label={`Undo edit: ${shorten(entry.value, 60)}`}
                      onClick={() => void undo(entry.key, entry.scope)}
                    >
                      Undo
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      ) : null}

      <div style={row}>
        <button
          ref={toggle}
          type="button"
          style={primary}
          aria-pressed={editing}
          disabled={busy || degraded}
          onClick={() => {
            if (!editing) {
              startEditing();
              return;
            }
            if (selection) closeSelection();
            stopEditing();
            setStatus("Editing is off.");
          }}
        >
          {editing ? "Done editing" : "Edit this page"}
        </button>
        <button type="button" style={secondary} aria-expanded={listOpen} onClick={() => { setPresent(engine.present()); setListOpen((value) => !value); }}>
          Edits on this page ({entries.length})
        </button>
      </div>
    </div>
  );
}

import Link from "@/components/app-link";
import { TRAINING_CREDIT_NOTICE } from "@/lib/program/learning-credit";
import { participationContract, type ParticipationSurface } from "@/lib/participation/contracts";
import { CONSULTATION_TOMBSTONE_RETENTION_DAYS } from "@/lib/privacy/consultation-terminal-retention";

const STAFF_NOTICES: Partial<Record<ParticipationSurface, string[]>> = {
  start_routing: ["These questions are optional and exist only to help you find a place to begin. Your choices stay on this page and clear when you leave it."],
  support_routing: ["Use general work information to find support. Your choices stay on this page; no one is contacted and no request is submitted."],
  ask: ["Ask takes a question in your own words. So that it can respond, your question and the recent conversation go to outside answer and research services, so please keep names, case details and other confidential material out of what you type. The conversation stays in this browser for this session only, and you can clear it at any time.", "If you used an earlier version that accepted questions, clearing data on this device does not remove any separate records already held by the program."],
  learning: ["Learn at your own pace; none of this is required. Notes and progress you save stay on this computer until you delete them, which also means anyone else who uses this computer could see them. Nothing is shared with supervisors or program staff.", TRAINING_CREDIT_NOTICE],
  path_practice: ["The guided practices are for reading and downloading; this page does not save your answers or progress. If you saved notes in an earlier version of the site, they may still be in this browser and visible to anyone using this computer; this page neither shows nor deletes them. Nothing you read or download here goes to your supervisor or counts toward any evaluation.", TRAINING_CREDIT_NOTICE],
  my_work: ["Your saved resources, practice plans, reflection and course bookmarks stay in this browser until you clear them, so anyone using this computer could see them. None of it is sent to your supervisor or to program staff.", "Earlier versions may have saved notes or consultation references on this device. Removing a local reference does not withdraw or delete a request submitted through an earlier version, or erase any separate records already held by the program."],
  consultation_preview: ["Reviewing a summary is optional. It does not save or send a consultation request or arrange a meeting. Your form and summary disappear when you leave this page. Information carried over from Ask stays on this computer until you clear it or close the tab. Clearing it does not remove separately retained records from earlier versions."],
  consultation_submission: ["Submitting is optional. Review the summary first, and leave out client, medical, personnel, complaint, and other identifying details. Only authorized consultants can see the request you submit; it is not sent to your supervisor.", "You receive a reference and private access key to follow up. Submission does not schedule a meeting. Only requests confirmed as DSD work enter the consultation queue. This is a program consultation request, not an official DHS record or evidence of required training."],
  consultation_tracking: ["Use your reference and private access key to check your request. Keep the access key private. You can correct general work information or withdraw the request when those options are available. Authorized consultants can see these changes.", "Saving a reference on this device is optional. Anyone using this computer may see it. Deleting that saved reference does not withdraw or delete your request. Corrections and withdrawal do not change how long the request is kept."],
};

const FACTS = [
  ["participation", "Participation"],
  ["privacy", "Privacy and recording"],
  ["purpose", "Purpose and requirements"],
  ["viewers", "Who can see it"],
  ["creates", "What this creates"],
  ["officialRecord", "Official record"],
  ["retention", "How long it stays"],
] as const;

const SURFACE_HEADINGS: Partial<Record<ParticipationSurface, string>> = {
  consultant_sign_in: "How Consultant Workspace sign-in works",
  consultant_workspace: "How the Consultant Workspace works",
  one_dsd_team: "How the One DSD Team space works",
};

type ParticipationNoticeProps = {
  surface: ParticipationSurface;
  consultationRetentionDays?: number;
  consultationRetentionCalendarYears?: number;
  correctionEnabled?: boolean;
};

function displayedFact(
  field: (typeof FACTS)[number][0],
  value: string,
  props: ParticipationNoticeProps,
): string {
  if (
    field === "retention"
    && (props.surface === "consultation_submission" || props.surface === "consultation_tracking")
    && (props.consultationRetentionDays || props.consultationRetentionCalendarYears)
  ) {
    return `${value} The approved consultation period is ${props.consultationRetentionCalendarYears ? `${props.consultationRetentionCalendarYears} calendar years` : `${props.consultationRetentionDays} calendar days`} from submission.`;
  }
  if (
    field === "creates"
    && props.surface === "consultation_tracking"
    && props.correctionEnabled === false
  ) {
    return `${value} Corrections are temporarily unavailable; checking status and any permitted withdrawal remain available.`;
  }
  return value;
}

export function ParticipationNotice(props: ParticipationNoticeProps) {
  const { surface } = props;
  const contract = participationContract(surface);
  const headingId = `participation-${contract.id}`;
  const staffNotice = STAFF_NOTICES[surface];

  if (staffNotice) {
    const consultation = surface === "consultation_submission" || surface === "consultation_tracking";
    // One short line per page; the page's own detail sits one click away. Consultation pages keep their retention terms in view.
    if (!consultation) return (
      <section className="text-sm text-muted" aria-label="Your privacy and participation" data-participation-class={contract.participationClass}>
        <p className="m-0">{surface === "ask" ? "Ask is voluntary. Your question and recent conversation may be sent to outside services, so use general examples and leave out confidential details." : "Taking part here is voluntary, and anything you save stays on this computer, under your control."} <Link href="/about#participation-title">Read how participation and privacy work.</Link></p>
        <details className="mt-1"><summary className="cursor-pointer">More about this page</summary><div className="mt-2 space-y-2">{staffNotice.map((paragraph) => <p key={paragraph}>{paragraph}</p>)}</div></details>
      </section>
    );
    return (
      <section className="text-sm text-muted space-y-2" aria-label="Your privacy and participation" data-participation-class={contract.participationClass}>
        {staffNotice.map((paragraph) => <p key={paragraph}>{paragraph}</p>)}
        {consultation && (props.consultationRetentionDays || props.consultationRetentionCalendarYears) && (
          <p>Your submitted details are retained for {props.consultationRetentionCalendarYears ? `${props.consultationRetentionCalendarYears} calendar years` : `${props.consultationRetentionDays} calendar days`} from submission, even if you withdraw the request. After that, only an expired status remains for {CONSULTATION_TOMBSTONE_RETENTION_DAYS} more days before it is deleted.</p>
        )}
        {surface === "consultation_tracking" && props.correctionEnabled === false && (
          <p>Corrections are temporarily unavailable. You can still check status and withdraw when that option is available.</p>
        )}
      </section>
    );
  }

  return (
    <section className="panel" aria-labelledby={headingId} data-participation-class={contract.participationClass}>
      <p className="kicker">Before you begin</p>
      <h2 id={headingId} className="text-xl font-extrabold">
        {SURFACE_HEADINGS[surface] ?? "How this works"}
      </h2>
      <dl className="mt-3 grid gap-3 text-sm md:grid-cols-2">
        {FACTS.map(([field, label]) => (
          <div key={field}>
            <dt className="font-bold">{label}</dt>
            <dd className="m-0">{displayedFact(field, contract.disclosure[field], props)}</dd>
          </div>
        ))}
      </dl>
    </section>
  );
}

