  );
}

"use client";
import { SourceLink } from "@/components/app-link";


import Link from "@/components/app-link";
import { useRef, useState } from "react";
import { SharePage } from "@/components/share-page";
import { podcastShareHref } from "@/lib/product/share-link";
import type { PodcastReadingSupport, PodcastTranscript } from "./podcast-transcript-data";
import { FeaturedMediaPanel } from "./featured-media-panel";

type PodcastPlayerProps = PodcastReadingSupport & {
  headingLevel?: 1 | 2 | 3;
  /** True when the player is on the podcast's own page, so it does not link to itself. */
  ownPage?: boolean;
  id: string;
  src: string;
  title: string;
  intro: string;
  downloadLabel: string;
  retryLabel: string;
  errorMessage: string;
};

function timestamp(seconds: number) {
  const whole = Math.floor(seconds);
  const hours = Math.floor(whole / 3600);
  const minutes = Math.floor(whole / 60) % 60;
  const rest = String(whole % 60).padStart(2, "0");
  return hours ? `${hours}:${String(minutes).padStart(2, "0")}:${rest}` : `${minutes}:${rest}`;
}
function usableTime(seconds: number) { return Number.isFinite(seconds) && seconds >= 0; }

function readTranscript(value: unknown): PodcastTranscript {
  if (!value || typeof value !== "object" || !("segments" in value) || !Array.isArray(value.segments)) throw new Error("Transcript format is unavailable");
  const segments = value.segments.map((segment: unknown) => {
    if (!segment || typeof segment !== "object" || !("text" in segment) || typeof segment.text !== "string" || !("start" in segment) || typeof segment.start !== "number" || !("end" in segment) || typeof segment.end !== "number") throw new Error("Transcript passage is incomplete");
    return { text: segment.text, start: segment.start, end: segment.end };
  });
  if (!segments.length) throw new Error("Transcript has no passages");
  return { status: "status" in value && value.status === "reviewed" ? "reviewed" : "machine-generated", segments };
}

const positionKey = (id: string) => `one-dsd-podcast-position-${id}`;
const lastSaved = new Map<string, number>();
function savedPosition(id: string): number {
  try { const seconds = Number(window.localStorage.getItem(positionKey(id))); return Number.isFinite(seconds) && seconds > 0 ? seconds : 0; } catch { return 0; }
}
/** Your place stays in this browser only, and is written every few seconds rather than constantly. */
function rememberPosition(id: string, seconds: number, clear = false) {
  if (!clear && Math.abs(seconds - (lastSaved.get(id) ?? -10)) < 5) return;
  lastSaved.set(id, seconds);
  try { if (clear) window.localStorage.removeItem(positionKey(id)); else window.localStorage.setItem(positionKey(id), String(Math.floor(seconds))); } catch { /* Playback still works without saving. */ }
}

export function PodcastPlayer({ headingLevel = 3, ownPage = false, id, src, title, intro, downloadLabel, retryLabel, errorMessage, transcript, transcriptUrl, chapters }: PodcastPlayerProps) {
  const Heading = headingLevel === 1 ? "h1" : headingLevel === 2 ? "h2" : "h3";
  const player = useRef<HTMLAudioElement>(null);
  const [failed, setFailed] = useState(false);
  const pendingSeek = useRef<number | null>(null);
  const [loadedTranscript, setLoadedTranscript] = useState<PodcastTranscript | null>(null);
  const [transcriptLoading, setTranscriptLoading] = useState(false);
  const [transcriptFailed, setTranscriptFailed] = useState(false);
  const [transcriptQuery, setTranscriptQuery] = useState("");
  const titleId = `podcast-${id}-title`;
  const detailsId = `podcast-${id}-details`;
  const errorId = `podcast-${id}-error`;
  const playerId = `podcast-${id}-audio`;
  const reading = transcript ?? loadedTranscript;
  const query = transcriptQuery.trim().toLocaleLowerCase();
  const passages = reading?.segments.filter(segment => !query || segment.text.toLocaleLowerCase().includes(query)) ?? [];

  async function loadTranscript() {
    if (!transcriptUrl || reading || transcriptLoading) return;
    setTranscriptLoading(true);
    setTranscriptFailed(false);
    try {
      if (!transcriptUrl.startsWith("/") || transcriptUrl.startsWith("//")) throw new Error("A local transcript is required");
      const response = await fetch(transcriptUrl);
      if (!response.ok) throw new Error("Transcript could not be loaded");
      setLoadedTranscript(readTranscript(await response.json()));
    } catch { setTranscriptFailed(true); }
    finally { setTranscriptLoading(false); }
  }

  function applyPendingSeek() {
    const audio = player.current;
    const seconds = pendingSeek.current;
    if (!audio || seconds === null) return true;
    try {
      if (Number.isFinite(audio.duration) && seconds > audio.duration) throw new Error("Time is outside the recording");
      audio.currentTime = seconds;
      pendingSeek.current = null;
      return true;
    } catch { setFailed(true); return false; }
  }

  async function playFrom(seconds: number) {
    const audio = player.current;
    if (!audio || !usableTime(seconds)) return;
    setFailed(false);
    pendingSeek.current = seconds;
    try {
      if (audio.readyState >= 1 && !applyPendingSeek()) return;
      if (audio.readyState < 1) audio.load();
      await audio.play();
    } catch { setFailed(true); }
  }

  async function retry() {
    setFailed(false);
    const audio = player.current;
    if (!audio) return;
    audio.load();
    try { await audio.play(); } catch { setFailed(true); }
  }

  return <FeaturedMediaPanel kind="podcast" className="print:hidden"><section id={`podcast-${id}`} className="space-y-3 print:hidden" aria-labelledby={titleId}>
    <Heading id={titleId} className={headingLevel === 1 ? "text-4xl font-semibold" : "text-2xl font-semibold"}>{title}</Heading>
    <p id={detailsId}>{intro}</p>
    <audio id={playerId} ref={player} src={src} controls preload="none" className="w-full max-w-2xl" aria-labelledby={titleId} aria-describedby={`${detailsId}${failed ? ` ${errorId}` : ""}`} onLoadedMetadata={() => { if (pendingSeek.current === null) { const saved = savedPosition(id); if (saved && player.current && saved < player.current.duration - 5) player.current.currentTime = saved; } applyPendingSeek(); }} onPlay={event => { const current = event.currentTarget; current.ownerDocument.querySelectorAll<HTMLMediaElement>("audio, video").forEach(media => { if (media !== current) media.pause(); }); current.ownerDocument.dispatchEvent(new CustomEvent("pac-media-play")); }} onTimeUpdate={event => rememberPosition(id, event.currentTarget.currentTime)} onEnded={() => rememberPosition(id, 0, true)} onError={() => setFailed(true)} onCanPlay={() => { if (pendingSeek.current === null) setFailed(false); }}>
      <SourceLink href={src} download>{downloadLabel}</SourceLink>
    </audio>
    <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
      <SharePage title={title} href={podcastShareHref(id)} noun="podcast" compact />
      {ownPage ? null : <Link href={podcastShareHref(id)} className="text-sm underline underline-offset-4">Open the podcast page</Link>}
    </div>
    {failed ? <div><p id={errorId} role="alert" className="error">{errorMessage}</p><button className="btn btn--light" type="button" onClick={() => void retry()}>{retryLabel}</button></div> : null}
    {chapters?.length ? <nav aria-label={`${title} chapters`} className="rounded-xl border border-line p-4">
      <p className="font-semibold">Choose a chapter</p>
      <ol className="mt-3 space-y-2">{chapters.map((chapter, index) => <li key={`${chapter.start}-${index}`}>
        <button type="button" className="inline-flex min-h-11 items-center text-left underline underline-offset-4" disabled={!usableTime(chapter.start)} aria-controls={playerId} onClick={() => void playFrom(chapter.start)}>
          {usableTime(chapter.start) ? `Play from ${timestamp(chapter.start)} · ` : ""}{chapter.title}
        </button>
      </li>)}</ol>
    </nav> : null}
    {transcript?.segments.length || transcriptUrl ? <div className="rounded-xl border border-line p-4">
      <details className="mt-3" onToggle={event => { if (event.currentTarget.open) void loadTranscript(); }}>
        <summary className="cursor-pointer font-semibold">Read the complete transcript</summary>
        <p className="mt-3 text-sm leading-6">Read at your own pace. Each time stamp starts the recording at that passage. The text stays here even if the recording will not play.</p>
        {transcriptLoading ? <p role="status" className="mt-3">Loading the transcript…</p> : null}
        {transcriptFailed ? <div className="mt-3"><p role="alert">The transcript could not be loaded. The recording remains available above.</p><button type="button" className="btn btn--light mt-2" onClick={() => void loadTranscript()}>Try loading the transcript again</button></div> : null}
        {reading ? <div className="mt-4"><label className="block font-semibold" htmlFor={`podcast-${id}-transcript-search`}>Find words in this transcript</label><input id={`podcast-${id}-transcript-search`} type="search" value={transcriptQuery} onChange={event => setTranscriptQuery(event.target.value)} className="mt-2 w-full rounded-lg border border-line bg-white px-3 py-2" />
          {query ? <p role="status" className="mt-2 text-sm">{passages.length} matching {passages.length === 1 ? "passage" : "passages"}. <button type="button" className="underline" onClick={() => setTranscriptQuery("")}>Show the complete transcript</button></p> : null}
        </div> : null}
        <ol className="mt-4 list-none space-y-5 p-0">{passages.map((segment, index) => <li key={`${segment.start}-${index}`}>
          {usableTime(segment.start) ? <button type="button" className="inline-flex min-h-11 items-center text-sm font-semibold underline underline-offset-4" aria-controls={playerId} onClick={() => void playFrom(segment.start)}>Play from {timestamp(segment.start)}</button> : null}
          <p className="mt-2 whitespace-pre-line leading-7">{segment.text}</p>
        </li>)}</ol>
      </details>
    </div> : null}
  </section></FeaturedMediaPanel>;
}

"use client";

import { useId } from "react";
import type { PolicyAnalysis, PolicySource } from "@/lib/policy-analysis/contract";
import { ANSWER_KIND_LABELS, formatDate, humanizeId, type QuestionLabels } from "./labels";
import styles from "./policy-analysis.module.css";

type Citation = { sourceId: string; excerpt: string };

export function Quotes({ citations, sources }: { citations: Citation[]; sources: PolicySource[] }) {
  if (!citations.length) return null;
  return (
    <>
      {citations.map((citation, index) => (
        <blockquote key={`${citation.sourceId}-${index}`} className={styles.quote}>
          “{citation.excerpt}”
          <cite>From: {sources.find(source => source.id === citation.sourceId)?.title ?? "a source no longer in this analysis"}</cite>
        </blockquote>
      ))}
    </>
  );
}

function AnswerBlock({ kind, text, citations, sources }: { kind: "evidence" | "inference" | "gap"; text: string; citations: Citation[]; sources: PolicySource[] }) {
  if (kind === "gap") {
    return (
      <div className={styles.gap}>
        <p className={`${styles.gapLabel} m-0`}>{ANSWER_KIND_LABELS.gap}</p>
        <p className={`${styles.pre} m-0`}>{text}</p>
        <Quotes citations={citations} sources={sources} />
      </div>
    );
  }
  return (
    <div>
      <span className={styles.answerLabel}>{ANSWER_KIND_LABELS[kind]}</span>
      <p className={`${styles.pre} m-0`}>{text}</p>
      <Quotes citations={citations} sources={sources} />
    </div>
  );
}

/** The equity analysis: summary, the information still needed, answers by question, principle findings and limitations. */
export function AnalysisView({ analysis, sources, questions, principleLabels }: {
  analysis: PolicyAnalysis;
  sources: PolicySource[];
  questions: QuestionLabels;
  principleLabels?: Record<string, string>;
}) {
  const ids = useId();
  const principleName = (id: string) => principleLabels?.[id] ?? humanizeId(id);
  const gaps = [
    ...analysis.answers.filter(answer => answer.kind === "gap").map(answer => ({ key: `q-${answer.questionId}`, about: questions[answer.questionId]?.prompt ?? humanizeId(answer.questionId), text: answer.text })),
    ...analysis.principles.filter(finding => finding.kind === "gap").map(finding => ({ key: `p-${finding.principleId}`, about: principleName(finding.principleId), text: finding.finding })),
  ];

  // Group answers by the instrument's stages, keeping the instrument's order; unknown questions go last.
  const groups = new Map<string, { order: number; answers: PolicyAnalysis["answers"] }>();
  for (const answer of analysis.answers) {
    const stage = questions[answer.questionId]?.stage ?? "Other questions";
    const order = questions[answer.questionId]?.stageOrder ?? 999;
    const group = groups.get(stage) ?? { order, answers: [] };
    group.answers.push(answer);
    groups.set(stage, group);
  }
  const ordered = [...groups.entries()].sort((a, b) => a[1].order - b[1].order);

  return (
    <div className={styles.stack}>
      <div>
        <h3 className="mt-0">Summary</h3>
        <p className={`${styles.pre} m-0`}>{analysis.summary}</p>
        <p className={`${styles.muted} mb-0`}>Prepared {formatDate(analysis.generatedAt)}.</p>
      </div>

      {gaps.length ? (
        <div className={styles.gap} aria-labelledby={`${ids}-gaps`} role="region">
          <h3 id={`${ids}-gaps`} className="mt-0">Information still needed</h3>
          <ul className="list-disc pl-6 m-0">
            {gaps.map(gap => <li key={gap.key}><strong>{gap.about}</strong> {gap.text}</li>)}
          </ul>
          <p className="mb-0 mt-2">Attach more material in step 2, such as the full policy, data or notes from the people affected, and run the analysis again to fill these in.</p>
        </div>
      ) : null}

      <div>
        <h3 className="mt-0">Answers to the policy review questions</h3>
        {ordered.map(([stage, group]) => (
          <section key={stage} className="mt-3" aria-label={stage}>
            <h4 className="font-bold text-lg m-0">{stage}</h4>
            <ol className={`${styles.list} mt-2`}>
              {group.answers.map(answer => (
                <li key={answer.questionId} className={styles.item}>
                  <p className="m-0 font-bold">{questions[answer.questionId]?.prompt ?? humanizeId(answer.questionId)}</p>
                  <div className="mt-2"><AnswerBlock kind={answer.kind} text={answer.text} citations={answer.citations} sources={sources} /></div>
                </li>
              ))}
            </ol>
          </section>
        ))}
      </div>

      {analysis.principles.length ? (
        <div>
          <h3 className="mt-0">Equity principles</h3>
          <ul className={styles.list}>
            {analysis.principles.map(finding => (
              <li key={finding.principleId} className={styles.item}>
                <p className="m-0 font-bold">{principleName(finding.principleId)}</p>
                <div className="mt-2"><AnswerBlock kind={finding.kind} text={finding.finding} citations={finding.citations} sources={sources} /></div>
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      {analysis.limitations.length ? (
        <div>
          <h3 className="mt-0">Limitations</h3>
          <ul className="list-disc pl-6 m-0">{analysis.limitations.map((item, index) => <li key={index}>{item}</li>)}</ul>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import type { PolicyCase } from "@/lib/policy-analysis/contract";
import { AnalysisView } from "./analysis-view";
import type { QuestionLabels } from "./labels";
import styles from "./policy-analysis.module.css";

function Elapsed() {
  const [seconds, setSeconds] = useState(0);
  useEffect(() => {
    const timer = window.setInterval(() => setSeconds(value => value + 1), 1000);
    return () => window.clearInterval(timer);
  }, []);
  return <span aria-hidden="true"> ({seconds} seconds so far)</span>;
}

/** Step 3: run the equity analysis, or explain the manual route when the analysis service is not available. */
export function AnalyzeStep({ value, saved, manual, manualReason, running, busy, onAnalyze, questions, principleLabels }: {
  value: PolicyCase | null;
  saved: boolean;
  manual: boolean;
  manualReason?: string | null;
  running: boolean;
  busy: boolean;
  onAnalyze: () => void;
  questions: QuestionLabels;
  principleLabels?: Record<string, string>;
}) {
  const analysis = value?.analysis ?? null;
  const final = value?.status === "final";
  return (
    <section className={styles.step} aria-labelledby="analyze-title" aria-busy={running}>
      <span className={styles.stepNumber}>Step 3</span>
      <h2 id="analyze-title">Analyze</h2>
      {manual ? (
        <div className="notice notice--warn">
          <p className="m-0"><strong>The analysis service is not available right now.</strong> {manualReason || ""}</p>
          <p className="mb-0 mt-2">You can still finish this work by hand: write the recommended changes yourself in step 4, then send them for decisions.</p>
        </div>
      ) : (
        <>
          <p className="mt-0">The analysis reads the sources against the policy review questions and the equity principles, quotes the passages it relies on, says plainly where information is missing, and drafts recommended changes.</p>
          {!value ? <p className={styles.muted}>Save the analysis in step 2 first.</p> : null}
          {value && !value.sources.length ? <p className={styles.muted}>No sources are attached. The analysis will be far more exact with the policy text added in step 2.</p> : null}
          {value && !final ? (
            <div className={styles.row}>
              <button type="button" className="btn btn--primary" disabled={busy || !value} onClick={onAnalyze}>
                {running ? "Analyzing…" : analysis ? "Run the analysis again" : "Run the equity analysis"}
              </button>
              {!saved ? <span className={styles.muted}>Your unsaved changes in step 2 are saved first.</span> : null}
            </div>
          ) : null}
          {analysis && value?.recommendations.length && !final ? <p className={`${styles.muted} mb-0`}>Running it again drafts a new set of recommended changes from the current sources.</p> : null}
        </>
      )}
      <p className="mt-2 mb-0" role="status">
        {running ? <>Analyzing the policy. This can take up to two minutes. Keep this page open.<Elapsed /></> : ""}
      </p>
      {analysis ? <div className="mt-4"><AnalysisView analysis={analysis} sources={value?.sources ?? []} questions={questions} principleLabels={principleLabels} /></div> : null}
    </section>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { api, isConflict, type CaseSummary } from "./api";
import { formatDate, plural, STATUS_LABELS } from "./labels";
import styles from "./policy-analysis.module.css";

export function CaseLibrary({ onOpen, onStart, onError, savingAvailable, refreshKey }: {
  onOpen: (id: string) => void;
  onStart: () => void;
  onError: (error: unknown) => void;
  savingAvailable: boolean;
  refreshKey: number;
}) {
  const [cases, setCases] = useState<CaseSummary[]>([]);
  const [nextOffset, setNextOffset] = useState<number | null>(null);
  const [loading, setLoading] = useState(savingAvailable);
  const [loadFailed, setLoadFailed] = useState(false);
  const [deleting, setDeleting] = useState<string | null>(null);
  const [confirming, setConfirming] = useState<string | null>(null);
  const [message, setMessage] = useState("");

  const load = useCallback(async (offset: number) => {
    setLoading(true);
    try {
      const page = await api.listCases(offset);
      setCases(current => offset === 0 ? page.cases : [...current, ...page.cases.filter(item => !current.some(existing => existing.id === item.id))]);
      setNextOffset(page.nextOffset);
      setLoadFailed(false);
    } catch (error) {
      setLoadFailed(true);
      onError(error);
    } finally {
      setLoading(false);
    }
  }, [onError]);

  useEffect(() => {
    if (!savingAvailable) return;
    let active = true;
    api.listCases(0)
      .then(page => { if (!active) return; setCases(page.cases); setNextOffset(page.nextOffset); setLoadFailed(false); })
      .catch(error => { if (!active) return; setLoadFailed(true); onError(error); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [onError, refreshKey, savingAvailable]);

  async function remove(item: CaseSummary) {
    setDeleting(item.id);
    setMessage("");
    try {
      await api.deleteCase(item.id, item.version);
      setCases(current => current.filter(entry => entry.id !== item.id));
      setConfirming(null);
      setMessage(`Deleted "${item.title}".`);
    } catch (error) {
      onError(error);
      if (isConflict(error)) void load(0);
    } finally {
      setDeleting(null);
    }
  }

  return (
    <section className={styles.step} aria-labelledby="case-library-title">
      <div className={styles.between}>
        <h2 id="case-library-title" className="m-0">Saved policy analyses</h2>
        <button type="button" className="btn btn--primary" onClick={onStart}>Start a new analysis</button>
      </div>
      <p className={styles.muted}>Each analysis keeps its policy, the material you added, the recommended changes, every decision and the formal proposal.</p>
      <p className={`${styles.small} m-0`} role="status">{message}</p>
      {!savingAvailable ? (
        <p className="m-0">Saved analyses cannot be shown here because saving is not available on this server.</p>
      ) : loading && !cases.length ? (
        <p className="m-0" role="status">Loading saved analyses…</p>
      ) : loadFailed && !cases.length ? (
        <p className="m-0">The saved analyses could not be loaded. <button type="button" className={styles.linkButton} onClick={() => void load(0)}>Try again</button></p>
      ) : !cases.length ? (
        <p className="m-0">No analyses are saved yet. Start a new analysis to choose a policy.</p>
      ) : (
        <ul className={styles.list}>
          {cases.map(item => (
            <li key={item.id} className={styles.item}>
              <div className={styles.between}>
                <div style={{ minWidth: 0 }}>
                  <p className={`${styles.choiceTitle} m-0`}>{item.title}</p>
                  <p className="m-0">{item.policyTitle}</p>
                </div>
                <p className="m-0 font-bold">{STATUS_LABELS[item.status] ?? item.status}</p>
              </div>
              <p className={`${styles.muted} m-0 mt-1`}>
                {plural(item.recommendationCount, "recommended change", "recommended changes")} · {plural(item.approvedCount, "approved", "approved")}
                {" · "}Started {formatDate(item.createdAt)} · Last changed {formatDate(item.updatedAt)}
                {item.finalizedAt ? ` · Formalized ${formatDate(item.finalizedAt)}` : ""}
              </p>
              <div className={`${styles.row} mt-2`}>
                <button type="button" className="btn btn--light" onClick={() => onOpen(item.id)} aria-label={`Open ${item.title}`}>Open</button>
                {confirming === item.id ? (
                  <>
                    <span className={styles.small}>Delete this analysis and everything in it? This cannot be undone.</span>
                    <button type="button" className="btn btn--light" disabled={deleting === item.id} onClick={() => void remove(item)}>
                      {deleting === item.id ? "Deleting…" : "Yes, delete it"}
                    </button>
                    <button type="button" className={styles.linkButton} disabled={deleting === item.id} onClick={() => setConfirming(null)}>Keep it</button>
                  </>
                ) : (
                  <button type="button" className={`${styles.linkButton} ${styles.danger}`} onClick={() => setConfirming(item.id)} aria-label={`Delete ${item.title}`}>Delete</button>
                )}
              </div>
            </li>
          ))}
        </ul>
      )}
      {nextOffset !== null ? (
        <p className="mt-3 mb-0"><button type="button" className="btn btn--light" disabled={loading} onClick={() => void load(nextOffset)}>{loading ? "Loading…" : "Show more"}</button></p>
      ) : null}
    </section>
  );
}

"use client";
import { SourceLink } from "@/components/app-link";


import { useId, useState } from "react";
import { DECISION_ROLE_LABELS, DECISION_ROLES, POLICY_LIMITS, type DecisionOutcome, type DecisionRoleId, type Recommendation } from "@/lib/policy-analysis/contract";
import { CHANGE_TYPE_LABELS, formatDate, OUTCOME_ACTIONS, OUTCOME_LABELS, ROLE_NAMES } from "./labels";
import styles from "./policy-analysis.module.css";

export type DecisionInput = { recommendationId: string; outcome: DecisionOutcome; reason: string; conditions?: string; deferredUntil?: string; decidingAs?: DecisionRoleId };

function DecisionSummary({ decision }: { decision: NonNullable<Recommendation["decision"]> }) {
  return (
    <>
      <strong>{OUTCOME_LABELS[decision.outcome]}</strong> by the {ROLE_NAMES[decision.role]} on {formatDate(decision.at)}. {decision.reason}
      {decision.conditions ? <> Conditions: {decision.conditions}</> : null}
      {decision.deferredUntil ? <> Come back to it on {formatDate(decision.deferredUntil)}.</> : null}
    </>
  );
}

function DecisionForm({ item, outcome, busy, onCancel, onSubmit }: {
  item: Recommendation;
  outcome: DecisionOutcome;
  busy: boolean;
  onCancel: () => void;
  onSubmit: (input: DecisionInput) => Promise<unknown>;
}) {
  const ids = useId();
  const [reason, setReason] = useState("");
  const [conditions, setConditions] = useState("");
  const [deferredUntil, setDeferredUntil] = useState("");
  const [problem, setProblem] = useState("");

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    if (!reason.trim()) { setProblem("Give the reason for this decision."); return; }
    if (outcome === "deferred" && !/^\d{4}-\d{2}-\d{2}$/.test(deferredUntil)) { setProblem("Choose the date to come back to this change."); return; }
    setProblem("");
    await onSubmit({
      recommendationId: item.id,
      outcome,
      reason: reason.trim(),
      ...(conditions.trim() ? { conditions: conditions.trim() } : {}),
      ...(outcome === "deferred" ? { deferredUntil } : {}),
    });
  }

  return (
    <form noValidate className={styles.decisionForm} onSubmit={event => void submit(event)} aria-label={`${OUTCOME_ACTIONS[outcome]}: ${item.title}`}>
      <p className="m-0 font-bold">{OUTCOME_ACTIONS[outcome]} this change</p>
      {problem ? <p className="field m-0 mt-1"><span className="error" role="alert">{problem}</span></p> : null}
      <div className="field mt-2">
        <label htmlFor={`${ids}-reason`}>Reason</label>
        <textarea id={`${ids}-reason`} rows={3} maxLength={POLICY_LIMITS.reasonCharacters} value={reason} onChange={event => setReason(event.target.value)} required aria-invalid={problem.startsWith("Give") || undefined} />
      </div>
      <div className="field">
        <label htmlFor={`${ids}-conditions`}>Conditions (optional)</label>
        <p className="help m-0" id={`${ids}-conditions-help`}>For example: approved once the notice is available in the five most-used languages.</p>
        <textarea id={`${ids}-conditions`} rows={2} maxLength={POLICY_LIMITS.reasonCharacters} aria-describedby={`${ids}-conditions-help`} value={conditions} onChange={event => setConditions(event.target.value)} />
      </div>
      {outcome === "deferred" ? (
        <div className="field">
          <label htmlFor={`${ids}-until`}>Date to come back to it</label>
          <input id={`${ids}-until`} type="date" value={deferredUntil} onChange={event => setDeferredUntil(event.target.value)} required aria-invalid={problem.startsWith("Choose") || undefined} />
        </div>
      ) : null}
      <div className={styles.row}>
        <button type="submit" className="btn btn--primary" disabled={busy}>{busy ? "Recording…" : `Record: ${OUTCOME_LABELS[outcome].toLowerCase()}`}</button>
        <button type="button" className={styles.linkButton} disabled={busy} onClick={onCancel}>Cancel</button>
      </div>
    </form>
  );
}

/** Step 5: approve, reject or defer each change, recorded by role with the reason. */
export function DecisionsStep({ recommendations, canDecide, busy, decidingAs, onDecidingAs, onDecide, notReadyText }: {
  recommendations: Recommendation[];
  canDecide: boolean;
  busy: boolean;
  decidingAs: DecisionRoleId;
  onDecidingAs: (role: DecisionRoleId) => void;
  onDecide: (input: DecisionInput) => Promise<boolean>;
  notReadyText?: string;
}) {
  const [open, setOpen] = useState<{ id: string; outcome: DecisionOutcome } | null>(null);
  const decided = recommendations.filter(item => item.decision).length;

  return (
    <section className={styles.step} aria-labelledby="decisions-title">
      <span className={styles.stepNumber}>Step 5</span>
      <h2 id="decisions-title">Decide</h2>
      <p className="mt-0">Approve, reject or defer each change and give the reason. Each decision is recorded with the role of the person who made it, never a name.</p>
      <div className="field">
        <label htmlFor="deciding-as">Deciding as</label>
        <p className="help m-0" id="deciding-as-help">Choose your role before you record a decision. It applies to each decision you record and to formalizing in step 6.</p>
        <select id="deciding-as" aria-describedby="deciding-as-help" value={decidingAs} disabled={busy} onChange={event => onDecidingAs(event.target.value as DecisionRoleId)}>
          {DECISION_ROLES.map(role => <option key={role} value={role}>{DECISION_ROLE_LABELS[role]}</option>)}
        </select>
      </div>
      {notReadyText ? <p className={styles.muted}>{notReadyText}</p> : null}
      {recommendations.length ? <p className={styles.muted}>{decided} of {recommendations.length} changes have a decision.</p> : null}
      <ol className={styles.list}>
        {recommendations.map(item => (
          <li key={item.id} className={styles.item}>
            <p className={styles.recType}>{CHANGE_TYPE_LABELS[item.type]}</p>
            <p className="m-0 font-bold"><SourceLink href={`#change-${item.id}`}>{item.title}</SourceLink></p>
            <div className={`${styles.decision} mt-2`} aria-live="polite">
              {item.decision ? <DecisionSummary decision={item.decision} /> : "No decision yet."}
            </div>
            {canDecide ? (
              open?.id === item.id ? (
                <DecisionForm key={open.outcome} item={item} outcome={open.outcome} busy={busy} onCancel={() => setOpen(null)} onSubmit={async input => {
                  const ok = await onDecide(input);
                  if (ok) setOpen(null);
                  return ok;
                }} />
              ) : (
                <div className={`${styles.row} mt-2`} role="group" aria-label={`${item.decision ? "Change the decision" : "Decision"} for ${item.title}`}>
                  {item.decision ? <span className={styles.small}>Change the decision:</span> : null}
                  {(["approved", "rejected", "deferred"] as const).map(outcome => (
                    <button key={outcome} type="button" className="btn btn--light" disabled={busy} onClick={() => setOpen({ id: item.id, outcome })}>
                      {OUTCOME_ACTIONS[outcome]}
                    </button>
                  ))}
                </div>
              )
            ) : null}
            {item.history.length ? (
              <details className="mt-2">
                <summary className={styles.small}>Decision history ({item.history.length})</summary>
                <ol className={styles.history}>
                  {[...item.history].reverse().map((entry, index) => (
                    <li key={`${entry.at}-${index}`}>
                      {formatDate(entry.at)}: {OUTCOME_LABELS[entry.outcome]} by the {ROLE_NAMES[entry.role]}. {entry.reason}
                      {entry.conditions ? ` Conditions: ${entry.conditions}` : ""}
                      {entry.deferredUntil ? ` Come back to it on ${formatDate(entry.deferredUntil)}.` : ""}
                    </li>
                  ))}
                </ol>
              </details>
            ) : null}
          </li>
        ))}
      </ol>
    </section>
  );
}

