"use client";

import { useState } from "react";
import { POLICY_LIMITS, type PolicySource, type Recommendation } from "@/lib/policy-analysis/contract";
import { blankRecommendation, problemsWith, RecommendationDisplay, RecommendationForm, toEditable, type EditableRecommendation } from "./recommendation-card";
import styles from "./policy-analysis.module.css";

/** Step 4: the recommended changes, each editable, plus changes added by hand. */
export function RecommendationsStep({ recommendations, sources, catalogTitles, principleName, editable, busy, manual, onSave }: {
  recommendations: Recommendation[];
  sources: PolicySource[];
  catalogTitles: Record<string, string>;
  principleName: (id: string) => string;
  editable: boolean;
  busy: boolean;
  /** True when the analysis service is not available and the person writes the changes. */
  manual: boolean;
  onSave: (all: EditableRecommendation[]) => Promise<boolean>;
}) {
  const [editing, setEditing] = useState<Record<string, EditableRecommendation>>({});
  const [added, setAdded] = useState<EditableRecommendation[]>([]);
  const [problems, setProblems] = useState<Record<string, string[]>>({});

  async function save(id: string) {
    const draft = editing[id] ?? added.find(item => item.id === id);
    if (!draft) return;
    const found = problemsWith(draft);
    setProblems(current => ({ ...current, [id]: found }));
    if (found.length) return;
    const isNew = added.some(item => item.id === id);
    const all = [
      ...recommendations.map(item => item.id === id ? draft : toEditable(item)),
      ...(isNew ? [draft] : []),
    ].map(toEditable);
    if (await onSave(all)) {
      setEditing(current => { const next = { ...current }; delete next[id]; return next; });
      setAdded(current => current.filter(item => item.id !== id));
      setProblems(current => { const next = { ...current }; delete next[id]; return next; });
    }
  }

  function cancel(id: string) {
    setEditing(current => { const next = { ...current }; delete next[id]; return next; });
    setAdded(current => current.filter(item => item.id !== id));
    setProblems(current => { const next = { ...current }; delete next[id]; return next; });
  }

  const full = recommendations.length + added.length >= POLICY_LIMITS.recommendations;

  return (
    <section className={styles.step} aria-labelledby="recommendations-title">
      <span className={styles.stepNumber}>Step 4</span>
      <h2 id="recommendations-title">Recommended changes</h2>
      <p className="mt-0">
        {manual
          ? "Write each change you recommend: what is done differently, the wording if the policy text changes, the equity consideration, and the person or area responsible."
          : "Each change names what is done differently, the wording when the policy text changes, the equity consideration it answers and the evidence behind it. Correct anything before it goes for decisions."}
      </p>
      {!recommendations.length && !added.length ? <p className={styles.muted}>No recommended changes yet.</p> : null}
      <ol className={styles.list}>
        {recommendations.map(item => {
          const draft = editing[item.id];
          return (
            <li key={item.id} id={`change-${item.id}`} className={styles.recCard}>
              {draft ? (
                <>
                  <RecommendationForm item={draft} problems={problems[item.id] ?? []} onChange={next => setEditing(current => ({ ...current, [item.id]: next }))} />
                  <div className={styles.row}>
                    <button type="button" className="btn btn--primary" disabled={busy} onClick={() => void save(item.id)}>{busy ? "Saving…" : "Save this change"}</button>
                    <button type="button" className={styles.linkButton} disabled={busy} onClick={() => cancel(item.id)}>Cancel</button>
                  </div>
                </>
              ) : (
                <>
                  <RecommendationDisplay item={toEditable(item)} decision={item.decision} sources={sources} catalogTitles={catalogTitles} principleName={principleName} />
                  {editable ? <button type="button" className="btn btn--light mt-2" disabled={busy} onClick={() => setEditing(current => ({ ...current, [item.id]: toEditable(item) }))} aria-label={`Edit ${item.title}`}>Edit</button> : null}
                </>
              )}
            </li>
          );
        })}
        {added.map((item, index) => (
          <li key={item.id} className={styles.recCard}>
            <p className={styles.recType}>New change {index + 1}</p>
            <RecommendationForm item={item} problems={problems[item.id] ?? []} onChange={next => setAdded(current => current.map(entry => entry.id === item.id ? next : entry))} />
            <div className={styles.row}>
              <button type="button" className="btn btn--primary" disabled={busy} onClick={() => void save(item.id)}>{busy ? "Saving…" : "Save this change"}</button>
              <button type="button" className={styles.linkButton} disabled={busy} onClick={() => cancel(item.id)}>Discard</button>
            </div>
          </li>
        ))}
      </ol>
      {editable ? (
        <p className="mt-3 mb-0">
          <button type="button" className="btn btn--light" disabled={busy || full} onClick={() => setAdded(current => [...current, blankRecommendation()])}>Add a change</button>
          {full ? <span className={`${styles.muted} ml-2`}>An analysis can hold up to {POLICY_LIMITS.recommendations} changes.</span> : null}
        </p>
      ) : null}
    </section>
  );
}

"use client";
import { SourceLink } from "@/components/app-link";


import { useId, useRef, useState } from "react";
import { POLICY_LIMITS, type PolicySource } from "@/lib/policy-analysis/contract";
import { uploadDocument } from "./api";
import styles from "./policy-analysis.module.css";

const ORIGIN_LABELS: Record<PolicySource["origin"], string> = {
  user: "Attached or pasted",
  catalog: "Official text",
  program: "From this program",
};

function wordCount(text: string): number {
  return text.trim() ? text.trim().split(/\s+/).length : 0;
}

/** Keeps one source inside the per-source limit and says so when it had to shorten it. */
export function fitSource(source: PolicySource): { source: PolicySource; shortened: boolean } {
  if (source.text.length <= POLICY_LIMITS.sourceCharacters) return { source, shortened: false };
  return { source: { ...source, text: source.text.slice(0, POLICY_LIMITS.sourceCharacters) }, shortened: true };
}

/** Step 2: the policy text and supporting material, the question to answer, and the analysis title. */
export function SourcesEditor({ title, onTitle, sources, onSources, context, onContext, disabled, onError, onNotice, children }: {
  title: string;
  onTitle: (value: string) => void;
  sources: PolicySource[];
  onSources: (next: PolicySource[]) => void;
  context: string;
  onContext: (value: string) => void;
  disabled: boolean;
  onError: (error: unknown) => void;
  onNotice: (message: string) => void;
  children?: React.ReactNode;
}) {
  const ids = useId();
  const fileInput = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);
  const [pasteTitle, setPasteTitle] = useState("");
  const [pasteText, setPasteText] = useState("");
  const total = sources.reduce((sum, source) => sum + source.text.length, 0);
  const full = sources.length >= POLICY_LIMITS.sources;
  const locked = disabled || uploading;

  function add(source: PolicySource): boolean {
    if (sources.length >= POLICY_LIMITS.sources) {
      onError(new Error(`An analysis can hold up to ${POLICY_LIMITS.sources} sources. Remove one before adding another.`));
      return false;
    }
    const fitted = fitSource(source);
    if (total + fitted.source.text.length > POLICY_LIMITS.totalSourceCharacters) {
      onError(new Error("The sources together would hold too much text. Remove a source or add a shorter passage."));
      return false;
    }
    onSources([...sources.filter(item => item.id !== fitted.source.id), fitted.source]);
    onNotice(fitted.shortened ? `Added "${fitted.source.title}". It was long, so only the first part was kept.` : `Added "${fitted.source.title}".`);
    return true;
  }

  async function upload(files: FileList | null) {
    const file = files?.[0];
    if (fileInput.current) fileInput.current.value = "";
    if (!file) return;
    setUploading(true);
    try {
      const result = await uploadDocument(file);
      const added = add({ id: result.source.id, title: result.source.title.slice(0, 500), text: result.source.text, origin: "user", ...(result.note ? { note: result.note.slice(0, 2_000) } : {}) });
      if (added && result.note) onNotice(`Added "${result.source.title}". ${result.note}`);
    } catch (error) {
      onError(error);
    } finally {
      setUploading(false);
    }
  }

  function addPasted() {
    const text = pasteText.trim();
    if (!text) { onError(new Error("Paste the text before adding it.")); return; }
    const name = pasteTitle.trim() || `Pasted text ${sources.length + 1}`;
    if (add({ id: `paste-${crypto.randomUUID()}`, title: name.slice(0, 500), text, origin: "user" })) {
      setPasteTitle("");
      setPasteText("");
    }
  }

  return (
    <section className={styles.step} aria-labelledby={`${ids}-title`}>
      <span className={styles.stepNumber}>Step 2</span>
      <h2 id={`${ids}-title`}>Add the policy text and supporting material</h2>
      <p className="mt-0">Attach the policy itself and anything that shows how it works in practice: data, complaints, meeting notes, letters or forms people receive. The analysis quotes only what is in these sources.</p>

      <div className={styles.row}>
        <input ref={fileInput} type="file" className="sr-only" tabIndex={-1} aria-hidden="true" accept=".pdf,.docx,.pptx,.txt,.csv,.tsv,.xlsx" onChange={event => void upload(event.target.files)} />
        <button type="button" className={`btn btn--light ${styles.attach}`} aria-label="Attach a document" disabled={locked || full} onClick={() => fileInput.current?.click()}>
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true"><path d="m8 12 7-7a4 4 0 0 1 6 6L10 22a6 6 0 0 1-8-8L13 3a2 2 0 0 1 3 3L5 17" /></svg>
          {uploading ? "Reading the document…" : "Attach a document"}
        </button>
        <span className={styles.muted}>PDF with selectable text, Word, PowerPoint, Excel, comma-separated or plain text, up to 20 megabytes.</span>
      </div>

      <details className="mt-3">
        <summary className="font-bold">Paste text</summary>
        <div className="mt-2">
          <div className="field">
            <label htmlFor={`${ids}-paste-title`}>Title of the pasted text</label>
            <input id={`${ids}-paste-title`} type="text" maxLength={500} value={pasteTitle} disabled={locked} onChange={event => setPasteTitle(event.target.value)} />
          </div>
          <div className="field">
            <label htmlFor={`${ids}-paste-text`}>Text</label>
            <textarea id={`${ids}-paste-text`} rows={8} value={pasteText} disabled={locked} onChange={event => setPasteText(event.target.value)} />
          </div>
          <button type="button" className="btn btn--light" disabled={locked || full || !pasteText.trim()} onClick={addPasted}>Add the pasted text</button>
        </div>
      </details>

      <h3>Sources in this analysis</h3>
      {sources.length ? (
        <ul className={styles.list}>
          {sources.map(source => (
            <li key={source.id} className={styles.item}>
              <div className={styles.between}>
                <div style={{ minWidth: 0 }}>
                  <p className="m-0 font-bold" style={{ overflowWrap: "anywhere" }}>{source.title}</p>
                  <p className={`${styles.muted} m-0`}>{ORIGIN_LABELS[source.origin]} · about {wordCount(source.text).toLocaleString("en-US")} words{source.url ? <> · <SourceLink href={source.url}>Link</SourceLink></> : null}</p>
                </div>
                <button type="button" className={`${styles.linkButton} ${styles.danger}`} disabled={locked} aria-label={`Remove ${source.title}`} onClick={() => { onSources(sources.filter(item => item.id !== source.id)); onNotice(`Removed "${source.title}".`); }}>Remove</button>
              </div>
              {source.note ? <p className={`${styles.small} m-0 mt-1`}>{source.note}</p> : null}
              <details className="mt-1">
                <summary className={styles.small}>Show the text</summary>
                <p className={`${styles.pre} ${styles.small} mt-1 mb-0`} style={{ maxHeight: "16rem", overflowY: "auto" }}>{source.text.slice(0, 6_000)}{source.text.length > 6_000 ? "…" : ""}</p>
              </details>
            </li>
          ))}
        </ul>
      ) : <p className={styles.muted}>No sources yet. Without the policy text, the analysis can only work from the catalog summary.</p>}
      <p className={`${styles.muted} mt-2`}>{sources.length} of {POLICY_LIMITS.sources} sources.</p>

      <div className="field mt-4">
        <label htmlFor={`${ids}-context`}>What you want to know</label>
        <p className="help m-0" id={`${ids}-context-help`}>For example: who could be left out by the new assessment timeline, and what would make the notices easier to understand.</p>
        <textarea id={`${ids}-context`} rows={4} maxLength={POLICY_LIMITS.contextCharacters} aria-describedby={`${ids}-context-help`} value={context} disabled={disabled} onChange={event => onContext(event.target.value)} />
      </div>
      <div className="field">
        <label htmlFor={`${ids}-title-input`}>Name of this analysis</label>
        <input id={`${ids}-title-input`} type="text" maxLength={240} value={title} disabled={disabled} onChange={event => onTitle(event.target.value)} required />
      </div>
      {children}
    </section>
  );
}

"use client";

import Image from "next/image";
import { useState } from "react";
import styles from "./policy-presentation-reader.module.css";

export type PolicySlide = { number: number; title: string; text: string[]; image: string };

export function PolicyPresentationReader({ slides }: { slides: PolicySlide[] }) {
  const [index, setIndex] = useState(0);
  const slide = slides[index];
  if (!slide) return <p>The presentation is available through the downloads above.</p>;
  const previous = () => setIndex(value => Math.max(0, value - 1));
  const next = () => setIndex(value => Math.min(slides.length - 1, value + 1));
  return <section className={styles.reader} aria-label="Policy review presentation">
    <div className={styles.controls}>
      <button type="button" onClick={previous} disabled={index === 0}>Previous</button>
      <label>Choose a slide<select value={index} onChange={event => setIndex(Number(event.target.value))}>{slides.map((item, position) => <option value={position} key={item.number}>{item.number}. {item.title}</option>)}</select></label>
      <button type="button" onClick={next} disabled={index === slides.length - 1}>Next</button>
    </div>
    <p role="status" className={styles.position}>Slide {index + 1} of {slides.length}</p>
    <h2>{slide.title}</h2>
    <div className={styles.frame} role="group" tabIndex={0} aria-label={`Slide ${index + 1}. Use the left and right arrow keys to move between slides. Home goes to the first slide; End goes to the last.`} onKeyDown={event => {
      if (event.key === "ArrowLeft") { event.preventDefault(); previous(); }
      if (event.key === "ArrowRight") { event.preventDefault(); next(); }
      if (event.key === "Home") { event.preventDefault(); setIndex(0); }
      if (event.key === "End") { event.preventDefault(); setIndex(slides.length - 1); }
    }}><Image src={slide.image} alt={`Slide ${index + 1}: ${slide.title}. The slide text is available below.`} width={1600} height={900} unoptimized className={styles.image} /></div>
    <details className={styles.transcript} key={slide.number}><summary>Read slide {index + 1} text</summary><div>{slide.text.map((paragraph, paragraphIndex) => <p key={paragraphIndex}>{paragraph}</p>)}</div></details>
  </section>;
}

