  const [busy,setBusy]=useState(false),[message,setMessage]=useState(""),[defineMeasure,setDefineMeasure]=useState(false);
  async function save(event:FormEvent<HTMLFormElement>) {
    event.preventDefault();const form=event.currentTarget,data=new FormData(form);
    if(Boolean(String(data.get("referenceLabel")??"").trim())!==Boolean(String(data.get("referenceHref")??"").trim())) {setMessage("Add both a source title and address, or leave both empty. Your writing is still here.");return;}
    setBusy(true);setMessage("");requestId.current??=crypto.randomUUID();
    try {
      const response=await fetch("/api/consultant/program",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"prepare_manual",requestId:requestId.current,taskId:task.id,expectedEventId:task.lastEventId,body:data.get("body"),note:data.get("note"),references:String(data.get("referenceHref")??"").trim()?[{label:data.get("referenceLabel"),href:data.get("referenceHref")}]:[],preparationPlan:{reviewNeeds:data.get("reviewNeeds"),measure:data.get("measure"),reportBack:data.get("reportBack"),...(defineMeasure?{measureDefinition:Object.fromEntries(measureDefinitionFields.map(field=>[field.id,data.get("measure_"+field.id)]))}:{})}})});
      const result=await response.json();if(!response.ok){if(response.status===409)throw new Error("This work changed since you opened it. Your writing is still here. Copy it before refreshing to review the latest record.");throw new Error(result.error??"The preparation could not be confirmed.");}
      setMessage("Preparation recorded. It remains a draft contribution, not an approved decision.");requestId.current=null;form.reset();router.refresh();
    }catch(error){setMessage(error instanceof Error?error.message:"The preparation could not be confirmed. Your writing is still here.");}finally{setBusy(false);}
  }
  return <details className="mt-5"><summary className="cursor-pointer font-semibold">Record your prepared analysis or recommendation</summary><form className="mt-4 grid gap-3" onSubmit={save} onChange={()=>{requestId.current=null;}}><fieldset disabled={busy} className="contents"><p>Use general program information. Keep client, case, health, personnel and confidential records out of this workspace.</p>{task.goalActionIds?.length? <p>Selected ADSA connections: {task.goalActionIds.map(id=><SourceLink key={id} className="mr-3 underline" href={"/program/implementation#"+id}>{id}: {adsaWorkAction(id)?.sourceText}</SourceLink>)}. This preparation is a draft contribution; delivery, implementation and observed benefit are recorded separately.</p>:null}<label>Prepared contribution<textarea className="input block w-full" name="body" rows={10} minLength={20} maxLength={18000} required placeholder="Question and scope; relevant sources; affected people and missing perspectives; options and tradeoffs; recommendation; uncertainty and the evidence still needed."/></label><fieldset className="grid gap-3"><legend>Connect a source or program resource, if useful</legend><p>Use a public source or a page in this program. Keep restricted links and sign-in details out. In your review note, explain the source&apos;s date, scope and any uncertainty; adding a link does not establish authority.</p><label>Source or resource title<input className="input block w-full" name="referenceLabel" minLength={2} maxLength={240}/></label><label>Public HTTPS address or program path<input className="input block w-full" name="referenceHref" maxLength={1500} placeholder="/learn/equity-toolkit"/></label></fieldset><label>Review note and source limitations<textarea className="input block w-full" name="note" rows={3} minLength={10} maxLength={3000} required/></label><label>Reviews needed before a decision<textarea className="input block w-full" name="reviewNeeds" minLength={10} maxLength={1500} required placeholder="Identify relevant policy, legal, fiscal, accessibility or community engagement needs; explain any not needed or still unknown."/></label><label>How will you check whether the change helped?<textarea className="input block w-full" name="measure" minLength={10} maxLength={1500} required placeholder="Proposed measure, evidence source, comparison and remaining uncertainty."/></label><details><summary className="cursor-pointer font-semibold">Keep a proposed measure definition with this work</summary><p className="mt-3">When this work needs a repeatable measure, save its definition with the preparation. The program assigns a stable identity and a new version when you revise it. It remains proposed; actual agency review, data permissions and targets are not established here.</p><label className="mt-3 block"><input type="checkbox" checked={defineMeasure} onChange={event=>setDefineMeasure(event.target.checked)}/> Include a measure definition</label>{defineMeasure&&<div className="mt-3 grid gap-3">{measureDefinitionFields.map(field=><label key={field.id}>{field.label}<textarea className="input block w-full" name={"measure_"+field.id} required minLength={field.minimum} maxLength={field.maximum} rows={2}/><span className="block text-sm text-muted">{field.help}</span></label>)}</div>}</details><label>Who should receive the findings and next update?<textarea className="input block w-full" name="reportBack" minLength={5} maxLength={1000} required/></label><button className="btn" disabled={busy}>{busy?"Saving…":"Record preparation"}</button><p role="status">{message}</p></fieldset></form></details>;
