"use client";
import { useRef, useState } from "react";
import { emptyCrosswalk, emptyRequirement, readRequirementsCrosswalk, requirementsSummary, REQUIREMENT_FIELDS, REQUIREMENT_STATUSES, type RequirementEntry, type RequirementsCrosswalk } from "@/lib/content/requirements-crosswalk";

export function RequirementsCrosswalkWorksheet() {
  const [work, setWork] = useState<RequirementsCrosswalk>(emptyCrosswalk);
  const [notice, setNotice] = useState("");
  const [fallback, setFallback] = useState<"text" | "json" | null>(null);
  const [pending, setPending] = useState<RequirementsCrosswalk | null>(null);
  const entryRefs = useRef<Record<string, HTMLTextAreaElement | null>>({});
  const text = requirementsSummary(work);
  function update(id: string, changes: Partial<RequirementEntry>) { setWork(current => ({ ...current, entries: current.entries.map(entry => entry.id === id ? { ...entry, ...changes } : entry) })); }
  function add() {
    if (work.entries.length >= 20) return;
    let number = work.entries.length + 1;
    while (work.entries.some(entry => entry.id === `R${number}`)) number++;
    const id = `R${number}`;
    setWork(current => ({ ...current, entries: [...current.entries, emptyRequirement(id)] }));
    setNotice("A new requirement entry is ready.");
    requestAnimationFrame(() => entryRefs.current[id]?.focus());
  }
  async function openFile(file?: File) {
    if (!file) return;
    try {
      if (file.size > 600_000) throw new Error("This working file is too large.");
      const candidate = readRequirementsCrosswalk(await file.text());
      setPending(candidate); setNotice("The file is ready to open. Keep a copy of your current notes before replacing them.");
    } catch (error) { setPending(null); setNotice(error instanceof Error ? error.message : "The file could not be opened. Your current notes are unchanged."); }
  }
  function download(kind: "text" | "json") {
    let url: string | undefined;
    try {
      url = URL.createObjectURL(new Blob([kind === "text" ? text : JSON.stringify(work, null, 2)], { type: kind === "text" ? "text/plain;charset=utf-8" : "application/json" }));
      const anchor = document.createElement("a"); anchor.href = url; anchor.download = kind === "text" ? "one-dhs-requirements-review.txt" : "one-dhs-requirements-working-file.json"; document.body.appendChild(anchor); anchor.click(); anchor.remove();
      setNotice(kind === "text" ? "Your review summary is ready to download. Check the saved file before sharing." : "Your editable working file is ready to download. Open it here later to continue."); setFallback(null);
    } catch { setFallback(kind); setNotice("The download could not start. Your complete file is shown below to copy and save manually."); }
    finally { if (url) { const created = url; setTimeout(() => URL.revokeObjectURL(created), 1000); } }
  }
  return <section className="space-y-6" aria-labelledby="requirements-working-title">
    <h2 id="requirements-working-title" className="text-2xl font-semibold">Connect each requirement with its evidence</h2>
    <p id="requirements-privacy" className="notice">Your entries stay on this page while it is open. They are not saved in the browser or submitted. Download a working file before leaving or reloading. Use general descriptions, roles and references; keep confidential case, health and personnel information in approved systems. Downloaded files remain on your device until you remove them.</p>
    <details><summary className="cursor-pointer font-semibold">Continue from a saved working file</summary><label className="mt-3 block">Choose your requirements working file<input className="mt-2 block" type="file" accept=".json,application/json" onChange={event => { void openFile(event.target.files?.[0]); event.target.value = ""; }}/></label>{pending && <div className="notice mt-3"><p>Ready to open: {pending.title || "Untitled work"}, revision {pending.revision}, {pending.entries.length} entries. Opening replaces the notes currently on this page.</p><div className="mt-3 flex flex-wrap gap-3"><button type="button" className="btn" onClick={() => { setWork(pending); setPending(null); setFallback(null); setNotice("Working file opened. Changes are not saved until you download again."); }}>Replace current notes with this file</button><button type="button" className="btn btn--light" onClick={() => { setPending(null); setNotice("Current notes kept."); }}>Keep current notes</button></div></div>}</details>
    <label className="block font-semibold">Name of the work<input className="mt-2 block w-full rounded-lg border border-line p-3 font-normal" maxLength={300} value={work.title} onChange={event => setWork(current => ({ ...current, title: event.target.value }))}/></label>
    <label className="block font-semibold">Working revision<input className="mt-2 block w-full rounded-lg border border-line p-3 font-normal" maxLength={80} value={work.revision} onChange={event => setWork(current => ({ ...current, revision: event.target.value }))}/></label>
    {work.entries.map((entry, index) => <fieldset key={entry.id} className="rounded-xl border border-line p-5 space-y-5"><legend className="px-2 text-xl font-semibold">Requirement {index + 1}</legend>{REQUIREMENT_FIELDS.map(field => <div key={field.id}><label className="block font-semibold" htmlFor={`${entry.id}-${field.id}`}>{field.label}</label><p id={`${entry.id}-${field.id}-help`} className="my-2 text-muted">{field.help}</p><textarea ref={field.id === "requirement" ? element => { entryRefs.current[entry.id] = element; } : undefined} id={`${entry.id}-${field.id}`} aria-describedby={`${entry.id}-${field.id}-help requirements-privacy`} className="w-full rounded-lg border border-line p-3" rows={3} maxLength={4000} value={entry[field.id]} onChange={event => update(entry.id, { [field.id]: event.target.value })}/></div>)}<label className="block font-semibold">Current review position<select className="mt-2 block w-full rounded-lg border border-line p-3 font-normal" value={entry.status} onChange={event => update(entry.id, { status: event.target.value as RequirementEntry["status"] })}>{REQUIREMENT_STATUSES.map(status => <option key={status}>{status}</option>)}</select></label><p className="text-sm text-muted">This records the preparer&apos;s account. It does not establish compliance or verify a review. If work or sources change, revisit the affected requirement and update its position.</p></fieldset>)}
    <div className="flex flex-wrap gap-3"><button type="button" className="btn btn--light" onClick={add} disabled={work.entries.length >= 20}>Add another requirement</button><button type="button" className="btn btn--primary" onClick={() => download("json")}>Save editable working file</button><button type="button" className="btn btn--light" onClick={() => download("text")}>Download review summary</button></div>
    <p role="status" aria-live="polite">{notice}</p>
    {fallback && <label className="block font-semibold">Complete {fallback === "json" ? "working file" : "review summary"}<textarea className="mt-2 w-full rounded-lg border border-line p-3 font-normal" rows={16} readOnly value={fallback === "json" ? JSON.stringify(work, null, 2) : text} onFocus={event => event.target.select()}/></label>}
  </section>;
}

"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import { Field, Notice } from "@/components/ui";
import type { ResearchPolicy, ResearchUsageEvent, UsageSummary } from "@/lib/intelligence/research/governance";

type ProviderRow = { id: string; configured: boolean; credential_env: string; models: { current_web: string; deep_research: string } };

const RESEARCH_ERRORS: Record<string, string> = {
  research_not_configured: "the research connection was not ready",
  research_disabled: "research was turned off",
  research_stop: "research was paused",
  daily_cap_reached: "the daily limit was reached",
  monthly_cap_reached: "the monthly limit was reached",
};

function requestResult(event: ResearchUsageEvent) {
  if (event.ok) return "Completed";
  const reason = event.error_code ? RESEARCH_ERRORS[event.error_code] : undefined;
  return reason ? `Not completed: ${reason}` : "Not completed";
}

function requestSetting(event: ResearchUsageEvent) {
  if (event.model === "perplexity-search") return "Public-source search";
  if (event.provider === "fixture") return "Readiness-check sample";
  return event.depth === "deep_research" ? "In-depth research" : "Current answer";
}

export function researchAvailability(policyEnabled: boolean, configured: boolean, paused: boolean) {
  if (paused) {
    return {
      active: false,
      heading: "External research is paused",
      detail: "Research is paused. Questions cannot be sent to an outside research service until the pause is lifted.",
    };
  }
  if (!configured) {
    return {
      active: false,
      heading: "External research is off until the connection is ready",
      detail: "A research service still needs to be connected. No questions are sent out for research.",
    };
  }
  if (!policyEnabled) {
    return {
      active: false,
      heading: "External research is off",
      detail: "A service is connected. Turn external research on to make it available to the program's research tools.",
    };
  }
  return {
    active: true,
    heading: "External research is available",
      detail: "Connected research tools can consult current public sources. Each tool explains what it sends and asks you to confirm when required.",
  };
}

export function ResearchControlsClient({ policy, summary, usage, providers, researchStopEnv }: { policy: ResearchPolicy; summary: UsageSummary; usage: ResearchUsageEvent[]; providers: ProviderRow[]; researchStopEnv: boolean }) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");
  const [daily, setDaily] = useState(String(policy.daily_request_cap));
  const [monthly, setMonthly] = useState(String(policy.monthly_usd_cap));
  const [domains, setDomains] = useState(policy.allowed_domains.join("\n"));
  const anyConfigured = providers.some((p) => p.configured && p.id !== "fixture");
  const availability = researchAvailability(policy.enabled, anyConfigured, researchStopEnv);

  async function post(body: Record<string, unknown>, label: string) {
    setBusy(true);
    setMsg("");
    try {
      const res = await fetch("/api/consultant/research", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
      const data = await res.json();
      if (!res.ok) {
        const reason = typeof data.error === "string" ? RESEARCH_ERRORS[data.error] : undefined;
        setMsg(reason ? `That change could not be completed because ${reason}.` : "That change could not be saved. Please try again.");
      }
      else {
        setMsg(`${label}.`);
        router.refresh();
      }
    } catch {
      setMsg("That change could not be saved. Please try again.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="space-y-8">
      <section className={`card ${!availability.active ? "notice--warn" : ""}`} aria-labelledby="rs-ctl">
        <p className="kicker">Availability</p>
        <h2 id="rs-ctl" className="text-2xl font-extrabold">
          {availability.heading}
        </h2>
        <p className="text-sm text-muted">{availability.detail}</p>
        <div className="mt-3 flex flex-wrap gap-3">
          {policy.enabled ? (
            <button type="button" className="btn btn--primary" style={{ background: "var(--red-strong)", borderColor: "var(--red-strong)" }} disabled={busy} onClick={() => post({ enabled: false }, "External research turned off")}>
              Turn external research off
            </button>
          ) : (
            <button type="button" className="btn btn--secondary" disabled={busy || !anyConfigured || researchStopEnv} onClick={() => post({ enabled: true }, "External research turned on")}>
              Turn external research on
            </button>
          )}
          <button type="button" className="btn btn--light" disabled={busy || !anyConfigured || researchStopEnv} onClick={() => post({ deep_research_enabled: !policy.deep_research_enabled }, policy.deep_research_enabled ? "In-depth research turned off" : "In-depth research allowed")}>
            {policy.deep_research_enabled ? "Turn in-depth research off" : "Allow in-depth research"}
          </button>
        </div>
        {msg ? (
          <p className="mt-2 text-sm" role="status">
            {msg}
          </p>
        ) : null}
      </section>

      <section className="grid gap-4 md:grid-cols-2" aria-labelledby="rs-usage">
        <div className="panel">
          <p className="kicker">Usage</p>
          <h2 id="rs-usage" className="text-xl font-extrabold">
            Today and this month
          </h2>
          <table className="data mt-2">
            <thead>
              <tr>
                <th scope="col">Period</th>
                <th scope="col">Requests</th>
                <th scope="col">Cost (USD)</th>
                <th scope="col">Limit</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <th scope="row">Today</th>
                <td>{summary.today.requests}</td>
                <td>{summary.today.usd.toFixed(4)}</td>
                <td>{summary.caps.daily_request_cap > 0 ? `${summary.caps.daily_request_cap} requests` : "No limit set"}</td>
              </tr>
              <tr>
                <th scope="row">This month</th>
                <td>{summary.month.requests}</td>
                <td>{summary.month.usd.toFixed(4)}</td>
                <td>{summary.caps.monthly_usd_cap > 0 ? `$${summary.caps.monthly_usd_cap}` : "No limit set"}</td>
              </tr>
            </tbody>
          </table>
          <p className="mt-2 text-sm text-muted">Costs use the amount reported by the research service when available. Otherwise, the program shows an estimate. The question itself is not stored in this record.</p>
        </div>
        <div className="panel">
          <p className="kicker">Sources for program questions</p>
          <h2 className="text-xl font-extrabold">Three research paths</h2>
          <dl className="mt-2 grid gap-x-4 gap-y-2 sm:grid-cols-[max-content_1fr]">
            <dt className="font-bold">Program library</dt>
            <dd className="m-0">Browse published resources and see their review status.</dd>
            <dt className="font-bold">Current public sources</dt>
            <dd className="m-0">{availability.active ? "Available to connected research tools." : "Not available right now."}</dd>
            <dt className="font-bold">In-depth research</dt>
            <dd className="m-0">{availability.active && policy.deep_research_enabled ? "Available when a question needs a fuller review." : "Not available right now."}</dd>
          </dl>
        </div>
      </section>

      <details className="card">
        <summary>Research services and setup help</summary>
        <p className="mt-3 text-sm">These services support public searches and more detailed research. Private connection keys are managed in the secure hosting settings for the program.</p>
        <table className="data mt-2">
          <thead>
            <tr>
              <th scope="col">Order</th>
              <th scope="col">Service</th>
              <th scope="col">Connection key</th>
              <th scope="col">Current / in-depth settings</th>
            </tr>
          </thead>
          <tbody>
            {policy.provider_order.map((id, index) => {
              const provider = providers.find((item) => item.id === id);
              return (
                <tr key={id}>
                  <td>{index + 1}</td>
                  <td>{id === "perplexity_agent" ? "Public research service" : id === "openai_web" ? "Public web search through the second answer service" : "Sample used for checks"}</td>
                  <td>{provider?.configured ? "Added" : provider?.credential_env ? "Not added" : "Not needed"}</td>
                  <td className="text-xs">{id !== "fixture" ? `${provider?.models.current_web ?? "low"} / ${provider?.models.deep_research ?? "medium"}` : "Readiness checks only"}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
        {!anyConfigured ? <p className="notice notice--warn mt-3 text-sm">Add a private connection key in the secure hosting settings for the research service before turning on research. This page never displays or saves the key.</p> : null}
