import { SourceLink } from "@/components/app-link";
import { Fragment, type ReactNode } from "react";
import { parseResearchMarkdown, type ResearchBlock } from "@/lib/content/research-markdown";
import { PrivateNotes } from "./private-notes";
import "./research-markdown.css";

const INLINE = /\[([^\]]+)\]\(((?:https?:\/\/|\/)[^)\s]+)\)|\*\*(.+?)\*\*|(?<![\w*])\*(?!\s)(.+?)(?<!\s)\*(?![\w*])|(https?:\/\/[^\s<]*[^\s<.,;:)])/g;

export function ResearchInline({ text }: { text: string }): ReactNode {
  const parts: ReactNode[] = [];
  let last = 0;
  for (const match of text.matchAll(INLINE)) {
    if (match.index > last) parts.push(text.slice(last, match.index));
    const key = match.index;
    if (match[1]) parts.push(<SourceLink key={key} href={match[2]}><ResearchInline text={match[1]} /></SourceLink>);
    else if (match[3]) parts.push(<strong key={key}><ResearchInline text={match[3]} /></strong>);
    else if (match[4]) parts.push(<em key={key}><ResearchInline text={match[4]} /></em>);
    else if (match[5]) parts.push(<SourceLink key={key} href={match[5]}>{match[5]}</SourceLink>);
    last = match.index + match[0].length;
  }
  if (last < text.length) parts.push(text.slice(last));
  return <>{parts.map((part, index) => <Fragment key={index}>{part}</Fragment>)}</>;
}

function Block({ block, notesKey }: { block: ResearchBlock; notesKey?: string }) {
  switch (block.type) {
    case "heading": {
      const Heading = block.level === 4 ? "h4" : "h3";
      return <Heading><ResearchInline text={block.text} /></Heading>;
    }
    case "paragraph": return <p><ResearchInline text={block.text} /></p>;
    case "list": {
      const List = block.ordered ? "ol" : "ul";
      return <List>{block.items.map((item, index) => <li key={index}><ResearchInline text={item} /></li>)}</List>;
    }
    case "table": return <div className="community-table" role="region" aria-label="Table" tabIndex={0}><table>
      <thead><tr>{block.header.map((cell, index) => <th key={index} scope="col"><ResearchInline text={cell} /></th>)}</tr></thead>
      <tbody>{block.rows.map((row, rowIndex) => <tr key={rowIndex}>{row.map((cell, index) => <td key={index}><ResearchInline text={cell} /></td>)}</tr>)}</tbody>
    </table></div>;
    case "note": return <aside className="research-note" role="note"><strong>Content note.</strong> <ResearchInline text={block.text} /></aside>;
    case "voice": return <blockquote className="research-voice"><ResearchBlocks blocks={block.blocks} /></blockquote>;
    case "fact": return <aside className="research-fact"><ResearchBlocks blocks={block.blocks} /></aside>;
    case "takeaway": return <aside className="research-takeaway"><p className="research-label">Practice this week</p><ResearchBlocks blocks={block.blocks} /></aside>;
    case "reflect": return <section className="research-reflect" aria-label="Reflection">
      <p className="research-label">For your own reflection. Nothing here is collected.</p>
      <ol>{block.items.map((item, index) => <li key={index}><ResearchInline text={item} /></li>)}</ol>
      {notesKey ? <PrivateNotes storageKey={notesKey} /> : null}
    </section>;
    case "scenario": return <section className="research-scenario" aria-label="Practice scenario">
      {block.label ? <p className="research-label"><ResearchInline text={block.label} /></p> : null}
      <ResearchBlocks blocks={block.blocks} />
      <p className="research-scenario-question"><ResearchInline text={block.question} /></p>
      {block.options.map((option, index) => <details key={index} className="research-scenario-option">
        <summary><ResearchInline text={option.choice} /></summary>
        <p><ResearchInline text={option.feedback} /></p>
      </details>)}
      <p className="research-scenario-hint">Open any answer to see what it might lead to. You can open all of them.</p>
    </section>;
  }
}

export function ResearchBlocks({ blocks, notesKey }: { blocks: ResearchBlock[]; notesKey?: string }) {
  return <>{blocks.map((block, index) => <Block key={index} block={block} notesKey={notesKey} />)}</>;
}

export function ResearchMarkdown({ markdown, notesKey }: { markdown: string; notesKey?: string }) {
  return <ResearchBlocks blocks={parseResearchMarkdown(markdown)} notesKey={notesKey} />;
}

"use client";

import Link from "@/components/app-link";
import { useCallback, useEffect, useRef, useState, type FormEvent } from "react";
import { localStudyHref } from "@/lib/client/resource-study-links";
import { resourceArtifactKinds, type ArtifactResourceLink, type ArtifactResourceSearch, type ResourceArtifact, type ResourceArtifactKind } from "@/lib/learning/resource-artifact-types";
import { ResourceCreationMedia, ResourceCreationPreview, type ResourceCreationFile } from "./resource-creation-preview";

type JobStatus = "queued" | "generating" | "rendering" | "ready" | "failed" | "stale";
type CreationJob = {
  id: string;
  resourcePath: string;
  title: string;
  kind: ResourceArtifactKind;
  status: JobStatus;
  createdAt: string;
  updatedAt: string;
  error?: string;
  artifact?: ResourceArtifact;
  files?: ResourceCreationFile[];
};

const endpoint = "/api/consultant/resource-creation";
const statusText: Record<JobStatus, string> = {
  queued: "Queued",
  generating: "Preparing the draft",
  rendering: "Rendering media",
  ready: "Ready to review",
  failed: "Could not finish",
  stale: "Source changed",
};
const formatHelp: Record<ResourceArtifactKind, string> = {
  "study-guide": "Key ideas and practice suggestions with citations.",
  quiz: "Questions, answers and explanations.",
  flashcards: "Practice cards with a question on one side and an answer on the other.",
  "mind-map": "A main topic and connected ideas arranged in branches.",
  slides: "An editable PowerPoint with slide content, speaker notes and citations.",
  infographic: "A visual draft with labeled sections, source links and an HTML download.",
  "audio-overview": "A short discussion between two hosts, with a transcript.",
  "video-overview": "A narrated video with captions and a transcript.",
};
const formats = Object.entries(resourceArtifactKinds) as [ResourceArtifactKind, string][];

async function jsonResponse<T>(response: Response): Promise<T> {
  const data = await response.json().catch(() => null);
  if (response.status === 401 || response.status === 403) {
    throw new Error("Sign in to the Consultant Workspace again to continue.");
  }
  if (!response.ok || !data) {
    throw new Error(typeof data?.error === "string" ? data.error : "The request could not be completed. Please try again.");
  }
  return data as T;
}

function sourceFromInput(value: string) {
  const text = value.trim();
  if (!text.startsWith("/") && !/^https?:\/\//i.test(text)) return "";
  try {
    const url = new URL(text, window.location.origin);
    const path = url.pathname + url.search;
    return url.origin === window.location.origin && localStudyHref(path) ? path : "";
  } catch {
    return "";
  }
}

function activeJob(job: CreationJob) {
  return job.status === "queued" || job.status === "generating" || job.status === "rendering";
}

function formatDate(value: string) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "" : new Intl.DateTimeFormat(undefined, {
    dateStyle: "medium", timeStyle: "short",
  }).format(date);
}

async function loadCatalog(query: string, offset: number, signal: AbortSignal) {
  const params = new URLSearchParams({ search: query, offset: String(offset) });
  return jsonResponse<ArtifactResourceSearch>(await fetch(`${endpoint}?${params}`, { cache: "no-store", signal }));
}

export function ResourceCreationPanel({ resourcePath, resourceTitle }: { resourcePath: string; resourceTitle?: string }) {
  const [source, setSource] = useState<ArtifactResourceLink | null>(() =>
    resourcePath && resourceTitle ? { resourcePath, title: resourceTitle } : null);
  const [pathInput, setPathInput] = useState(resourcePath);
  const [kind, setKind] = useState<ResourceArtifactKind>("study-guide");
  const [search, setSearch] = useState("");
  const [results, setResults] = useState<ArtifactResourceSearch | null>(null);
  const [searching, setSearching] = useState(true);
  const [searchError, setSearchError] = useState("");
  const searchRequest = useRef<AbortController | null>(null);
  const currentSearch = useRef("");
  const [jobs, setJobs] = useState<CreationJob[]>([]);
  const [selectedId, setSelectedId] = useState("");
  const [loadingJobs, setLoadingJobs] = useState(true);
  const [jobsError, setJobsError] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [creationError, setCreationError] = useState("");
  const [notice, setNotice] = useState("");
  const submitLock = useRef(false);
  const jobsSequence = useRef(0);

  const searchResources = useCallback(async (query: string, offset = 0) => {
    searchRequest.current?.abort();
    const controller = new AbortController();
    searchRequest.current = controller;
    currentSearch.current = query;
    setSearching(true);
    setSearchError("");
    try {
      const data = await loadCatalog(query, offset, controller.signal);
      if (!controller.signal.aborted) {
        setResults(current => offset && current
          ? { ...data, resources: [...new Map([...current.resources, ...data.resources].map(item => [item.resourcePath, item])).values()] }
          : data);
      }
    } catch (error) {
      if (!controller.signal.aborted) setSearchError(error instanceof Error ? error.message : "Resources could not be loaded.");
    } finally {
      if (searchRequest.current === controller && !controller.signal.aborted) setSearching(false);
    }
  }, []);

  const refreshJobs = useCallback((signal?: AbortSignal) => {
    const sequence = ++jobsSequence.current;
    return fetch(endpoint, { cache: "no-store", signal })
      .then(response => jsonResponse<{ jobs: CreationJob[] }>(response))
      .then(({ jobs }) => {
        if (!signal?.aborted && sequence === jobsSequence.current) {
          setJobs(jobs);
          setSelectedId(current => jobs.some(job => job.id === current) ? current : jobs[0]?.id ?? "");
          setJobsError("");
        }
      })
      .catch(error => {
        if (!signal?.aborted && sequence === jobsSequence.current) setJobsError(error instanceof Error ? error.message : "Drafts could not be loaded.");
      })
      .finally(() => {
        if (!signal?.aborted && sequence === jobsSequence.current) setLoadingJobs(false);
      });
  }, []);

  useEffect(() => {
    const controller = new AbortController();
    const catalog = new AbortController();
    searchRequest.current = catalog;
    void loadCatalog("", 0, catalog.signal).then(data => {
      if (!catalog.signal.aborted) setResults(data);
    }).catch(error => {
      if (!catalog.signal.aborted) setSearchError(error instanceof Error ? error.message : "Resources could not be loaded.");
    }).finally(() => {
      if (!catalog.signal.aborted) setSearching(false);
    });
    void refreshJobs(controller.signal);
    return () => {
      controller.abort();
      searchRequest.current?.abort();
    };
  }, [refreshJobs]);

  const working = jobs.some(activeJob);
  useEffect(() => {
    if (!working || submitting) return;
    const controller = new AbortController();
    let updating = false;
    const timer = window.setInterval(async () => {
      if (updating) return;
      updating = true;
      try { await refreshJobs(controller.signal); } finally { updating = false; }
    }, 5000);
    return () => {
      window.clearInterval(timer);
      controller.abort();
    };
  }, [working, submitting, refreshJobs]);

  function selectResource(resource: ArtifactResourceLink) {
    setSource(resource);
    setPathInput(resource.resourcePath);
    setCreationError("");
  }

  async function create(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submitLock.current) return;
    setCreationError("");
    setNotice("");
    const sourcePath = sourceFromInput(pathInput);
    if (!sourcePath) {
      setCreationError("Choose a published resource or paste a link from this application.");
      return;
    }
    submitLock.current = true;
    ++jobsSequence.current;
    setSubmitting(true);
    try {
      const response = await fetch(endpoint, {
        method: "POST", headers: { "content-type": "application/json" },
        body: JSON.stringify({ resourcePath: sourcePath, kind }),
      });
      const { job } = await jsonResponse<{ job: CreationJob }>(response);
      setJobs(current => [job, ...current.filter(item => item.id !== job.id)]);
      setSelectedId(job.id);
      setNotice(job.status === "ready" ? "Your draft is ready to review." : "Draft creation started. Its status will update here.");
    } catch (error) {
      setCreationError(error instanceof TypeError
        ? "The connection ended before the request was confirmed. Check Recent drafts before starting another draft."
        : error instanceof Error ? error.message : "Draft creation could not start.");
      void refreshJobs();
    } finally {
      setSubmitting(false);
      setLoadingJobs(false);
      submitLock.current = false;
    }
  }

  const selected = jobs.find(job => job.id === selectedId);
  return <div className="wrap grid items-start gap-6 py-8 lg:grid-cols-2">
    <section className="card min-w-0 space-y-5" aria-labelledby="creation-source-heading">
      <h2 id="creation-source-heading" className="text-xl font-bold">Choose a resource</h2>
      <form onSubmit={event => { event.preventDefault(); void searchResources(search.trim()); }}>
        <label htmlFor="creation-search" className="block font-semibold">Search published resources</label>
        <div className="mt-2 flex flex-wrap items-end gap-2">
          <input id="creation-search" className="min-h-11 min-w-0 flex-1 rounded border border-line px-3" type="search" value={search} maxLength={150} onChange={event => setSearch(event.target.value)} />
          <button type="submit" className="btn min-h-11">Search</button>
        </div>
      </form>
      <p className="text-sm" role="status">{searchError || (searching ? "Finding resources…" : results?.total ? `${results.total} resources found` : "No matching resources.")}</p>
      {results?.resources.length ? <ul className="max-h-96 divide-y divide-line overflow-y-auto border-y border-line">
        {results.resources.map(item => <li key={item.resourcePath} className="space-y-1 py-2">
          <button type="button" className="min-h-11 text-left font-semibold underline underline-offset-4"
            aria-pressed={source?.resourcePath === item.resourcePath}
            onClick={() => selectResource(item)}>{item.title}</button>
          <p className="text-sm text-muted">{item.type.replace(/[-_]/g, " ")}</p>
          {item.related?.length ? <details className="text-sm">
            <summary className="min-h-11 cursor-pointer py-2">{item.relatedCount} related {item.relatedCount === 1 ? "resource" : "resources"}</summary>
            <ul className="list-disc space-y-1 pl-5">
              {item.related.map(related => <li key={related.resourcePath}>
                <button type="button" className="min-h-11 text-left underline" onClick={() => selectResource(related)}>{related.title}</button>
              </li>)}
            </ul>
          </details> : null}
        </li>)}
      </ul> : null}
      {results?.nextOffset !== undefined ? <button type="button" className="btn min-h-11"
        disabled={searching} onClick={() => void searchResources(currentSearch.current, results.nextOffset)}>Show more resources</button> : null}
      <form onSubmit={create} className="space-y-4 border-t border-line pt-4">
        {source ? <p><span className="font-semibold">Selected resource:</span> {source.title}</p> : null}
        <div>
          <label htmlFor="creation-path" className="block font-semibold">Resource link</label>
          <input id="creation-path" className="mt-2 min-h-11 w-full rounded border border-line px-3" value={pathInput}
            onChange={event => { setPathInput(event.target.value); setSource(null); }} maxLength={1000}
            placeholder="/library/ja-language-access-checklist" required />
        </div>
        <div>
          <label htmlFor="creation-format" className="block font-semibold">Draft format</label>
          <select id="creation-format" className="mt-2 min-h-11 w-full rounded border border-line px-3" value={kind}
            onChange={event => setKind(event.target.value as ResourceArtifactKind)} aria-describedby="creation-format-help">
            {formats.map(([value, label]) => <option key={value} value={value}>{label}</option>)}
          </select>
          <p id="creation-format-help" className="mt-2 text-sm text-muted">{formatHelp[kind]}</p>
        </div>
        <button type="submit" className="btn btn--primary min-h-11" disabled={submitting || !pathInput.trim()}>
          {submitting ? "Starting draft…" : "Create draft"}
        </button>
        <p role="status">{creationError || notice}</p>
      </form>
    </section>
    <section className="card min-w-0 space-y-4" aria-labelledby="creation-jobs-heading">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h2 id="creation-jobs-heading" className="text-xl font-bold">Recent drafts</h2>
        <button type="button" className="btn min-h-11" onClick={() => void refreshJobs()}>Refresh</button>
      </div>
      {loadingJobs || jobsError || !jobs.length ? <p role="status">{jobsError || (loadingJobs ? "Loading drafts…" : "Completed and in-progress drafts will appear here.")}</p> : null}
      {jobs.length ? <ul className="max-h-64 divide-y divide-line overflow-y-auto border-y border-line">
        {jobs.map(job => <li key={job.id}>
          <button type="button" className="min-h-11 w-full py-2 text-left" aria-pressed={job.id === selectedId} onClick={() => setSelectedId(job.id)}>
            <span className="block font-semibold underline underline-offset-4">{job.title}</span>
            <span className="block text-sm text-muted">{resourceArtifactKinds[job.kind]} · {statusText[job.status]} · {formatDate(job.createdAt)}</span>
          </button>
        </li>)}
      </ul> : null}
      {selected ? <div>
        <p role="status"><strong>{statusText[selected.status]}.</strong> {selected.error}</p>
        {localStudyHref(selected.resourcePath) ? <Link href={selected.resourcePath} className="text-sm underline underline-offset-4">Open source resource</Link> : null}
        {selected.files?.length ? <ResourceCreationMedia files={selected.files} /> : null}
        {selected.artifact ? <ResourceCreationPreview artifact={selected.artifact} powerPointHref={
          selected.status === "ready" && selected.artifact.kind === "slides"
            ? `/api/consultant/resource-creation/${encodeURIComponent(selected.id)}/file?kind=pptx&download=1` : undefined
        } /> : null}
      </div> : null}
    </section>
  </div>;
}

"use client";
import { SourceLink } from "@/components/app-link";


import { resourceVisualHtml } from "@/lib/client/resource-creation-exports";
import { localStudyHref } from "@/lib/client/resource-study-links";
import type { ResourceArtifact } from "@/lib/learning/resource-artifact-types";

export type ResourceCreationFile = { kind: "audio" | "video" | "captions" | "transcript"; href: string; mime: string };

type PreviewBlock = {
  heading: string;
  text?: string;
  points?: string[];
  detail?: { label: string; text: string };
  sourceIds: string[];
};

function previewBlocks(artifact: ResourceArtifact): PreviewBlock[] {
  switch (artifact.kind) {
    case "study-guide":
      return artifact.sections;
    case "quiz":
      return artifact.sections.map((item, index) => ({
        heading: `${index + 1}. ${item.question}`,
        points: item.options,
        detail: { label: "Show answer and explanation", text: `${item.options[item.correctIndex]}\n\n${item.explanation}` },
        sourceIds: item.sourceIds,
      }));
    case "flashcards":
      return artifact.sections.map(item => ({
        heading: item.front, detail: { label: "Show answer", text: item.back }, sourceIds: item.sourceIds,
      }));
    case "mind-map":
      return artifact.sections.map(item => ({ heading: item.heading, points: item.branches, sourceIds: item.sourceIds }));
    case "slides":
      return artifact.sections.map(item => ({
        heading: item.heading, points: item.points,
        detail: { label: "Speaker notes", text: item.speakerNotes }, sourceIds: item.sourceIds,
      }));
    case "infographic":
      return artifact.sections.map(item => ({
        heading: item.heading, text: item.text,
        detail: { label: "Visual direction", text: item.visualCue }, sourceIds: item.sourceIds,
      }));
    case "audio-overview":
      return artifact.sections.map(item => ({
        heading: item.speaker === "host1" ? "Host 1" : "Host 2", text: item.text, sourceIds: item.sourceIds,
      }));
    case "video-overview":
      return artifact.sections.map(item => ({
        heading: item.heading, text: item.narration, points: item.onScreen,
        detail: { label: "Visual direction", text: item.visualCue }, sourceIds: item.sourceIds,
      }));
  }
}

const fileLabels: Record<ResourceCreationFile["kind"], string> = {
  audio: "Download audio",
  video: "Download video",
  captions: "Download captions",
  transcript: "Download transcript",
};

export function ResourceCreationMedia({ files }: { files: ResourceCreationFile[] }) {
  const usable = files.filter(file => localStudyHref(file.href));
  const audio = usable.find(file => file.kind === "audio");
  const video = usable.find(file => file.kind === "video");
  const captions = usable.find(file => file.kind === "captions");
  if (!usable.length) return null;
  return <section className="mt-4 space-y-3" aria-label="Preview and downloads">
    {audio ? <audio controls preload="none" src={audio.href} aria-label="Two-host audio overview" className="w-full">
      {captions ? <track kind="captions" src={captions.href} srcLang="en" label="English" /> : null}
    </audio> : null}
    {video ? <video controls preload="metadata" src={video.href} aria-label="Narrated video overview" className="aspect-video w-full bg-black">
      {captions ? <track kind="captions" src={captions.href} srcLang="en" label="English" default /> : null}
    </video> : null}
    <ul className="flex flex-wrap gap-x-5 gap-y-2">
      {usable.map(file => <li key={file.href}><SourceLink href={file.href} download className="inline-flex min-h-11 items-center underline underline-offset-4">{fileLabels[file.kind]}</SourceLink></li>)}
    </ul>
  </section>;
}

function markdownText(value: string) {
  return value.replace(/[\\`*_{}[\]<>]/g, "\\$&");
}

function downloadText(content: string, mime: string, fileName: string) {
  const url = URL.createObjectURL(new Blob([content], { type: mime }));
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  link.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export function ResourceCreationPreview({ artifact, powerPointHref }: { artifact: ResourceArtifact; powerPointHref?: string }) {
  const blocks = previewBlocks(artifact);
  const sources = artifact.sources.filter(source => localStudyHref(source.href));
  const numberById = new Map(sources.map((source, index) => [source.id, index + 1]));
  const visual = artifact.kind === "mind-map" || artifact.kind === "infographic";

  function exportHtml() {
    if (artifact.kind === "mind-map" || artifact.kind === "infographic") {
      downloadText(resourceVisualHtml(artifact, window.location.origin), "text/html;charset=utf-8", `${artifact.kind}-draft.html`);
    }
  }

  function exportMarkdown() {
    const content = [
      `# ${markdownText(artifact.title)}`, markdownText(artifact.summary),
      ...blocks.map(block => [
        `## ${markdownText(block.heading)}`,
        block.text ? markdownText(block.text) : "",
        block.points?.map(point => `- ${markdownText(point)}`).join("\n"),
        block.detail ? `**${block.detail.label}**\n\n${markdownText(block.detail.text)}` : "",
        block.sourceIds.map(id => numberById.get(id)).filter(Boolean).map(number => `[${number}]`).join(" "),
      ].filter(Boolean).join("\n\n")),
      "## Sources",
      sources.map((source, index) => `${index + 1}. ${markdownText(source.title)} — ${new URL(source.href, window.location.origin).href}`).join("\n"),
    ].filter(Boolean).join("\n\n");
    downloadText(content, "text/markdown;charset=utf-8", `${artifact.kind}-draft.md`);
  }
  return <article className="mt-5 border-t border-line pt-4">
    <div className="flex flex-wrap items-center justify-between gap-3">
      <h3 className="text-lg font-bold">{artifact.title}</h3>
      <div className="flex flex-wrap gap-2">
        {artifact.kind === "slides" && localStudyHref(powerPointHref)
          ? <SourceLink href={powerPointHref} download className="btn min-h-11">Download editable PowerPoint</SourceLink> : null}
        {visual ? <button type="button" className="btn min-h-11" onClick={exportHtml}>Download visual as HTML</button> : null}
        <button type="button" className="btn min-h-11" onClick={exportMarkdown}>Download draft as Markdown</button>
      </div>
    </div>
    <p className="mt-2 whitespace-pre-wrap">{artifact.summary}</p>
    {artifact.kind === "mind-map" ? <p className="mx-auto mt-4 max-w-fit rounded border border-[#18768a] bg-[#e7f2f5] px-4 py-3 text-center font-bold">{artifact.title}</p> : null}
    <div className={visual ? "mt-4 grid grid-cols-[repeat(auto-fit,minmax(min(100%,13rem),1fr))] gap-3" : "mt-4 space-y-4"}>
      {blocks.map((block, index) => <section key={index} className={visual
        ? "min-w-0 break-words rounded border border-t-4 border-line border-t-[#18768a] bg-[#f4f8fa] p-3"
        : "border-t border-line pt-3"}>
        <h4 className="font-semibold">{block.heading}</h4>
        {block.text ? <p className="mt-2 whitespace-pre-wrap">{block.text}</p> : null}
        {block.points?.length ? <ul className="mt-2 list-disc space-y-1 pl-6">{block.points.map((point, index) => <li key={index}>{point}</li>)}</ul> : null}
        {block.detail ? <details className="mt-2">
          <summary className="min-h-11 cursor-pointer py-2 font-semibold">{block.detail.label}</summary>
          <p className="whitespace-pre-wrap">{block.detail.text}</p>
        </details> : null}
        {block.sourceIds.length ? <p className="mt-2 text-sm">
          {Array.from(new Set(block.sourceIds)).map(id => {
            const number = numberById.get(id);
            return number ? <SourceLink key={id} href={sources[number - 1].href} className="mr-2 underline" aria-label={`Source ${number}: ${sources[number - 1].title}`}>[{number}]</SourceLink> : null;
          })}
        </p> : null}
      </section>)}
    </div>
    {sources.length ? <section className="mt-5 border-t border-line pt-3">
      <h4 className="font-semibold">Sources cited</h4>
      <ol className="mt-2 list-decimal space-y-1 pl-6">{sources.map(source => <li key={source.id}><SourceLink href={source.href} className="underline">{source.title}</SourceLink></li>)}</ol>
    </section> : null}
  </article>;
}

"use client";

import Link from "@/components/app-link";
import { useRouter } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import { Field, Notice } from "@/components/ui";
import {
  EDITABLE_AUTHORITIES,
  EDITABLE_CONTENT_TYPES,
  EDITABLE_INTENTS,
  EDITABLE_LAYERS,
  INTENT_LABELS,
  type EditableResourceFields,
  type EditableResourceState,
} from "@/lib/content/resource-editor-contract";
import { AUTHORITY, CONTENT_TYPE_LABEL, LAYER_LABEL } from "@/lib/content/types";

type PathOption = { id: string; label: string };

type DraftResponse = {
  ok?: boolean;
  draft?: EditableResourceState;
  message?: string;
  error?: string;
};

function bodyText(parts: string[]) {
  return parts.join("\n\n");
}

function bodyParts(value: string) {
  return value
    .split(/\n\s*\n/)
    .map((part) => part.trim())
    .filter(Boolean);
}

function topicText(topics: string[]) {
  return topics.join(", ");
}

function topics(value: string) {
  return Array.from(
    new Set(
      value
        .split(/[\n,]/)
        .map((topic) => topic.trim())
        .filter(Boolean),
    ),
  );
}

export function ResourceInlineEditor({
  initial,
  pathOptions,
  endpoint,
  reviewHref,
  workspaceLabel = "Consultant Workspace",
  publishImmediately = !endpoint,
}: {
  initial: EditableResourceState;
  pathOptions: PathOption[];
  endpoint?: string;
  reviewHref?: string;
  workspaceLabel?: string;
  publishImmediately?: boolean;
}) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [saved, setSaved] = useState(initial);
  const [fields, setFields] = useState(initial.fields);
  const [body, setBody] = useState(bodyText(initial.fields.body));
  const [tagText, setTagText] = useState(topicText(initial.fields.tags));
  const [changeNote, setChangeNote] = useState("");
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [confirmClose, setConfirmClose] = useState(false);
  const keepEditingRef = useRef<HTMLButtonElement>(null);

  // Unsaved edits live only in this component. Warn before the page is left,
  // and ask before the fields are closed, so a draft is never lost silently.
  const dirty = open && (
    JSON.stringify(fields) !== JSON.stringify(saved.fields)
    || body !== bodyText(saved.fields.body)
    || tagText !== topicText(saved.fields.tags)
    || changeNote !== ""
  );
  useEffect(() => {
    if (!dirty) return;
    const guard = (event: BeforeUnloadEvent) => {
      event.preventDefault();
      event.returnValue = "";
    };
    window.addEventListener("beforeunload", guard);
    return () => window.removeEventListener("beforeunload", guard);
  }, [dirty]);
  useEffect(() => {
    if (confirmClose) keepEditingRef.current?.focus();
  }, [confirmClose]);

  function requestClose() {
    if (dirty) {
      setConfirmClose(true);
      return;
    }
    setOpen(false);
  }

  function discardAndClose() {
    restoreSavedDraft();
    setConfirmClose(false);
    setOpen(false);
  }

  function update<K extends keyof EditableResourceFields>(
    key: K,
    value: EditableResourceFields[K],
  ) {
    setFields((current) => ({ ...current, [key]: value }));
  }

  function restoreSavedDraft() {
    setFields(saved.fields);
    setBody(bodyText(saved.fields.body));
    setTagText(topicText(saved.fields.tags));
    setChangeNote("");
    setError("");
    setMessage("");
  }

  async function saveDraft(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setBusy(true);
    setError("");
    setMessage("");
    const nextFields = { ...fields, body: bodyParts(body), tags: topics(tagText) };

    try {
      const response = await fetch(
        endpoint ?? `/api/consultant/resources/${encodeURIComponent(initial.contentItemId)}/draft`,
        {
          method: "PATCH",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({
            expectedRevisionId: saved.expectedRevisionId,
            ...(publishImmediately ? { expectedPublishedRevisionId: saved.publishedRevisionId } : {}),
            fields: nextFields,
            changeNote: changeNote.trim() || null,
          }),
        },
      );
      const result = (await response.json().catch(() => ({}))) as DraftResponse;
      if (!response.ok || !result.draft) {
        setError(result.error ?? "Changes could not be saved. The published resource has not changed.");
        return;
      }
      setSaved(result.draft);
      setFields(result.draft.fields);
      setBody(bodyText(result.draft.fields.body));
      setTagText(topicText(result.draft.fields.tags));
      setChangeNote("");
      setMessage(result.message ?? (publishImmediately ? "Changes saved and published in this application." : "Draft saved for review. Staff still see the current approved version."));
      if (publishImmediately) router.refresh();
    } catch {
      setError("Changes could not be saved. The published resource has not changed.");
    } finally {
      setBusy(false);
    }
  }

  const availablePaths = Array.from(
    new Map(
      [
        ...pathOptions,
        ...fields.pathIds
          .filter((id) => !pathOptions.some((option) => option.id === id))
          .map((id) => ({ id, label: id })),
      ].map((option) => [option.id, option]),
    ).values(),
  );

  return (
    <section className="card mt-8" aria-labelledby="edit-resource-heading">
        <p className="kicker">{workspaceLabel}</p>
      <h2 className="text-xl font-extrabold" id="edit-resource-heading">
        Edit this resource
      </h2>
      <p className="mt-2 mb-0">
        {publishImmediately ? "Save to publish your changes in this One DSD application. Earlier wording remains in the resource history." : "Make changes here without replacing what staff already use. Saving creates a draft that must be reviewed before it can be published."}
      </p>
      {!publishImmediately && saved.hasUnpublishedChanges ? (
        <div className="mt-4">
          <Notice tone="warn">You are editing the most recent draft. Staff still see the current approved version.</Notice>
        </div>
      ) : null}
      {!publishImmediately && saved.hasUnpublishedChanges ? (
        <p className="mt-4 mb-0">
          <Link href={reviewHref ?? `/consultant/resources/${encodeURIComponent(initial.contentItemId)}`}>Review this draft and decide whether to publish it</Link>
        </p>
      ) : null}
      {!open ? (
        <button className="btn btn--primary mt-4" type="button" onClick={() => setOpen(true)}>
          Open editing fields
        </button>
      ) : (
        <form className="mt-6" onSubmit={saveDraft}>
          <div className="grid gap-x-6 md:grid-cols-2">
            <Field id="resource-title" label="Title">
              <input
                id="resource-title"
                type="text"
                value={fields.title}
                maxLength={300}
                required
                onChange={(event) => update("title", event.target.value)}
              />
            </Field>
            <Field id="resource-owner" label="Person or office responsible">
              <input
                id="resource-owner"
                type="text"
                value={fields.owner}
                maxLength={200}
                required
                onChange={(event) => update("owner", event.target.value)}
              />
            </Field>
            <Field id="resource-type" label="Resource type">
              <select
                id="resource-type"
                value={fields.type}
                onChange={(event) => update("type", event.target.value as EditableResourceFields["type"])}
              >
                {EDITABLE_CONTENT_TYPES.map((value) => (
                  <option key={value} value={value}>
                    {CONTENT_TYPE_LABEL[value]}
                  </option>
                ))}
              </select>
            </Field>
            <Field id="resource-authority" label="How staff should understand it">
              <select
                id="resource-authority"
                value={fields.authority}
                onChange={(event) => update("authority", event.target.value as EditableResourceFields["authority"])}
              >
                {EDITABLE_AUTHORITIES.map((value) => (
                  <option key={value} value={value}>
                    {AUTHORITY[value].label || "Held back from staff"}
                  </option>
                ))}
              </select>
            </Field>
            <Field id="resource-layer" label="Level of detail">
              <select
                id="resource-layer"
                value={fields.layer}
                onChange={(event) => update("layer", event.target.value as EditableResourceFields["layer"])}
              >
                {EDITABLE_LAYERS.map((value) => (
                  <option key={value} value={value}>
                    {LAYER_LABEL[value]}
                  </option>
                ))}
              </select>
            </Field>
            <Field id="resource-scope" label="Where this applies">
              <select
                id="resource-scope"
                value={fields.scope}
                disabled
              >
                <option value={fields.scope}>{fields.scope === "dsd" ? "Disability Services Division" : "DHS agency-wide resource"}</option>
              </select>
            </Field>
            <Field id="resource-review-date" label="Review date">
              <input
                id="resource-review-date"
                type="date"
                value={fields.reviewDate}
                required
                onChange={(event) => update("reviewDate", event.target.value)}
              />
            </Field>
          </div>

          <Field id="resource-summary" label="Short overview">
            <textarea
              id="resource-summary"
              value={fields.summary}
              maxLength={2_000}
              required
              rows={3}
              onChange={(event) => update("summary", event.target.value)}
            />
          </Field>
          <Field id="resource-why" label="Why this matters">
            <textarea
              id="resource-why"
              value={fields.whyItMatters ?? ""}
              maxLength={3_000}
              rows={3}
              onChange={(event) => update("whyItMatters", event.target.value || null)}
            />
          </Field>
          <Field
            id="resource-body"
            label="Resource content"
            help="Leave a blank line between each paragraph or list item."
          >
            <textarea
              id="resource-body"
              value={body}
              maxLength={100_000}
              required
              rows={12}
              onChange={(event) => setBody(event.target.value)}
            />
          </Field>

          <fieldset className="panel mb-4">
            <legend className="font-bold text-navy-deep">What this resource helps staff do</legend>
            <div className="checks mt-3 sm:grid-cols-2">
              {EDITABLE_INTENTS.map((intent) => (
                <label key={intent}>
                  <input
                    type="checkbox"
                    checked={fields.intents.includes(intent)}
                    onChange={(event) =>
                      update(
                        "intents",
                        event.target.checked
                          ? Array.from(new Set([...fields.intents, intent]))
                          : fields.intents.filter((value) => value !== intent),
                      )
                    }
                  />
                  <span>{INTENT_LABELS[intent]}</span>
                </label>
              ))}
            </div>
          </fieldset>

          <Field id="resource-tags" label="Topics" help="Separate topics with commas or place each one on its own line.">
            <textarea
              id="resource-tags"
              value={tagText}
              maxLength={5_000}
              rows={3}
              onChange={(event) => setTagText(event.target.value)}
            />
          </Field>

          <fieldset className="panel mb-4">
            <legend className="font-bold text-navy-deep">Learning paths</legend>
            <div className="checks mt-3">
              {availablePaths.map((path) => (
                <label key={path.id}>
                  <input
                    type="checkbox"
                    checked={fields.pathIds.includes(path.id)}
                    onChange={(event) =>
                      update(
                        "pathIds",
                        event.target.checked
                          ? Array.from(new Set([...fields.pathIds, path.id]))
                          : fields.pathIds.filter((value) => value !== path.id),
                      )
                    }
                  />
                  <span>{path.label}</span>
                </label>
              ))}
            </div>
          </fieldset>

          <fieldset className="panel mb-4">
            <legend className="font-bold text-navy-deep">Next steps shown with this resource</legend>
            <div className="mt-3 space-y-4">
              {fields.nextActions.map((action, index) => (
                <div className="grid gap-x-4 border-b border-line pb-4 md:grid-cols-[1fr_1fr_auto]" key={index}>
                  <Field id={`next-step-label-${index}`} label="Link wording">
                    <input
                      id={`next-step-label-${index}`}
                      type="text"
                      value={action.label}
                      maxLength={200}
                      required
                      onChange={(event) =>
                        update(
                          "nextActions",
                          fields.nextActions.map((current, currentIndex) =>
                            currentIndex === index ? { ...current, label: event.target.value } : current,
                          ),
                        )
                      }
                    />
                  </Field>
                  <Field id={`next-step-address-${index}`} label="Program path or secure web address">
                    <input
                      id={`next-step-address-${index}`}
                      type="text"
                      value={action.href}
                      maxLength={2_000}
                      required
                      onChange={(event) =>
                        update(
                          "nextActions",
                          fields.nextActions.map((current, currentIndex) =>
                            currentIndex === index ? { ...current, href: event.target.value } : current,
                          ),
                        )
                      }
                    />
                  </Field>
                  <button
                    className="btn btn--light self-end mb-4"
                    type="button"
                    onClick={() => update("nextActions", fields.nextActions.filter((_, currentIndex) => currentIndex !== index))}
                  >
                    Remove this step
                  </button>
                </div>
              ))}
            </div>
            <button
              className="btn btn--light mt-3"
              type="button"
              onClick={() => update("nextActions", [...fields.nextActions, { label: "", href: "" }])}
            >
              Add another step
            </button>
          </fieldset>

          <div className="grid gap-x-6 md:grid-cols-2">
            <Field id="resource-source-name" label="Public source name, if used">
              <input
                id="resource-source-name"
                type="text"
                value={fields.sourceName ?? ""}
                maxLength={300}
                onChange={(event) => update("sourceName", event.target.value || null)}
              />
            </Field>
            <Field id="resource-source-address" label="Public source address, if used" help="Use a secure web address beginning with https://.">
              <input
                id="resource-source-address"
                type="url"
                value={fields.href ?? ""}
                maxLength={2_000}
                onChange={(event) => update("href", event.target.value || null)}
              />
            </Field>
          </div>
          <Field id="resource-change-note" label="Note about this change" help="Optional. Use this to explain what you changed.">
            <textarea
              id="resource-change-note"
              value={changeNote}
              maxLength={500}
              rows={2}
              onChange={(event) => setChangeNote(event.target.value)}
            />
          </Field>

          {error ? (
            <p className="error" role="alert">
              {error}
            </p>
          ) : null}
          {message ? (
            <p className="notice" role="status">
              {message}
            </p>
          ) : null}

          <div className="flex flex-wrap gap-3">
            <button className="btn btn--primary" type="submit" disabled={busy}>
              {busy ? "Saving changes" : publishImmediately ? "Save and publish" : "Save draft for review"}
            </button>
            <button className="btn btn--light" type="button" disabled={busy} onClick={restoreSavedDraft}>
              {publishImmediately ? "Restore saved wording" : "Restore saved draft"}
            </button>
            <button className="text-button" type="button" disabled={busy} onClick={requestClose}>
              Close editing fields
            </button>
          </div>
          {confirmClose ? (
            <div className="notice notice--warn mt-4" role="alertdialog" aria-modal="false" aria-labelledby="resource-close-confirm-title" aria-describedby="resource-close-confirm-text">
              <p className="m-0 font-bold" id="resource-close-confirm-title">You have unsaved changes</p>
              <p className="mt-1 mb-0" id="resource-close-confirm-text">Closing the editing fields will discard them. The saved draft is not affected.</p>
              <div className="mt-3 flex flex-wrap gap-3">
                <button className="btn btn--light" type="button" ref={keepEditingRef} onClick={() => setConfirmClose(false)}>Keep editing</button>
                <button className="btn btn--primary" type="button" onClick={discardAndClose}>Discard changes and close</button>
              </div>
            </div>
          ) : null}
        </form>
      )}
    </section>
  );
}

import { SourceLink } from "@/components/app-link";
import { FeaturedMediaPanel } from "@/components/featured-media-panel";
import { listResourceMedia, mediaAvailable, videoEmbedUrl, type ResourceMediaItem } from "@/lib/content/media";
import { ResourceMediaManager } from "@/components/resource-media-manager";
import { SyncedAudio } from "@/components/synced-audio";
import type { ReactNode } from "react";

/**
 * Images, infographics, video, and documents attached to a resource. Shown to
 * everyone. The consultant also sees controls to add and delete items.
 */
export async function ResourceMediaGallery({ contentItemId, owner, visualFallback }: { contentItemId: string; owner: boolean; visualFallback?: ReactNode }) {
  let items: ResourceMediaItem[] = [];
  // Keep connection diagnostics in logs and owner controls, not staff resource pages.
  let unavailable: "not-connected" | "failed" | null = mediaAvailable() ? null : "not-connected";
  if (!unavailable) {
    try {
      items = await listResourceMedia(contentItemId);
    } catch (error) {
      unavailable = "failed";
      console.error("Resource media could not be read.", error instanceof Error ? error.message : error);
    }
  }
  if (items.length === 0 && !owner) return visualFallback ?? null;
  const audio = items.filter((item) => item.kind === "audio");
  const visual = items.filter((item) => item.kind !== "audio");
  const showVisualHeading = visual.length > 0 || owner;
  const headingId = `resource-media-${contentItemId}`;
  const noticeId = `resource-media-notice-${contentItemId}`;

  return <>
    {!items.some(item => item.kind === "image" || item.kind === "video") ? visualFallback : null}
    <section className="mt-6" aria-labelledby={showVisualHeading ? headingId : unavailable ? noticeId : `resource-listen-${contentItemId}`} data-resource-media="true">
      {unavailable ? (
        <p id={noticeId} className="notice notice--warn" role="status" data-resource-media-unavailable={unavailable}>
          {unavailable === "failed"
            ? "Attached files are temporarily unavailable."
            : "Attached files are unavailable."}
        </p>
      ) : null}
      {audio.length > 0 ? (
        <FeaturedMediaPanel kind="audio" label="Listen"><div data-resource-listen="true">
          <h2 id={`resource-listen-${contentItemId}`} className="m-0 text-xl font-extrabold">Listen to this resource</h2>
          {audio.map((item) => (
            <figure key={item.id} className="m-0 mt-3">
              {item.script && item.script.length > 0
                ? <SyncedAudio src={item.mediaId ? `/api/media/${item.mediaId}` : item.externalUrl ?? ""} title={item.title || "Read aloud"} script={item.script} />
                : <audio controls preload="none" src={item.mediaId ? `/api/media/${item.mediaId}` : item.externalUrl ?? undefined} style={{ width: "100%" }} aria-label={item.title || "Read aloud"} />}
              {item.title ? <figcaption className="mt-1 text-sm">{item.title}</figcaption> : null}
              {owner ? <ResourceMediaManager contentItemId={contentItemId} deleteId={item.id} deleteTitle={item.title || item.fileName || "audio"} /> : null}
            </figure>
          ))}
        </div></FeaturedMediaPanel>
      ) : null}
      {showVisualHeading ? <h2 id={headingId} className="mt-6 text-xl font-extrabold">Images, video, and documents</h2> : null}
      <div className="mt-4 grid gap-6" style={{ gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))" }}>
        {visual.map((item) => (
          <figure key={item.id} className="m-0" style={{ position: "relative" }}>
            <MediaBody item={item} />
            {item.title ? <figcaption className="mt-2 text-sm">{item.title}</figcaption> : null}
            {owner ? <ResourceMediaManager contentItemId={contentItemId} deleteId={item.id} deleteTitle={item.title || item.fileName || item.kind} /> : null}
          </figure>
        ))}
      </div>
      {owner ? <ResourceMediaManager contentItemId={contentItemId} /> : null}
    </section>
  </>;
}

function MediaBody({ item }: { item: ResourceMediaItem }) {
  const fileUrl = item.mediaId ? `/api/media/${item.mediaId}` : null;
  if (item.kind === "image" && fileUrl) {
    // eslint-disable-next-line @next/next/no-img-element
    return <img loading="lazy" decoding="async" src={fileUrl} alt={item.alt || item.title} style={{ width: "100%", height: "auto", borderRadius: 12 }} />;
  }
  if (item.kind === "video") {
    const embed = item.externalUrl ? videoEmbedUrl(item.externalUrl) : null;
    if (embed) {
      return (
        <div style={{ position: "relative", paddingTop: "56.25%", borderRadius: 12, overflow: "hidden", background: "#000" }}>
          <iframe loading="lazy" src={embed} title={item.title || "Video"} allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen style={{ position: "absolute", inset: 0, width: "100%", height: "100%", border: 0 }} />
        </div>
      );
    }
    if (fileUrl) return <video controls preload="none" src={fileUrl} style={{ width: "100%", borderRadius: 12, background: "#000" }} aria-label={item.title || "Video"} />;
    if (item.externalUrl) return <SourceLink href={item.externalUrl} target="_blank" rel="noreferrer">Watch: {item.title || item.externalUrl}</SourceLink>;
  }
  if (item.kind === "document") {
    const href = fileUrl ?? item.externalUrl ?? "#";
    return <SourceLink className="btn" href={href} target="_blank" rel="noreferrer">Open {item.title || item.fileName || "document"}</SourceLink>;
  }
  if (fileUrl) return <SourceLink href={fileUrl} target="_blank" rel="noreferrer">Open {item.title || item.fileName || "file"}</SourceLink>;
  return null;
}

"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";

type Kind = "audio" | "image" | "video" | "document";

/**
 * Consultant controls for a resource's media. With `deleteId` it renders a
 * Delete button for one item; otherwise it renders the add form.
 */
export function ResourceMediaManager({ contentItemId, deleteId, deleteTitle }: { contentItemId: string; deleteId?: string; deleteTitle?: string }) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [kind, setKind] = useState<Kind>("image");
  const [videoSource, setVideoSource] = useState<"link" | "file">("link");
  const endpoint = `/api/consultant/resources/${encodeURIComponent(contentItemId)}/media`;

  const remove = async () => {
    if (!deleteId) return;
    if (!window.confirm(`Delete "${deleteTitle ?? "this item"}" from this resource?`)) return;
    setBusy(true);
    setError("");
    try {
      const response = await fetch(endpoint, { method: "DELETE", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: deleteId }) });
      const body = await response.json();
      if (!response.ok) throw new Error(body.error ?? "The item could not be deleted.");
      router.refresh();
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "The item could not be deleted.");
    } finally {
      setBusy(false);
    }
  };

  if (deleteId) {
    return (
      <div className="mt-2">
        <button type="button" onClick={() => void remove()} disabled={busy} style={{ border: "1px solid #b42318", color: "#fff", background: "#b42318", borderRadius: 8, fontWeight: 700, cursor: "pointer", padding: "4px 10px", fontSize: 13 }}>
          {busy ? "Deleting…" : "Delete"}
        </button>
        {error ? <p role="alert" className="mt-1 text-sm">{error}</p> : null}
      </div>
    );
  }

  const submit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    form.set("kind", kind);
    const file = form.get("file");
    const link = String(form.get("url") ?? "").trim();
    if (kind === "video" && videoSource === "link") {
      form.delete("file");
      if (!link) { setError("Paste the link to the video."); return; }
    } else {
      form.delete("url");
      if (!(file instanceof File) || file.size === 0) { setError("Choose a file."); return; }
      if (file.size > 4 * 1024 * 1024) { setError("Files can be up to 4 MB. For a larger video, paste a link to it instead."); return; }
    }
    setBusy(true);
    setError("");
    try {
      const response = await fetch(endpoint, { method: "POST", body: form });
      const body = await response.json();
      if (!response.ok) throw new Error(body.error ?? "The item could not be added.");
      (event.target as HTMLFormElement).reset();
      router.refresh();
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "The item could not be added.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <form className="card mt-6" onSubmit={(event) => void submit(event)} data-resource-media-add="true" aria-labelledby={`media-add-heading-${contentItemId}`}>
      <h3 className="m-0 text-lg font-extrabold" id={`media-add-heading-${contentItemId}`}>Add audio, an image, a video, or a document</h3>
      <div className="field mt-3">
        <label htmlFor={`media-kind-${contentItemId}`}>What are you adding?</label>
        <select id={`media-kind-${contentItemId}`} name="kind" value={kind} onChange={(event) => setKind(event.target.value as Kind)}>
          <option value="audio">Audio: read-aloud in your voice</option>
          <option value="image">Image or infographic</option>
          <option value="video">Video</option>
          <option value="document">Document (PDF, Word, PowerPoint, Excel)</option>
        </select>
      </div>
      {kind === "video" ? (
        <div className="field">
          <span>Where is the video?</span>
          <label><input type="radio" name="videoSource" checked={videoSource === "link"} onChange={() => setVideoSource("link")} /> A link (YouTube, Vimeo, SharePoint, or another site)</label>
          <label><input type="radio" name="videoSource" checked={videoSource === "file"} onChange={() => setVideoSource("file")} /> A file on this computer (up to 4 MB)</label>
        </div>
      ) : null}
      {kind === "video" && videoSource === "link" ? (
        <div className="field">
          <label htmlFor={`media-url-${contentItemId}`}>Video link</label>
          <input id={`media-url-${contentItemId}`} name="url" type="url" placeholder="https://" />
        </div>
      ) : (
        <div className="field">
          <label htmlFor={`media-file-${contentItemId}`}>File (up to 4 MB)</label>
          <input id={`media-file-${contentItemId}`} name="file" type="file" accept={kind === "audio" ? "audio/*,.m4a,.mp3,.wav" : kind === "image" ? "image/*" : kind === "video" ? "video/*" : ".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt,application/pdf"} />
        </div>
      )}
      <div className="field">
        <label htmlFor={`media-title-${contentItemId}`}>Caption or title (optional)</label>
        <input id={`media-title-${contentItemId}`} name="title" type="text" maxLength={300} />
      </div>
      {kind === "image" ? (
        <div className="field">
          <label htmlFor={`media-alt-${contentItemId}`}>Describe the image for people using screen readers</label>
          <input id={`media-alt-${contentItemId}`} name="alt" type="text" maxLength={2000} />
        </div>
      ) : null}
      <button type="submit" className="btn btn--primary" disabled={busy}>{busy ? "Adding…" : "Add to this resource"}</button>
      {error ? <p role="alert" className="mt-2 text-sm">{error}</p> : null}
    </form>
  );
}

"use client";

import Link from "@/components/app-link";
import { useState } from "react";
import { Notice } from "@/components/ui";
import {
  RESOURCE_REVIEW_DECISION_LABELS,
  RESOURCE_REVIEW_DECISIONS,
  RESOURCE_REVIEW_LABELS,
  RESOURCE_STAFF_SENSITIVITY_CLASSES,
  RESOURCE_STAFF_SENSITIVITY_LABELS,
  type ResourceReleaseAction,
  type ResourceReleaseState,
} from "@/lib/content/resource-release-contract";

type ReleaseResponse = {
  ok?: boolean;
  release?: ResourceReleaseState;
  message?: string;
  error?: string;
};

function dateText(value: string) {
  return new Intl.DateTimeFormat("en-US", {
    dateStyle: "medium",
    timeZone: "America/Chicago",
  }).format(new Date(value));
}

export function ResourceReleaseClient({
  initial, endpoint, canReview = true, canPublish = true, canWithdraw = true, editHref,
}: {
  initial: ResourceReleaseState; endpoint?: string;
  canReview?: boolean; canPublish?: boolean; canWithdraw?: boolean; editHref?: string;
}) {
  const [release, setRelease] = useState(initial);
  const [reason, setReason] = useState("");
  const [sensitivityClass, setSensitivityClass] = useState<"" | "S0" | "S1">("");
  const [exposureApproved, setExposureApproved] = useState(false);
  const [exposureReason, setExposureReason] = useState("");
  const [busy, setBusy] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  async function act(action: ResourceReleaseAction, busyKey: string) {
    if ((action.action === "review" && !canReview) || (action.action === "withdraw" && !canWithdraw) || (["publish", "republish"].includes(action.action) && !canPublish)) return;
    setBusy(busyKey);
    setMessage("");
    setError("");
    try {
      const response = await fetch(
        endpoint ?? `/api/consultant/resources/${encodeURIComponent(release.contentItemId)}/release`,
        {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify(action),
        },
      );
      const result = (await response.json().catch(() => ({}))) as ReleaseResponse;
      if (!response.ok || !result.release) {
        setError(result.error ?? "That change could not be completed.");
        return;
      }
      setRelease(result.release);
      setReason("");
      setSensitivityClass("");
      setExposureApproved(false);
      setExposureReason("");
      setMessage(result.message ?? "The resource review has been updated.");
    } catch {
      setError("That change could not be completed right now.");
    } finally {
      setBusy("");
    }
  }

  function saveReview(event: React.FormEvent<HTMLFormElement>, dimension: string) {
    event.preventDefault();
    if (!release.draft) return;
    const currentReview = release.draft.reviews.find((review) => review.dimension === dimension);
    if (!currentReview) {
      setError("Reload this page before saving the review.");
      return;
    }
    const values = new FormData(event.currentTarget);
    const decision = String(values.get("decision"));
    const note = String(values.get("note") ?? "").trim();
    if (!RESOURCE_REVIEW_DECISIONS.includes(decision as (typeof RESOURCE_REVIEW_DECISIONS)[number])) {
      setError("Choose a review decision.");
      return;
    }
    void act(
      {
        action: "review",
        revisionId: release.draft.revisionId,
        dimension: dimension as keyof typeof RESOURCE_REVIEW_LABELS,
        decision: decision as keyof typeof RESOURCE_REVIEW_DECISION_LABELS,
        expectedPriorReviewId: currentReview.reviewId,
        note: note || null,
      },
      `review-${dimension}`,
    );
  }

  const published = release.published?.payload;
  const draft = release.draft;
  const staffExposureDecisionReady = Boolean(
    sensitivityClass && exposureApproved && exposureReason.trim(),
  );

  function staffExposureDecisionFields(legend: string) {
    return (
      <fieldset className="panel mt-4">
        <legend className="font-bold">{legend}</legend>
        <p className="mt-2 text-sm">
          Choose the reviewed classification and record why this resource may be shown at the
          program&apos;s staff-facing web address without sign-in.
        </p>
        <label className="field">
          <span>Content classification</span>
          <select
            value={sensitivityClass}
            onChange={(event) => setSensitivityClass(event.target.value as "" | "S0" | "S1")}
            required
          >
            <option value="">Choose a classification</option>
            {RESOURCE_STAFF_SENSITIVITY_CLASSES.map((value) => (
              <option key={value} value={value}>
                {value}: {RESOURCE_STAFF_SENSITIVITY_LABELS[value]}
              </option>
            ))}
          </select>
        </label>
        <label className="field">
          <span>Why access without sign-in is appropriate</span>
          <textarea
            value={exposureReason}
            onChange={(event) => setExposureReason(event.target.value)}
            rows={2}
            maxLength={500}
            required
          />
        </label>
        <label className="mt-3 flex items-start gap-3">
          <input
            type="checkbox"
            checked={exposureApproved}
            onChange={(event) => setExposureApproved(event.target.checked)}
          />
          <span>
            I approve showing this reviewed resource without sign-in at the program&apos;s
            staff-facing web address.
          </span>
        </label>
      </fieldset>
    );
  }

  return (
    <div className="wrap py-8">
      <p>
        <Link href={`/resources/${encodeURIComponent(release.contentItemId)}`}>
          Open the staff resource
        </Link>
      </p>

      {editHref ? <p><Link href={editHref}>Prepare a resource draft</Link></p> : null}
      {message ? <p className="notice" role="status">{message}</p> : null}
      {error ? <p className="error" role="alert">{error}</p> : null}

      {release.withdrawn ? (
        <Notice tone="warn">
          {release.published?.isInherited
            ? "The Disability Services Division version has been withdrawn. Staff still see the agencywide version."
            : "This resource has been withdrawn from this program view. Its approved history is still available below."}
        </Notice>
      ) : null}
      {release.published?.isInherited ? (
        <Notice>
          The agencywide version is shown here. A Disability Services Division draft can build on it without changing the agencywide resource.
        </Notice>
      ) : null}

      {draft ? (
        <>
          <section className="card mt-6" aria-labelledby="compare-resource-heading">
            <p className="kicker">Review changes</p>
            <h2 className="text-xl font-extrabold" id="compare-resource-heading">
              Compare the staff version and the draft
            </h2>
            <p className="mt-2">The staff version will not change until every required review is complete and you choose to publish.</p>
            <div className="mt-5 grid gap-6 lg:grid-cols-2">
              <div className="panel">
                <h3 className="text-lg font-bold">Current staff version</h3>
                {published ? (
                  <>
                    <p className="font-bold">{published.title}</p>
                    <p>{published.summary}</p>
                    <div className="space-y-2">
                      {published.body.map((part, index) => <p className="m-0" key={`published-${index}`}>{part}</p>)}
                    </div>
                  </>
                ) : (
                  <p className="m-0">There is no current staff version in this program view.</p>
                )}
              </div>
              <div className="panel">
                <h3 className="text-lg font-bold">Draft version</h3>
                <p className="font-bold">{draft.payload.title}</p>
                <p>{draft.payload.summary}</p>
                <div className="space-y-2">
                  {draft.payload.body.map((part, index) => <p className="m-0" key={`draft-${index}`}>{part}</p>)}
                </div>
                <p className="mt-4 mb-0 text-sm">
                  Applies to: {draft.payload.scope === "dsd" ? "Disability Services Division" : "DHS agency-wide resource"}. Maintained by {draft.payload.owner}.
                </p>
              </div>
            </div>
          </section>

          <section className="card mt-6" aria-labelledby="required-reviews-heading">
            <p className="kicker">Required reviews</p>
            <h2 className="text-xl font-extrabold" id="required-reviews-heading">
              Record each decision
            </h2>
            <p className="mt-2">A resource can be published only when every review is complete or does not apply.</p>
            <div className="mt-5 space-y-5">
              {draft.requiredReviewDimensions.map((dimension) => {
                const current = draft.reviews.find((review) => review.dimension === dimension);
                return (
                  <form
                    className="panel"
                    key={`${dimension}-${current?.reviewId ?? "missing"}`}
                    onSubmit={(event) => saveReview(event, dimension)}
                  >
                    <h3 className="text-lg font-bold">{RESOURCE_REVIEW_LABELS[dimension]}</h3>
                    <p className="text-sm">
                      Current decision: {current ? (current.status === "pending" ? "Not reviewed" : RESOURCE_REVIEW_DECISION_LABELS[current.status]) : "Not reviewed"}
                      {current?.recordedAt ? `. Saved ${dateText(current.recordedAt)}.` : "."}
                    </p>
                    {current?.note ? <p className="text-sm">Latest note: {current.note}</p> : null}
                    <fieldset disabled={!canReview || Boolean(busy)}><legend className="sr-only">Record this review</legend><div className="grid gap-4 md:grid-cols-2">
                      <label className="field">
                        <span>Decision</span>
                        <select name="decision" defaultValue={current?.status === "pending" ? "pass" : current?.status ?? "pass"}>
                          {RESOURCE_REVIEW_DECISIONS.map((decision) => (
                            <option key={decision} value={decision}>{RESOURCE_REVIEW_DECISION_LABELS[decision]}</option>
                          ))}
                        </select>
                      </label>
                      <label className="field">
                        <span>Review note</span>
                        <textarea name="note" rows={2} maxLength={2_000} defaultValue={current?.note ?? ""} />
                      </label>
                    </div>
                    <button className="btn btn--light" type="submit" disabled={Boolean(busy)}>
                      {busy === `review-${dimension}` ? "Saving decision" : "Save this review"}
                    </button></fieldset>
                  </form>
                );
              })}
            </div>
          </section>

          {canPublish ? <section className="card mt-6" aria-labelledby="publish-resource-heading">
            <p className="kicker">Staff release</p>
            <h2 className="text-xl font-extrabold" id="publish-resource-heading">
              Publish the reviewed resource
            </h2>
            {draft.readyToPublish ? (
              <Notice>Every required review is complete. The wording and presentation will be checked once more before staff see it.</Notice>
            ) : (
              <Notice tone="warn">Finish every required review before publishing.</Notice>
            )}
            <label className="field mt-4">
              <span>Reason for publishing</span>
              <textarea value={reason} onChange={(event) => setReason(event.target.value)} rows={2} maxLength={500} required />
            </label>
            {staffExposureDecisionFields("Staff access decision")}
            <button
              className="btn btn--primary"
              type="button"
              disabled={Boolean(busy) || !draft.readyToPublish || !reason.trim() || !staffExposureDecisionReady}
              onClick={() => {
                if (!sensitivityClass || !exposureApproved || !exposureReason.trim()) return;
                void act({
                  action: "publish",
                  revisionId: draft.revisionId,
                  expectedScopeDecisionId: release.scopeDecisionId,
                  reason: reason.trim(),
                  sensitivityClass,
                  unauthenticatedExposurePermitted: true,
                  exposureReason: exposureReason.trim(),
                }, "publish");
              }}
            >
              {busy === "publish" ? "Publishing resource" : "Publish this reviewed resource"}
            </button>
          </section> : null}
        </>
      ) : (
        <div className="card mt-6">
          <p className="kicker">Review changes</p>
          <h2 className="text-xl font-extrabold">No draft is waiting for review</h2>
          <p className="m-0">{editHref ? <Link href={editHref}>Prepare a new draft</Link> : endpoint ? "Published versions remain available below." : "Open the staff resource to prepare a new draft."}</p>
        </div>
      )}

      {canWithdraw && release.published && !release.published.isInherited ? (
        <section className="card mt-6" aria-labelledby="withdraw-resource-heading">
          <p className="kicker">Availability</p>
          <h2 className="text-xl font-extrabold" id="withdraw-resource-heading">Withdraw the current staff version</h2>
          <p>Withdrawal removes this resource from the current program view without deleting its history. A previously approved version can be restored later.</p>
          <label className="field">
            <span>Reason for withdrawal</span>
            <textarea value={reason} onChange={(event) => setReason(event.target.value)} rows={2} maxLength={500} required />
          </label>
          <button
            className="btn btn--light"
            type="button"
            disabled={Boolean(busy) || !reason.trim()}
            onClick={() => void act({
              action: "withdraw",
              revisionId: release.published!.revisionId,
              expectedScopeDecisionId: release.scopeDecisionId,
              reason: reason.trim(),
            }, "withdraw")}
          >
            {busy === "withdraw" ? "Withdrawing resource" : "Withdraw this resource"}
          </button>
        </section>
      ) : null}

      <section className="card mt-6" aria-labelledby="resource-history-heading">
        <p className="kicker">Approved history</p>
        <h2 className="text-xl font-extrabold" id="resource-history-heading">Previously published versions</h2>
        {release.history.length ? (
          <div className="mt-4 space-y-4">
            {release.history.map((version) => (
              <div className="panel" key={version.revisionId}>
                <h3 className="text-lg font-bold">{version.title}</h3>
                <p className="text-sm">
                  Version {version.revisionNumber}. Published {dateText(version.decidedAt)}. {version.isInherited ? "Agencywide version." : "This program's version."} {version.isCurrent ? "This is the current staff version." : version.isInherited ? "It remains read-only here." : "This version can be restored."}
                </p>
                {canPublish && !version.isCurrent && !version.isInherited ? (
                  <button
                    className="btn btn--light"
                    type="button"
                    disabled={Boolean(busy) || !reason.trim() || !staffExposureDecisionReady}
                    onClick={() => {
                      if (!sensitivityClass || !exposureApproved || !exposureReason.trim()) return;
                      void act({
                        action: "republish",
                        revisionId: version.revisionId,
                        expectedScopeDecisionId: release.scopeDecisionId,
                        reason: reason.trim(),
                        sensitivityClass,
                        unauthenticatedExposurePermitted: true,
                        exposureReason: exposureReason.trim(),
                      }, `restore-${version.revisionId}`);
                    }}
                  >
                    {busy === `restore-${version.revisionId}` ? "Restoring version" : "Restore this approved version"}
                  </button>
                ) : null}
              </div>
            ))}
          </div>
        ) : <p className="m-0">No published history is available.</p>}
        {canPublish && release.history.some((version) => !version.isCurrent && !version.isInherited) ? (
          <>
            <label className="field mt-4">
              <span>Reason for restoring a previous version</span>
              <textarea value={reason} onChange={(event) => setReason(event.target.value)} rows={2} maxLength={500} required />
            </label>
            {staffExposureDecisionFields("Restored staff access decision")}
          </>
        ) : null}
      </section>
    </div>
  );
}

