                </div>
                <details className="mt-5 border-t border-[#d7dddf] pt-4">
                  <summary className="cursor-pointer text-sm font-bold text-navy">Read the scene dialogue</summary>
                  <ol className="mb-0 mt-4 space-y-3 pl-5 text-sm leading-6">
